import{n as e}from"./rolldown-runtime-BgaNhQyE.js";function t(e){return e===r.id}function ee(e){if(e)return n.find(t=>t.id===e||t.date===e)}function te(e){return`/daily/${e.id}`}var n,r,i=e((()=>{n=[{id:`2026-11-16-alphaproof-code-signal-verification`,date:`2026-11-16`,url:`https://google-deepmind.github.io/code-verification/`,title:`AlphaProof Code: Verifying Signal's Security at the Machine-Code Level`,authors:`Swarat Chaudhuri, Andrew Ferraiuolo, Anton Kovsharov, Tej Chajed, Sam Schlesinger, Karn Seth, Jonathan Katz, Charles Sutton, and Pushmeet Kohli`,venue:`Google DeepMind, 2026`,lane:`AI Research`,difficulty:`Medium`,readTime:`8 min`,description:`AlphaProof Code lets untrusted AI agents generate millions of lines of Lean proof while an exact comparator and small kernel decide what counts. Follow the human-approved specification, proof campaigns, compiled AArch64 target, trusted base, known-bug probes, and the boundary around the reported Signal security guarantee.`,learns:[`Why unreliable proof agents can remain outside the trusted base when a fresh Lean kernel checks the exact approved theorem.`,`How the proof connects a pinned AArch64 libsignal-cli binary to symbolic and computational security games without trusting rustc.`,`Which definitions, assumptions, hooks, environment limits, and artifact-version details remain inside the guarantee's boundary.`],explore:{label:`Compare learned process verification`,href:`/daily/2026-10-18-lets-verify-step-by-step`,description:`Contrast Lean's deterministic proof checker with a learned process reward model that scores intermediate reasoning steps statistically.`},preview:{badge:`SPEC / PROOF / GATEKEEPER`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-11-14-test-time-compute-scaling`,date:`2026-11-14`,url:`https://arxiv.org/abs/2408.03314`,title:`Scaling LLM Test-Time Compute Optimally can be More Effective than Scaling Model Parameters`,authors:`Charlie Snell, Jaehoon Lee, Kelvin Xu, and Aviral Kumar`,venue:`ICLR 2025`,lane:`AI Research`,difficulty:`Medium`,readTime:`9 min`,description:`More inference compute only helps when it is spent in the right shape. Follow a difficulty-aware router that chooses between independent samples, sequential revisions, and process-reward search, then read the fourfold efficiency result and the boundary on the hardest problems.`,learns:[`Why model-specific difficulty predicts whether extra compute should buy fresh attempts, revisions of one route, or verifier-guided search.`,`How the paper's routed revision policy beats 256 parallel samples with 64 samples in its displayed MATH comparison.`,`Why the comparison with a roughly fourteen-times-larger model depends on problem difficulty, workload volume, proprietary checkpoints, and an uncharged routing cost.`],explore:{label:`Inspect process verification`,href:`/daily/2026-10-18-lets-verify-step-by-step`,description:`See how step-level supervision trains the process reward model that this paper later uses to guide search through partial solutions.`},preview:{badge:`BUDGET / DIFFICULTY / ROUTING`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-11-13-dinov2-visual-features`,date:`2026-11-13`,url:`https://arxiv.org/abs/2304.07193v2`,title:`DINOv2: Learning Robust Visual Features without Supervision`,authors:`Maxime Oquab et al.`,venue:`TMLR 2024`,lane:`AI Research`,difficulty:`Medium`,readTime:`15 min`,description:`DINOv2 trains one visual backbone to preserve both whole-image meaning and patch-level structure without captions or class labels. Follow LVD-142M curation, the moving teacher, masked patch targets, feature spreading, frozen-transfer evidence, and the data and bias boundaries around general-purpose features.`,learns:[`How visually retrieved web images turn a 1.2-billion-image pool into the curated LVD-142M pretraining set.`,`Why crop-level self-distillation, masked patch prediction, and KoLeo feature spreading protect different uses of one representation.`,`What frozen linear probes, dense prediction heads, distillation ablations, and the Dollar Street audit establish, and what private data still prevents reproducing.`],explore:{label:`Compare image-text supervision`,href:`/daily/2026-08-23-clip-natural-language-supervision`,description:`Contrast DINOv2's image-only crop and patch targets with CLIP's alignment between an image and its natural-language caption.`},preview:{badge:`CROPS / PATCHES / FEATURES`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-11-12-artificial-hivemind-homogeneity`,date:`2026-11-12`,url:`https://arxiv.org/abs/2510.22954v2`,title:`Artificial Hivemind: The Open-Ended Homogeneity of Language Models (and Beyond)`,authors:`Liwei Jiang, Yuanjun Chai, Margaret Li, Mickel Liu, Raymond Fok, Nouha Dziri, Yulia Tsvetkov, Maarten Sap, Alon Albalak, and Yejin Choi`,venue:`NeurIPS 2025 Best Paper`,lane:`AI Research`,difficulty:`Medium`,readTime:`15 min`,description:`Many language models repeatedly land on the same small set of ideas for open-ended prompts. Follow Infinity-Chat, the within-model and across-model similarity measurements, the human study, and a 2026 critique showing why the null baseline changes the strength of the claim.`,learns:[`How fifty samples, response embeddings, and pairwise cosine similarity turn a cloud of open-ended answers into a homogeneity measurement.`,`Why high overlap appears within one model and across model families, even under more aggressive sampling settings.`,`How a same-prompt, different-idea null weakens the headline interpretation without erasing the residual effect, and what a production diversity audit should measure next.`],explore:{label:`Compare metric sensitivity`,href:`/daily/2026-10-16-emergent-abilities-mirage`,description:`See another case where a measurement choice changes the apparent shape of a language-model capability.`},preview:{badge:`IDEA OVERLAP`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-11-11-generative-agents-memory-reflection`,date:`2026-11-11`,url:`https://arxiv.org/abs/2304.03442v2`,title:`Generative Agents: Interactive Simulacra of Human Behavior`,authors:`Joon Sung Park, Joseph C. O'Brien, Carrie J. Cai, Meredith Ringel Morris, Percy Liang, and Michael S. Bernstein`,venue:`UIST 2023`,lane:`AI Research`,difficulty:`Medium`,readTime:`12 min`,description:`Generative Agents makes long-term memory part of an agent's control loop. Follow the shared memory stream, three-factor retrieval score, reflection tree, recursive plan, believability ablation, and the failures that separate stored history from usable context.`,learns:[`How recency, importance, and embedding relevance select a bounded prompt from a growing natural-language memory stream.`,`Why reflections and plans are written back as memories, letting yesterday's conclusions shape today's reactions without changing model weights.`,`What the five-condition believability study establishes, and why one two-day town, retrieval failures, paper-code drift, and a subjective metric bound the claim.`],explore:{label:`Compare verbal reinforcement`,href:`/daily/2026-10-14-reflexion-verbal-reinforcement-learning`,description:`Contrast this persistent social memory stream with Reflexion's evidence from task feedback stored across repeated attempts.`},preview:{badge:`MEMORY / REFLECTION LOOP`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-11-10-rt2-vision-language-action`,date:`2026-11-10`,url:`https://arxiv.org/abs/2307.15818v1`,title:`RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control`,authors:`Anthony Brohan et al.`,venue:`CoRL 2023`,lane:`AI Research`,difficulty:`Medium`,readTime:`10 min`,description:`RT-2 turns low-level robot actions into the same kind of tokens a vision-language model already writes. Follow the shared vocabulary, co-fine-tuning recipe, transfer evidence, cloud control loop, and the boundary between new semantic uses and new physical skills.`,learns:[`How eight discretized action values let one vision-language model share every weight across web and robot tasks.`,`Why mixing the original web tasks into robot fine-tuning matters more than simply attaching a larger pretrained model.`,`What the seen, unseen, and emergent-skill evaluations establish, and why scale, latency, and narrow robot motions bound the result.`],explore:{label:`Compare a compact modern VLA`,href:`/daily/2026-10-06-smolvla-affordable-robotics`,description:`Contrast RT-2's large cloud-served token policy with SmolVLA's compact action-chunking design and asynchronous execution loop.`},preview:{badge:`ACTIONS AS TOKENS`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-11-09-distserve-prefill-decode-disaggregation`,date:`2026-11-09`,url:`https://arxiv.org/abs/2401.09670v3`,title:`DistServe: Disaggregating Prefill and Decoding for Goodput-optimized Large Language Model Serving`,authors:`Yinmin Zhong, Shengyu Liu, Junda Chen, Jianbo Hu, Yibo Zhu, Xuanzhe Liu, Xin Jin, and Hao Zhang`,venue:`OSDI 2024`,lane:`Inference`,difficulty:`Medium`,readTime:`16 min`,description:`Prefill is compute-bound and decoding is bandwidth-bound, so sharing a GPU makes each wait on the other. Follow DistServe's split into prefill and decode pools, the per-GPU goodput arithmetic, the KV-cache transfer it adds, and what its evaluation does and does not show.`,learns:[`Why time to first token and time per output token pull a shared GPU in opposite directions, and how goodput scores both.`,`How separate prefill and decode pools turn capacity planning into a ratio between two phase rates, with a KV-cache handoff between them.`,`What the placement search, the transfer measurements, and the vLLM++ ablation establish, and where synthetic arrivals and author-set deadlines bound the claim.`],explore:{label:`Size a split with numbers`,href:`/blog/disaggregated-prefill-and-decode`,description:`Continue into Fanout's practical guide to sizing prefill and decode pools, cache transfer, and when a split pays.`},preview:{badge:`PREFILL / DECODE SPLIT`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-11-08-spanner-truetime-commit-wait`,date:`2026-11-08`,url:`https://www.usenix.org/system/files/conference/osdi12/osdi12-final-16.pdf`,title:`Spanner: Google's Globally-Distributed Database`,authors:`James C. Corbett, Jeffrey Dean, Michael Epstein, Andrew Fikes, Christopher Frost, JJ Furman, Sanjay Ghemawat, Andrey Gubarev, Christopher Heiser, Peter Hochschild, Wilson Hsieh, Sebastian Kanthak, Eugene Kogan, Hongyi Li, Alexander Lloyd, Sergey Melnik, David Mwaura, David Nagle, Sean Quinlan, Rajesh Rao, Lindsay Rolig, Yasushi Saito, Michal Szymaniak, Christopher Taylor, Ruth Wang, and Dale Woodford`,venue:`OSDI 2012 Best Paper`,lane:`Systems`,difficulty:`Medium`,readTime:`13 min`,description:`Spanner gives every transaction a commit timestamp that respects real-time order across datacenters. Follow the TrueTime interval API, the start rule and commit wait, the measured cost of waiting out clock uncertainty, and the drift assumption the guarantee rests on.`,learns:[`Why stamping writes with ordinary wall clocks can let a later transaction read before an earlier write.`,`How an interval clock plus commit wait proves external consistency, and why the wait is about twice the clock uncertainty.`,`What Table 3 and Figure 6 show about the cost of the wait and the size of epsilon, and which assumption the paper cannot measure away.`],explore:{label:`Compare logical clocks`,href:`/daily/2026-09-11-lamport-logical-clocks`,description:`Contrast Lamport's message-counting order with Spanner's physical timestamps that carry an explicit error bound.`},preview:{badge:`COMMIT WAIT`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-11-07-rlvr-reasoning-boundary`,date:`2026-11-07`,url:`https://arxiv.org/abs/2504.13837v5`,title:`Does Reinforcement Learning Really Incentivize Reasoning Capacity in LLMs Beyond the Base Model?`,authors:`Yang Yue, Zhiqi Chen, Rui Lu, Andrew Zhao, Zhaokai Wang, Yang Yue, Shiji Song, and Gao Huang`,venue:`NeurIPS 2025 Runner-Up`,lane:`AI Research`,difficulty:`Medium`,readTime:`13 min`,description:`RL with verifiable rewards can make correct reasoning easier to sample without expanding the set of problems a model can solve. Follow the pass@k crossover, base-only coverage, training checkpoints, and the limits of that negative result.`,learns:[`Why pass@1 measures early success while high-k pass@k probes whether any sampled correct route remains.`,`How matched base and RLVR models can reverse order as the sample budget grows, including base-only solved problems.`,`What one training trajectory and the entropy controls establish, and why math benchmarks, finite samples, and paired-model availability bound the claim.`],explore:{label:`Compare self-consistency`,href:`/daily/2026-10-05-self-consistency-reasoning`,description:`Contrast a practical small-sample voting method with this paper's high-k diagnostic for the boundary of sampled reasoning coverage.`},preview:{badge:`REASONING COVERAGE`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-11-06-calibration-temperature-scaling`,date:`2026-11-06`,url:`https://proceedings.mlr.press/v70/guo17a.html`,title:`On Calibration of Modern Neural Networks`,authors:`Chuan Guo, Geoff Pleiss, Yu Sun, and Kilian Q. Weinberger`,venue:`ICML 2017`,lane:`AI Research`,difficulty:`Easy`,readTime:`13 min`,description:`A classifier can become more accurate while its probabilities become less honest. Follow reliability diagrams, expected calibration error, and the one learned temperature that softens confidence without changing a single predicted class.`,learns:[`Why accuracy and calibrated confidence answer different questions, and how a reliability diagram exposes the gap.`,`How one validation-fitted temperature rescales every logit while preserving the model's class ranking and accuracy.`,`What the paper's cross-dataset results establish, and why binning, distribution shift, and newer architectures limit the recipe.`],explore:{label:`Compare Batch Normalization`,href:`/daily/2026-07-10-batch-normalization`,description:`Review the normalization method the calibration paper associates with lower error but worse confidence estimates in its controlled ConvNet comparison.`},preview:{badge:`CALIBRATED CONFIDENCE`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-11-05-sigmoid-loss-language-image-pretraining`,date:`2026-11-05`,url:`https://arxiv.org/abs/2303.15343v4`,title:`Sigmoid Loss for Language Image Pre-Training`,authors:`Xiaohua Zhai et al.`,venue:`ICCV 2023 Oral`,lane:`AI Research`,difficulty:`Medium`,readTime:`12 min`,description:`SigLIP replaces CLIP's two batch-wide softmax choices with an independent sigmoid decision for every image-text pair. Follow the signed pair loss, the learned bias, the chunked distributed implementation, and the batch-size evidence that makes 32,000 more important than one million.`,learns:[`How a similarity matrix becomes independent positive and negative pair decisions instead of two globally normalized classification problems.`,`Why a learned bias matters when every row contains one positive and thousands of negative image-text pairs.`,`What the memory-fit and batch-size sweeps establish, and why false negatives, optimizer instability, and private data still bound the result.`],explore:{label:`Compare CLIP's contrastive objective`,href:`/daily/2026-08-23-clip-natural-language-supervision`,description:`Start with the original image-text alignment recipe, then compare its row and column softmax normalizers with SigLIP's independent pair losses.`},preview:{badge:`PAIRWISE SIGMOID`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-11-04-muzero-learned-model-planning`,date:`2026-11-04`,url:`https://arxiv.org/abs/1911.08265v2`,title:`Mastering Atari, Go, Chess and Shogi by Planning with a Learned Model`,authors:`Julian Schrittwieser et al.`,venue:`Nature 2020`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`MuZero replaces the perfect simulator inside AlphaZero-style search with a learned latent model that predicts only reward, policy, and value. Follow the three learned functions, the search-to-training loop, the Atari evidence, and the precise boundary behind the phrase without rules.`,learns:[`Why a planning model can ignore future pixels and preserve only the quantities tree search consumes.`,`How representation, dynamics, and prediction functions let Monte Carlo tree search expand an imagined latent tree.`,`What the board-game and Atari results establish, and why deterministic dynamics, compute, and model error still bound the result.`],explore:{label:`Start with AlphaGo's search loop`,href:`/daily/2026-08-15-alphago-neural-tree-search`,description:`Compare a planner that receives game rules with MuZero's replacement: a learned hidden-state transition, reward, policy, and value model.`},preview:{badge:`LEARNED MODEL PLANNING`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-11-03-neural-ordinary-differential-equations`,date:`2026-11-03`,url:`https://proceedings.neurips.cc/paper/2018/hash/69386f6bb1dfed68692a24c8686939b9-Abstract.html`,title:`Neural Ordinary Differential Equations`,authors:`Ricky T. Q. Chen et al.`,venue:`NeurIPS 2018 Best Paper`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`Neural ODEs replace a fixed stack of hidden layers with a learned derivative field and an adaptive differential-equation solver. Follow the solver contract, the reverse-time adjoint, the continuous normalizing flow, and the numerical limits hidden by the continuous-depth metaphor.`,learns:[`How a residual update becomes a continuous-time derivative field integrated by a black-box adaptive solver.`,`Why the adjoint method can avoid storing the forward solver trajectory, and where numerical reconstruction complicates that promise.`,`What the MNIST, continuous-flow, and irregular-time-series evidence establishes without implying that Neural ODEs replace ordinary residual networks.`],explore:{label:`Compare residual networks`,href:`/daily/2026-07-09-resnet`,description:`Contrast a fixed sequence of learned residual steps with a shared derivative field whose evaluation points are chosen by a numerical solver.`},preview:{badge:`CONTINUOUS DEPTH`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-11-02-tensorflow-large-scale-machine-learning`,date:`2026-11-02`,url:`https://www.usenix.org/conference/osdi16/technical-sessions/presentation/abadi`,title:`TensorFlow: A System for Large-Scale Machine Learning`,authors:`Martín Abadi et al.`,venue:`OSDI 2016`,lane:`Systems`,difficulty:`Medium`,readTime:`13 min`,description:`TensorFlow made one machine-learning program portable across heterogeneous hardware by representing primitive computation, mutable state, and update rules in one deferred dataflow graph. Follow how the runtime prunes, places, partitions, and connects that graph across CPU, GPU, TPU, and machine boundaries.`,learns:[`Why putting mutable Variables and their update operations inside the graph was more flexible than a fixed parameter-server interface.`,`How feeds and fetches select a subgraph, placement assigns operations to devices, and cross-device edges become Send and Recv operations.`,`What the 2016 performance evidence establishes, and why static graphs, weak checkpoint consistency, and incomplete placement policy bound the result.`],explore:{label:`Compare tensor parallel training`,href:`/daily/2026-10-27-megatron-lm-tensor-parallelism`,description:`Contrast TensorFlow's general placement substrate with Megatron-LM's paper-specific decision to split Transformer matrix multiplications across GPUs.`},preview:{badge:`STATEFUL DATAFLOW`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-11-01-qlora-efficient-finetuning`,date:`2026-11-01`,url:`https://arxiv.org/abs/2305.14314v1`,title:`QLoRA: Efficient Finetuning of Quantized LLMs`,authors:`Tim Dettmers et al.`,venue:`NeurIPS 2023`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`QLoRA made large-model fine-tuning fit radically smaller memory budgets by storing a frozen base in 4-bit NormalFloat, dequantizing blocks for 16-bit computation, and training only LoRA adapters. Follow the precision boundary, memory devices, ablations, and qualified chatbot evidence.`,learns:[`Why four-bit storage does not mean four-bit matrix multiplication, gradients, activations, or optimizer state.`,`How NF4, double quantization, paged optimizers, and broad LoRA coverage each remove a different memory or accuracy bottleneck.`,`What the MMLU datatype comparisons establish and why the 99.3 percent Guanaco headline is bounded by its prompts, judge, and confidence interval.`],explore:{label:`Learn LoRA and QLoRA`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aqlora`,description:`Connect QLoRA's quantized frozen base to Fanout's worked low-rank adapter update, parameter count, gradient flow, and merge boundary.`},preview:{badge:`4-BIT FINETUNING`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-31-end-to-end-object-detection-transformers`,date:`2026-10-31`,url:`https://arxiv.org/abs/2005.12872v3`,title:`End-to-End Object Detection with Transformers`,authors:`Nicolas Carion et al.`,venue:`ECCV 2020`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`DETR reframed object detection as direct set prediction: learned query slots propose boxes in parallel, Hungarian matching assigns one positive owner to each target, and unmatched slots learn no object. Follow the mechanism, the decoder ablations, and the scale-dependent COCO evidence.`,learns:[`How a fixed bank of learned object queries represents a variable-sized set through the no-object class.`,`Why one-to-one Hungarian matching turns duplicate predictions into training errors instead of an inference-time cleanup problem.`,`What the 42.0 AP headline hides about large and small objects, long training, and fixed query capacity.`],explore:{label:`Compare grid-based YOLO`,href:`/daily/2026-09-10-yolo-unified-object-detection`,description:`Contrast DETR's learned set assignment with an earlier one-stage detector whose prediction responsibilities are tied to a spatial grid.`},preview:{badge:`DIRECT SET PREDICTION`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-30-asynchronous-deep-reinforcement-learning`,date:`2026-10-30`,url:`https://arxiv.org/abs/1602.01783v2`,title:`Asynchronous Methods for Deep Reinforcement Learning`,authors:`Volodymyr Mnih et al.`,venue:`ICML 2016`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`A3C replaced one agent's replay memory with many fresh, out-of-phase actor-learners updating a shared model. Follow how parallel experience decorrelates training data, how short n-step rollouts update both policy and value, and why later synchronous A2C changed the verdict on asynchrony itself.`,learns:[`Why independent actors can perform the stabilizing, decorrelating role that experience replay played in DQN.`,`How an A3C worker turns a short rollout into an advantage estimate and updates shared policy and value parameters without a synchronization barrier.`,`What the 57-game Atari and thread-scaling results establish, which comparison caveat matters, and why A2C later separated parallelism from asynchrony.`],explore:{label:`Compare replay-based DQN`,href:`/daily/2026-09-28-human-level-control-dqn`,description:`Contrast A3C's fresh parallel rollouts with DQN's stored, randomly sampled experience and delayed target network.`},preview:{badge:`ASYNCHRONOUS ACTOR-CRITIC`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-29-denoising-diffusion-probabilistic-models`,date:`2026-10-29`,url:`https://arxiv.org/abs/2006.11239v2`,title:`Denoising Diffusion Probabilistic Models`,authors:`Jonathan Ho, Ajay Jain, Pieter Abbeel`,venue:`NeurIPS 2020`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`DDPM made diffusion models practical for high-quality image synthesis: corrupt data with a fixed Gaussian chain, train one time-conditioned U-Net to predict the added noise, then reverse the chain from pure noise. Follow the closed-form training shortcut, the simplified objective, and the evidence behind the paper's sample-quality claims.`,learns:[`How a closed-form forward marginal lets training jump directly to any noise level instead of simulating every earlier corruption step.`,`Why predicting injected noise turns the reverse-process objective into a simple denoising regression problem across timesteps.`,`What the CIFAR-10 ablations establish about the simplified objective, and why 1,000-step sampling remained the central cost.`],explore:{label:`Compare continuous flows`,href:`/daily/2026-10-01-flow-matching-generative-modeling`,description:`Contrast DDPM's stochastic discrete-time reversal with flow matching's learned continuous vector field and ODE-style transport.`},preview:{badge:`DENOISING DIFFUSION`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-10-28-generative-pretraining-gpt`,date:`2026-10-28`,url:`https://cdn.openai.com/research-covers/language-unsupervised/language_understanding_paper.pdf`,title:`Improving Language Understanding by Generative Pre-Training`,authors:`Alec Radford et al.`,venue:`OpenAI 2018`,lane:`AI Research`,difficulty:`Medium`,readTime:`12 min`,description:`GPT-1 made the two-stage transfer recipe concrete: learn a decoder Transformer from unlabeled books, serialize several supervised tasks into token sequences, then adapt the same network with a small output head. Follow the mechanism, the decisive no-pretraining ablation, and the limits of the 2018 evidence.`,learns:[`How next-token prediction creates a reusable training signal before the model sees downstream labels.`,`Why task-specific input transformations let entailment, similarity, question answering, and classification share one decoder architecture.`,`What the layer-transfer and no-pretraining ablations establish, and why the auxiliary language-model objective has a mixed result.`],explore:{label:`Compare in-context adaptation`,href:`/daily/2026-09-03-gpt3-few-shot-learners`,description:`Contrast GPT-1's supervised gradient-based fine-tuning with GPT-3's later use of demonstrations inside the context window.`},preview:{badge:`GENERATIVE PRE-TRAINING`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-27-megatron-lm-tensor-parallelism`,date:`2026-10-27`,url:`https://arxiv.org/abs/1909.08053v4`,title:`Megatron-LM: Training Multi-Billion Parameter Language Models Using Model Parallelism`,authors:`Mohammad Shoeybi et al.`,venue:`arXiv 2019 · revised 2020`,lane:`Systems`,difficulty:`Hard`,readTime:`12 min`,description:`Megatron-LM places tensor boundaries around the operations that can remain local. Follow why a naive row split must synchronize before GeLU, how paired column- and row-parallel projections reduce only at the block output, and what the paper's 512-GPU weak-scaling evidence actually establishes.`,learns:[`Why partial sums must be combined before a nonlinearity, while disjoint output columns can pass through GeLU independently.`,`How the same column-then-row arrangement keeps complete attention heads local and limits collectives per Transformer layer.`,`Why 74% weak-scaling efficiency is not a 74% fixed-model speedup, and how interconnect and GEMM shape bound the result.`],explore:{label:`Compare pipeline parallelism`,href:`/daily/2026-10-11-gpipe-pipeline-parallelism`,description:`Contrast splitting individual matrices inside a layer with GPipe's strategy of assigning whole layer groups to pipeline stages.`},preview:{badge:`TENSOR PARALLELISM`,accent:`var(--ga-sparkle-to)`,background:`color-mix(in srgb, var(--ga-sparkle-to) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-26-dapo-llm-reinforcement-learning`,date:`2026-10-26`,url:`https://arxiv.org/abs/2503.14476`,title:`DAPO: An Open-Source LLM Reinforcement Learning System at Scale`,authors:`Qiying Yu et al.`,venue:`NeurIPS 2025`,lane:`AI Research`,difficulty:`Hard`,readTime:`13 min`,description:`DAPO turns four failure diagnoses in long-chain-of-thought reinforcement learning into four concrete interventions: asymmetric clipping, informative-prompt sampling, token-level loss normalization, and gradual overlength penalties. Follow each control, then audit the cumulative AIME experiment and the compute claims it cannot settle.`,learns:[`Why a symmetric probability-ratio clip can stop rare, positively rewarded tokens from becoming much more likely.`,`How dynamic sampling removes prompt groups whose identical rewards produce zero normalized advantage.`,`What the cumulative 30-to-50 AIME result establishes, and why it does not isolate four independent causal effects.`],explore:{label:`Review group-relative advantages`,href:`/daily/2026-08-02-deepseekmath-grpo`,description:`Start with GRPO's critic-free group normalization before inspecting the four training controls DAPO adds around it.`},preview:{badge:`REASONING RL`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`network`}},{id:`2026-10-25-whisper-large-scale-weak-supervision`,date:`2026-10-25`,url:`https://arxiv.org/abs/2212.04356v1`,title:`Robust Speech Recognition via Large-Scale Weak Supervision`,authors:`Alec Radford et al.`,venue:`ICML 2023`,lane:`AI Research`,difficulty:`Medium`,readTime:`9 min`,description:`Whisper trains a standard encoder-decoder Transformer on 680,000 hours of diverse web audio and represents language, transcription, translation, silence, and timestamps with decoder tokens. Read it to see why cross-dataset zero-shot evaluation changes the robustness story, what dataset scale buys, and where long-form generation can still fail.`,learns:[`How one decoder prefix specifies language, task, silence, and timestamp behavior for a fixed audio representation.`,`Why matching two systems on clean LibriSpeech exposes a much larger robustness gap across other speech distributions.`,`How uneven language data, thirty-second windows, decoding heuristics, and hallucinations bound the result.`],explore:{label:`Start with audio fingerprints`,href:`/daily/2026-08-19-shazam-audio-search`,description:`Review how time-frequency structure represents audio before moving from sparse landmarks to learned speech features.`},preview:{badge:`ROBUST SPEECH RECOGNITION`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-24-focal-loss-dense-object-detection`,date:`2026-10-24`,url:`https://arxiv.org/abs/1708.02002v2`,title:`Focal Loss for Dense Object Detection`,authors:`Tsung-Yi Lin, Priya Goyal, Ross Girshick, Kaiming He, and Piotr Dollár`,venue:`ICCV 2017`,lane:`AI Research`,difficulty:`Easy`,readTime:`12 min`,description:`Focal loss discounts already-correct predictions so many easy background candidates do not overwhelm a dense detector. Calculate the loss contribution, separate class weights from difficulty weights, and inspect RetinaNet’s controlled comparison.`,learns:[`Why many small easy-background losses can dominate a dense detector’s training objective.`,`How the correct-class probability controls focal weighting and how gamma differs from alpha.`,`What the matched RetinaNet ablation establishes and why hard examples can still contain bad labels.`],explore:{label:`See a dense detector first`,href:`/daily/2026-09-10-yolo-unified-object-detection`,description:`Review how an image becomes many candidate predictions before changing their contribution to training.`},preview:{badge:`FOCAL LOSS`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`bars`}},{id:`2026-10-23-roformer-rotary-position-embeddings`,date:`2026-10-23`,url:`https://arxiv.org/abs/2104.09864v5`,title:`RoFormer: Enhanced Transformer with Rotary Position Embedding`,authors:`Jianlin Su, Yu Lu, Shengfeng Pan, Ahmed Murtadha, Bo Wen, and Yunfeng Liu`,venue:`arXiv 2021 · revised 2023`,lane:`AI Research`,difficulty:`Medium`,readTime:`11 min`,description:`RoFormer rotates query and key coordinate pairs so their attention score carries relative position. Work through the shared-shift identity, then audit why computable positions and successful long-context generalization are different claims.`,learns:[`How absolute-position rotations make a query-key comparison depend on relative offset.`,`Why paired frequencies preserve the geometric identity without making every score decrease with distance.`,`What the mixed benchmark results and long-text training schedule establish about generalization.`],explore:{label:`Start with soft attention`,href:`/daily/2026-09-16-neural-translation-soft-attention`,description:`Review how similarity scores become a weighted read before changing the position rule inside each score.`},preview:{badge:`RELATIVE POSITION`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`curve`}},{id:`2026-10-22-neural-turing-machines`,date:`2026-10-22`,url:`https://arxiv.org/abs/1410.5401v2`,title:`Neural Turing Machines`,authors:`Alex Graves, Greg Wayne, and Ivo Danihelka`,venue:`arXiv 2014`,lane:`AI Research`,difficulty:`Medium`,readTime:`28 min`,description:`Neural Turing Machines give a neural controller a separate, mutable memory and make its read and write addresses differentiable. Read it to see how content lookup and relative shifts combine, why the copy trace looks like a learned algorithm, and where the paper's preliminary synthetic evidence stops.`,learns:[`How a normalized weighting turns a discrete memory address into a trainable soft read or write.`,`Why content addressing finds a matching row while location addressing iterates from the previous focus.`,`What the copy memory trace establishes, and why fixed capacity and missing seed variation bound the claim.`],explore:{label:`Start with soft attention`,href:`/daily/2026-09-16-neural-translation-soft-attention`,description:`Review how differentiable weights select information before applying the same idea to mutable external memory.`},preview:{badge:`EXTERNAL MEMORY`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-21-densenet-feature-reuse`,date:`2026-10-21`,url:`https://arxiv.org/abs/1608.06993v5`,title:`Densely Connected Convolutional Networks`,authors:`Gao Huang, Zhuang Liu, Laurens van der Maaten, and Kilian Q. Weinberger`,venue:`CVPR 2017`,lane:`AI Research`,difficulty:`Easy`,readTime:`11 min`,description:`DenseNet keeps earlier feature maps available by concatenating them and asks each layer to add a small new contribution. Follow channel growth and compressed transitions, then separate the paper’s parameter-efficiency evidence from the activation-memory cost of a naive implementation.`,learns:[`How concatenation preserves earlier maps as separate channels while a growth rate limits each new contribution.`,`Why fixed-resolution dense blocks need channel projections and pooling at their boundaries.`,`What the parameter comparison establishes and why it does not guarantee low peak memory or latency.`],explore:{label:`Start with residual connections`,href:`/daily/2026-07-09-resnet`,description:`Review residual addition before comparing it with DenseNet’s channel concatenation.`},preview:{badge:`FEATURE REUSE`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`network`}},{id:`2026-10-20-nerf-neural-radiance-fields`,date:`2026-10-20`,url:`https://arxiv.org/abs/2003.08934v2`,title:`NeRF: Representing Scenes as Neural Radiance Fields for View Synthesis`,authors:`Ben Mildenhall et al.`,venue:`ECCV 2020`,lane:`AI Research`,difficulty:`Medium`,readTime:`30 min`,description:`NeRF learns one continuous, scene-specific function of 3D position and viewing direction, then volume-renders that function into new camera views. Read it to see how density controls both color and visibility along a ray, why sinusoidal coordinates and hierarchical sampling matter, and where the original method trades speed for fidelity.`,learns:[`How position-dependent density and view-dependent color represent one static scene.`,`Why transmittance and opacity turn ordered ray samples into a differentiable pixel color.`,`What the main result, component ablations, per-scene optimization, and rendering cost actually establish.`],explore:{label:`Start with Vision Transformer`,href:`/daily/2026-09-27-vision-transformer-image-patches`,description:`Review how continuous visual inputs become learned features before studying NeRF's coordinate-based scene function.`},preview:{badge:`NEURAL RADIANCE FIELDS`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-19-alibi-linear-attention-biases`,date:`2026-10-19`,url:`https://arxiv.org/abs/2108.12409v2`,title:`Train Short, Test Long: Attention with Linear Biases Enables Input Length Extrapolation`,authors:`Ofir Press, Noah A. Smith, and Mike Lewis`,venue:`ICLR 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`12 min`,description:`ALiBi replaces position embeddings with fixed distance penalties in attention scores. Follow the arithmetic, compare equal-time training budgets, and learn why improved perplexity on longer blocks can come from fewer context resets rather than better use of distant facts.`,learns:[`How head-specific distance penalties change attention weights without imposing a hard context cutoff.`,`Why shifted bias rows give the same softmax result and why the causal mask still matters.`,`How the evaluation protocol separates stable extrapolation from evidence of long-range retrieval.`],explore:{label:`Review soft attention`,href:`/daily/2026-09-16-neural-translation-soft-attention`,description:`Start with normalized attention weights and weighted value mixtures before adding the distance penalty.`},preview:{badge:`POSITION BIAS`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`bars`}},{id:`2026-10-18-lets-verify-step-by-step`,date:`2026-10-18`,url:`https://arxiv.org/abs/2305.20050v1`,title:`Let's Verify Step by Step`,authors:`Hunter Lightman et al.`,venue:`ICLR 2024`,lane:`AI Research`,difficulty:`Medium`,readTime:`32 min`,description:`Let's Verify Step by Step compares reward models trained on a final answer with reward models trained to judge every reasoning step. Read it to see why first-error labels improve credit assignment, how best-of-N exposes verifier quality without changing the generator, and why the headline result needs a controlled companion experiment.`,learns:[`How process supervision preserves a valid prefix while locating the first broken reasoning step.`,`Why product scoring turns many step judgments into one candidate rank for best-of-N selection.`,`Which results isolate supervision form and which remain confounded by different training sets.`],explore:{label:`Explore reward models`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Areward-model`,description:`Continue from process supervision into Fanout's AI research concept graph for reward models.`},preview:{badge:`PROCESS SUPERVISION`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-10-17-unet-context-localization`,date:`2026-10-17`,url:`https://arxiv.org/abs/1505.04597v1`,title:`U-Net: Convolutional Networks for Biomedical Image Segmentation`,authors:`Olaf Ronneberger, Philipp Fischer, and Thomas Brox`,venue:`MICCAI 2015`,lane:`AI Research`,difficulty:`Easy`,readTime:`24 min`,description:`U-Net joins a context-building encoder to a localization-preserving decoder with copied feature maps at matching resolutions. Read it to see how those bridges recover spatial detail, why elastic augmentation and a border-aware loss matter on tiny biomedical datasets, and what the original challenge results do not isolate.`,learns:[`How contracting and expanding paths divide context from precise localization.`,`Why copied encoder maps, elastic deformation, border weighting, and overlap tiling form one complete system.`,`Why the benchmark wins support the package but do not quantify the causal gain from skip connections alone.`],explore:{label:`Explore U-Net`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Au-net`,description:`Continue from the paper into Fanout's AI research concept graph for U-Net.`},preview:{badge:`U-NET`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-16-emergent-abilities-mirage`,date:`2026-10-16`,url:`https://proceedings.neurips.cc/paper_files/paper/2023/hash/adc98a266f45005c403b8311ca7e8bd7-Abstract-Conference.html`,title:`Are Emergent Abilities of Large Language Models a Mirage?`,authors:`Rylan Schaeffer, Brando Miranda, and Sanmi Koyejo`,venue:`NeurIPS 2023 Outstanding Paper`,lane:`AI Research`,difficulty:`Medium`,readTime:`34 min`,description:`This paper asks whether sudden capability jumps in language-model scaling curves belong to the models or to the metrics used to score them. Read it to see how exact match can hide smooth partial progress, why fixed outputs look different under Token Edit Distance and Brier Score, and what evidence a serious emergence claim should survive.`,learns:[`How exact-match accuracy can transform smooth token-level improvement into a flat-then-jump curve.`,`Why re-scoring fixed outputs isolates the metric from the model, prompt set, and training run.`,`Which claims survive the paper's BIG-Bench meta-analysis, induced vision experiments, and stated limitations.`],explore:{label:`Start with scaling laws`,href:`/daily/2026-07-17-scaling-laws`,description:`Review how performance changes with model scale before asking whether a bend in that curve reflects the model or the measurement.`},preview:{badge:`METRIC MIRAGE`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-10-15-masked-autoencoders-scalable-vision`,date:`2026-10-15`,url:`https://arxiv.org/abs/2111.06377v3`,title:`Masked Autoencoders Are Scalable Vision Learners`,authors:`Kaiming He et al.`,venue:`CVPR 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`28 min`,description:`Masked autoencoders hide most image patches before a Vision Transformer encoder, then use a lightweight decoder to reconstruct only the missing pixels. Read it to see why the 75 percent masking ratio saves encoder compute, how the asymmetric design changes representation learning, and which ImageNet and COCO results support the paper's claims.`,learns:[`Why the large encoder processes visible patches only and mask tokens appear after it.`,`How a high masking ratio changes both the reconstruction task and the amount of pretraining compute.`,`Why strong fine-tuning and transfer results do not prove that pixel reconstruction itself discovers semantic objects.`],explore:{label:`Start with Vision Transformer`,href:`/daily/2026-09-27-vision-transformer-image-patches`,description:`Review how an image becomes a sequence of positioned patch tokens before hiding most of that sequence during MAE pretraining.`},preview:{badge:`MASKED AUTOENCODERS`,accent:`var(--ga-cat-yellow)`,background:`color-mix(in srgb, var(--ga-cat-yellow) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-14-reflexion-verbal-reinforcement-learning`,date:`2026-10-14`,url:`https://arxiv.org/abs/2303.11366`,title:`Reflexion: Language Agents with Verbal Reinforcement Learning`,authors:`Noah Shinn et al.`,venue:`NeurIPS 2023`,lane:`AI Research`,difficulty:`Medium`,readTime:`32 min`,description:`Reflexion turns a failed agent trajectory into a short verbal lesson, stores that lesson as episodic memory, and retries without updating model weights. Read it to see how acting, evaluation, and reflection form one loop, why evaluator quality controls the learning signal, and how the original ALFWorld, HotPotQA, and coding results should be interpreted.`,learns:[`How the Actor, Evaluator, and Self-Reflection roles convert one failed trajectory into a new prompt.`,`Why short-term trajectory context and long-term verbal memory solve different parts of the retry problem.`,`Where generated tests and self-evaluation can create false lessons or end the loop too early.`],explore:{label:`Start with ReAct`,href:`/daily/2026-08-10-react-reasoning-acting`,description:`See how thoughts, actions, and observations form one trial before adding reflection across repeated trials.`},preview:{badge:`REFLEXION`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-13-tau-bench-tool-agent-user-interaction`,date:`2026-10-13`,url:`https://arxiv.org/abs/2406.12045v1`,title:`tau-bench: A Benchmark for Tool-Agent-User Interaction in Real-World Domains`,authors:`Shunyu Yao et al.`,venue:`ICLR 2025`,lane:`AI Research`,difficulty:`Medium`,readTime:`34 min`,description:`tau-bench evaluates tool-using agents inside multi-turn retail and airline conversations with domain policies and mutable databases. Read it to see how final-state grading separates fluent talk from completed work, why pass^k measures repeated reliability, and why the original scores are now historical rather than a current leaderboard.`,learns:[`How a simulated user, policy document, API tools, and hidden target state form one stateful agent task.`,`Why the reward checks both the final database and required information in the agent's reply.`,`How pass^k exposes inconsistent agents and why corrected task releases matter for present-day comparisons.`],explore:{label:`Compare ReAct`,href:`/daily/2026-08-10-react-reasoning-acting`,description:`See how interleaved reasoning and tool actions work before inspecting how tau-bench evaluates the resulting conversation and state changes.`},preview:{badge:`TAU-BENCH`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-12-sleeper-agents-safety-training`,date:`2026-10-12`,url:`https://arxiv.org/abs/2401.05566v3`,title:`Sleeper Agents: Training Deceptive LLMs that Persist Through Safety Training`,authors:`Evan Hubinger et al.`,venue:`Anthropic 2024`,lane:`AI Research`,difficulty:`Medium`,readTime:`36 min`,description:`Sleeper Agents deliberately trains language models to follow one policy in ordinary contexts and an unsafe policy after a hidden trigger. Read it to see why standard safety training can improve the visible branch while leaving the triggered behavior intact, and why the result is a model-organism warning rather than evidence about prevalence in deployed systems.`,learns:[`How a synthetic trigger selects between ordinary and deliberately planted coding policies.`,`Why supervised fine-tuning, reinforcement learning, and adversarial training can miss a conditional policy outside their training distribution.`,`How to separate an existence proof about controlled model organisms from claims about real-world deceptive alignment.`],explore:{label:`Compare Constitutional AI`,href:`/daily/2026-09-23-constitutional-ai-feedback`,description:`Contrast the sleeper-agent stress test with a behavioral safety pipeline that uses constitutional critiques and preference feedback.`},preview:{badge:`SLEEPER AGENTS`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-orange) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-11-gpipe-pipeline-parallelism`,date:`2026-10-11`,url:`https://arxiv.org/abs/1811.06965v5`,title:`GPipe: Easy Scaling with Micro-Batch Pipeline Parallelism`,authors:`Yanping Huang et al.`,venue:`NeurIPS 2019`,lane:`Systems`,difficulty:`Easy`,readTime:`32 min`,description:`GPipe divides a neural network into sequential stages and sends micro-batches through them as a pipeline. Read it to see how the schedule trades idle time for throughput, why accumulated gradients preserve synchronous updates, and how rematerialization makes much larger models fit in accelerator memory.`,learns:[`How layer partitions and micro-batches turn model parallelism into a diagonal pipeline schedule.`,`Why increasing the number of micro-batches shrinks the fill-and-drain bubble without changing the mini-batch update.`,`How activation rematerialization saves memory and why stage balance still limits throughput.`],explore:{label:`Map distributed training`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Adistributed-training`,description:`Connect pipeline parallelism to data, tensor, and optimizer-state partitioning in the Fanout knowledge map.`},preview:{badge:`GPIPE`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-10-toy-models-superposition`,date:`2026-10-10`,url:`https://arxiv.org/abs/2209.10652v1`,title:`Toy Models of Superposition`,authors:`Nelson Elhage et al.`,venue:`Transformer Circuits Thread 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`34 min`,description:`Toy Models of Superposition asks how a neural layer can track more useful features than it has hidden dimensions. Read it to see how sparse features share non-orthogonal directions, why ReLU makes interference affordable, and why the clean geometry remains a controlled clue rather than a map of a real language model.`,learns:[`How a tied-weight ReLU autoencoder turns features into directions through a narrow hidden layer.`,`Why sparse features can share non-orthogonal directions while dense features are pruned.`,`How phase changes and geometric packing sharpen interpretability questions without proving what happens in real models.`],explore:{label:`Map the interpretability stack`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Ainterpretability`,description:`Connect the toy mechanism to feature discovery, sparse representations, and causal tests in the Fanout knowledge map.`},preview:{badge:`SUPERPOSITION`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-09-rethinking-generalization`,date:`2026-10-09`,url:`https://arxiv.org/abs/1611.03530v2`,title:`Understanding deep learning requires rethinking generalization`,authors:`Chiyuan Zhang et al.`,venue:`ICLR 2017`,lane:`AI Research`,difficulty:`Medium`,description:`The random-label control shows that a network can fit arbitrary training targets while performing near chance on held-out examples. Read it to distinguish fitting from generalization, understand what stays fixed in the experiment, and avoid overclaims about regularization or learning theory.`,learns:[`Why random targets must stay fixed across epochs for the paper’s memorization control.`,`How equal training accuracy can accompany very different held-out accuracy in a matched comparison.`,`Why the results challenge coarse explanations without proving that regularization or learning theory is useless.`],explore:{label:`Map generalization`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Ageneralization`,description:`Connect the random-label control to generalization, regularization, and inductive bias in the Fanout knowledge map.`},readTime:`32 min`,preview:{badge:`GENERALIZATION`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`bars`}},{id:`2026-10-08-cuckoo-hashing`,date:`2026-10-08`,url:`https://www.rasmuspagh.net/papers/cuckoo-jour.pdf`,title:`Cuckoo Hashing`,authors:`Rasmus Pagh and Flemming Friche Rodler`,venue:`Journal of Algorithms 2004`,lane:`Systems`,difficulty:`Easy`,description:`Cuckoo hashing restricts each key to two candidate cells, moving collisions into insertion. Read it to separate worst-case lookup from expected amortized updates, replay an eviction chain, and see why empty space alone cannot guarantee a valid placement.`,learns:[`How two legal homes per key bound lookup while allowing insertion to displace residents.`,`Why three keys sharing two candidate cells cannot fit, even in a mostly empty table.`,`Which randomness and space assumptions support the update guarantee, and where historical benchmarks stop.`],explore:{label:`Compare consistent hashing`,href:`/system/archive/consistent-hashing`,description:`Contrast assigning keys to servers with assigning keys to cells inside a dictionary; the two hashing problems have different constraints.`},readTime:`28 min`,preview:{badge:`CUCKOO HASHING`,accent:`var(--ga-fg1)`,background:`var(--ga-chip)`,figure:`network`}},{id:`2026-10-07-flamingo-visual-language-model`,date:`2026-10-07`,url:`https://arxiv.org/abs/2204.14198v2`,title:`Flamingo: a Visual Language Model for Few-Shot Learning`,authors:`Jean-Baptiste Alayrac et al.`,venue:`NeurIPS 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`42 min`,description:`Flamingo connects a frozen vision encoder and a frozen language model with a fixed visual bottleneck and gated cross-attention layers. Read it to see how interleaved images and text share context, why the gates begin closed, and which celebrated few-shot claims remain hard to reproduce.`,learns:[`How a Perceiver Resampler turns variable image and video features into sixty-four visual tokens.`,`Why zero-initialized gated cross-attention preserves the language model before the visual bridge learns to open.`,`How the single-image attention mask, broad task results, proprietary data, and unreleased model bound the evidence.`],explore:{label:`Start with CLIP's contrastive pairing`,href:`/daily/2026-08-23-clip-natural-language-supervision`,description:`See how image-text matching produces a useful visual encoder before Flamingo turns visual evidence into generated language.`},preview:{badge:`FLAMINGO`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-06-smolvla-affordable-robotics`,date:`2026-10-06`,url:`https://arxiv.org/abs/2506.01844v1`,title:`SmolVLA: A Vision-Language-Action Model for Affordable and Efficient Robotics`,authors:`Mustafa Shukor et al.`,venue:`arXiv 2025`,lane:`AI Research`,difficulty:`Medium`,readTime:`36 min`,description:`SmolVLA compresses a vision-language-action policy to 450 million parameters and predicts fifty-action chunks with a flow-matching expert. Read it to see how an asynchronous queue overlaps inference with robot motion, why that makes execution faster, and where the reported success rate falls.`,learns:[`How a shortened vision-language backbone and interleaved action expert turn images, language, and robot state into action chunks.`,`How a refill threshold lets a robot execute one chunk while a policy server predicts the next.`,`How to read the compact-model results alongside narrow embodiment coverage and the measured speed-success tradeoff.`],explore:{label:`Compare action chunks in Fanout`,href:`/daily/2026-09-24-diffusion-policy-robot-actions`,description:`Continue from a flow-matching robot policy to the earlier question of why policies predict whole action sequences.`},preview:{badge:`SMOLVLA`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-orange) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-10-05-self-consistency-reasoning`,date:`2026-10-05`,url:`https://arxiv.org/abs/2203.11171v4`,title:`Self-Consistency Improves Chain of Thought Reasoning in Language Models`,authors:`Xuezhi Wang et al.`,venue:`ICLR 2023`,lane:`Inference`,difficulty:`Easy`,readTime:`28 min`,description:`A model can reach the same answer along several different routes. This paper shows how sampling those routes and voting on their final answers improves reasoning accuracy without additional training, then exposes the extra computation and the gap between agreement and correctness.`,learns:[`How self-consistency replaces one greedy chain of thought with several sampled solutions and a vote over final answers.`,`Why grouping answers differs from selecting the most probable individual explanation.`,`How to read the accuracy gains alongside generation cost, answer extraction, and repeated mistakes.`],explore:{label:`Read the original chain-of-thought guide`,href:`/daily/2026-08-18-chain-of-thought`,description:`Understand the worked-example prompting baseline before changing how its generated answers are combined.`},preview:{badge:`SELF-CONSISTENCY`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-04-simclr-contrastive-representations`,date:`2026-10-04`,url:`https://arxiv.org/abs/2002.05709v3`,title:`A Simple Framework for Contrastive Learning of Visual Representations`,authors:`Ting Chen, Simon Kornblith, Mohammad Norouzi, and Geoffrey Hinton`,venue:`ICML 2020`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`SimCLR turns two altered views of one photograph into a training target without class labels. Read it to see why easy visual shortcuts can spoil representation learning, why the projection head is discarded after training, and why the headline ImageNet result needs its model size attached.`,learns:[`How same-source image views define positives while other batch views supply competing negatives.`,`Why augmentation composition and a nonlinear projection head change the representation that transfers.`,`How to interpret linear evaluation, batch-size tradeoffs, and the wider model behind the headline accuracy.`],explore:{label:`Compare image-text pairing in Fanout`,href:`/daily/2026-08-23-clip-natural-language-supervision`,description:`Continue from matching two views of an image to CLIP’s matching of observed image-text pairs.`},preview:{badge:`SIMCLR`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-10-03-log-structured-merge-tree`,date:`2026-10-03`,url:`https://doi.org/10.1007/s002360050048`,title:`The Log-Structured Merge-Tree (LSM-Tree)`,authors:`Patrick O’Neil, Edward Cheng, Dieter Gawlick, and Elizabeth O’Neil`,venue:`Acta Informatica 1996`,lane:`Systems`,difficulty:`Easy`,readTime:`32 min`,description:`How can a database keep scattered incoming records searchable without paying for a separate disk-page update on every insert? The original LSM-tree batches sorted entries in memory and rolls them into larger disk trees. Read it to understand the merge, its amortized cost, and the read and recovery obligations that remain.`,learns:[`How a separately searchable memory component postpones disk placement without hiding recent entries.`,`How a rolling merge shares page-transfer work across new entries, and why a small memory buffer can erase the advantage.`,`Why component searches, deletion markers, recovery, and historical cost assumptions limit a simple faster-writes claim.`],explore:{label:`Follow a modern LSM storage engine`,href:`/system/archive/lsm-tree-storage-engine`,description:`Connect the original rolling merge to memory tables, sorted files, version resolution, and compaction.`},preview:{badge:`LSM-TREE`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-10-02-truthfulqa-human-falsehoods`,date:`2026-10-02`,url:`https://arxiv.org/abs/2109.07958v2`,title:`TruthfulQA: Measuring How Models Mimic Human Falsehoods`,authors:`Stephanie Lin, Jacob Hilton, and Owain Evans`,venue:`ACL 2022`,lane:`AI Research`,difficulty:`Easy`,readTime:`31 min`,description:`TruthfulQA asks whether a language model can resist false statements that humans repeat often enough to imitate. Read it to see how adversarial misconception questions separate truthfulness from informativeness, why the original models showed inverse scaling, which controls support that interpretation, and why new model families, benchmark revisions, judge availability, shortcuts, and contamination now bound the famous result.`,learns:[`How adversarially filtered misconception questions target imitative falsehoods rather than ordinary missing knowledge.`,`Why truthfulness and informativeness require separate labels, and how the original human-evaluated scaling result should be read.`,`How dataset revisions, post-training, retrieval, judge design, multiple-choice shortcuts, and benchmark exposure change what a modern score can establish.`],explore:{label:`Audit leaderboard evidence in Fanout`,href:`/daily/2026-09-21-leaderboard-illusion`,description:`Connect TruthfulQA's judge and benchmark mechanics to selection bias, repeated evaluation, and the gap between a leaderboard score and a deployment claim.`},preview:{badge:`TRUTHFULQA`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-10-01-flow-matching-generative-modeling`,date:`2026-10-01`,url:`https://arxiv.org/abs/2210.02747v2`,title:`Flow Matching for Generative Modeling`,authors:`Yaron Lipman et al.`,venue:`ICLR 2023`,lane:`AI Research`,difficulty:`Medium`,readTime:`29 min`,description:`Flow Matching asks how to train a continuous generative flow when the distribution-level velocity target is unavailable. Read it to see how per-example conditional paths create tractable regression labels, why the conditional and marginal objectives have identical gradients, how path geometry changes solver work, and why straight conditional paths do not prove globally straight transport.`,learns:[`How a neural velocity field transports source noise into the data distribution through an ODE.`,`Why conditional velocity regression has the same parameter gradient as the inaccessible marginal Flow Matching objective.`,`How to read the likelihood, FID, and solver-evaluation results without turning conditional straightness into a global optimal-transport claim.`],explore:{label:`Compare diffusion training in Fanout`,href:`/daily/2026-09-24-diffusion-policy-robot-actions`,description:`Connect Flow Matching's velocity regression to a diffusion model that denoises whole robot-action sequences and replans from fresh observations.`},preview:{badge:`FLOW MATCHING`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-09-30-gated-attention-language-models`,date:`2026-09-30`,url:`https://arxiv.org/abs/2505.06708`,title:`Gated Attention for Large Language Models: Non-linearity, Sparsity, and Attention-Sink-Free`,authors:`Zihan Qiu et al.`,venue:`NeurIPS 2025 Best Paper`,lane:`AI Research`,difficulty:`Medium`,readTime:`27 min`,description:`Gated Attention asks what happens when an attention head can decline to write its result. Read it to see why softmax's sum-to-one rule encourages sink behavior, how a query-dependent sigmoid gate after SDPA separates reading from writing, which ablations make that explanation credible, and where missing error bars, full-attention cost, and an incomplete long-context theory bound the result.`,learns:[`Why softmax can choose where to read without representing that no visible token is useful enough to write forward.`,`Why the strongest gate is post-SDPA, query-dependent, head-specific, multiplicative, and free to approach zero.`,`How to read the perplexity, training-stability, sink, and 128k RULER results without turning them into a universal speedup or proven causal theory.`],explore:{label:`Review QKV and attention sinks in Fanout`,href:`/inference-eng/curriculum/02-02`,description:`Connect the paper's write gate to the attention-head interface, causal masking, first-token sinks, and the residual stream it modifies.`},preview:{badge:`GATED ATTENTION`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`attention`}},{id:`2026-09-29-llms-lost-multi-turn-conversation`,date:`2026-09-29`,url:`https://arxiv.org/abs/2505.06120v1`,title:`LLMs Get Lost In Multi-Turn Conversation`,authors:`Philippe Laban et al.`,venue:`ICLR 2026 Outstanding Paper`,lane:`AI Research`,difficulty:`Easy`,readTime:`36 min`,description:`LLMs Get Lost In Multi-Turn Conversation asks whether a model that solves a complete one-shot instruction remains dependable when the same requirements arrive over several turns. Read it to see how instruction sharding holds the intended task fixed, why best-case aptitude hides a 112% rise in unreliability, which recap and temperature interventions fall short, and where an idealized simulated user limits the result.`,learns:[`How Full, Concat, and Sharded delivery separate instruction rewriting from multi-turn information timing.`,`Why repeated simulations need both an aptitude measure and an unreliability range instead of one average score.`,`How to read the 39% average degradation, partial mitigations, episodic translation control, and simulator limits without turning them into claims about natural user behavior.`],explore:{label:`Compare the ReAct loop in Fanout`,href:`/daily/2026-08-10-react-reasoning-acting`,description:`Connect multi-turn requirement delivery to an explicit action-observation loop, where the model's own earlier outputs also become part of the next decision context.`},preview:{badge:`MULTI-TURN RELIABILITY`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-09-28-human-level-control-dqn`,date:`2026-09-28`,url:`https://www.nature.com/articles/nature14236`,title:`Human-level control through deep reinforcement learning`,authors:`Volodymyr Mnih et al.`,venue:`Nature 2015`,lane:`AI Research`,difficulty:`Medium`,readTime:`32 min`,description:`DQN is remembered for learning Atari games from pixels. Read it for the less obvious result: why naive deep Q-learning chases its own moving data and targets, and how shuffled replay plus a delayed target network made that feedback loop trainable across 49 games.`,learns:[`Why a neural value function changes its own data distribution and bootstrap labels as it learns.`,`How experience replay and a delayed target network stabilize different parts of the same feedback loop.`,`How to read the five-game component ablation and the 49-game benchmark without turning either into a general superhuman-agent claim.`],explore:{label:`Explore deep Q-learning in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Adeep-q-learning-dqn`,description:`Connect replay buffers and bootstrap targets to reinforcement learning, temporal-difference updates, exploration, and later value-based agents.`},preview:{badge:`DEEP Q-NETWORK`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-orange) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-09-27-vision-transformer-image-patches`,date:`2026-09-27`,url:`https://openreview.net/forum?id=YicbFdNTTy`,title:`An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale`,authors:`Alexey Dosovitskiy et al.`,venue:`ICLR 2021`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`Vision Transformer asks how much image-specific structure a model needs when pre-training data becomes very large. Read it to see how a 224-pixel image becomes 196 patch tokens, which convolutional priors disappear, why ResNets lead at smaller scale, where ViT crosses over, and how patch size turns visual detail into a quadratic token-pair bill.`,learns:[`How non-overlapping image patches, a shared projection, learned positions, and one class token create a Transformer sequence.`,`Why removing locality and translation equivariance hurts at smaller data scales but can pay off after large-scale pre-training.`,`How to read the data crossover, compute comparison, attention analysis, and private JFT dependence without turning them into a universal no-convolution claim.`],explore:{label:`Explore Vision Transformer in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Avision-transformer-vit`,description:`Connect patch tokens to self-attention, position embeddings, transfer learning, image resolution, and the vision models that followed.`},preview:{badge:`VISION TRANSFORMER`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-26-swe-agent-computer-interfaces`,date:`2026-09-26`,url:`https://proceedings.neurips.cc/paper_files/paper/2024/hash/5a7c947568c1b1328ccc5230172e1e7c-Abstract-Conference.html`,title:`SWE-agent: Agent-Computer Interfaces Enable Automated Software Engineering`,authors:`John Yang et al.`,venue:`NeurIPS 2024`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`SWE-agent asks how much software-agent capability comes from the language model and how much comes from the interface around it. Read it to see why summarized search, 100-line file windows, precise edits, lint feedback, and compressed history help one fixed model repair more repositories—and why a 12.47% resolve rate is mechanism evidence rather than production autonomy.`,learns:[`Why an agent-computer interface controls both the actions a model can express and the repository state it can observe.`,`How the search, viewer, editor, linting, and history ablations isolate interface choices around a fixed model.`,`How to read SWE-bench pass@1, API cost, sandboxing, patch quality, and manually tuned interfaces without turning a benchmark result into a deployment claim.`],explore:{label:`Compare the ReAct loop in Fanout`,href:`/daily/2026-08-10-react-reasoning-acting`,description:`Connect SWE-agent's software-specific workbench to the more general reasoning-and-acting loop that alternates model actions with environment observations.`},preview:{badge:`SWE-AGENT`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-25-model-agnostic-meta-learning`,date:`2026-09-25`,url:`https://proceedings.mlr.press/v70/finn17a.html`,title:`Model-Agnostic Meta-Learning for Fast Adaptation of Deep Networks`,authors:`Chelsea Finn, Pieter Abbeel, and Sergey Levine`,venue:`ICML 2017`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`MAML asks whether training should optimize a model's answer before adaptation or the quality of the answer after a few task-specific gradient steps. Read it to see how support and query examples create a nested objective, why one initialization can move toward several related tasks, what the sinusoid and MiniImageNet results establish, and where task shift and second-order cost bound the claim.`,learns:[`How a task becomes one outer-loop training example through separate support and query data.`,`Why the meta-objective changes the usefulness of a local gradient rather than merely lowering pre-adaptation loss.`,`How to read the MiniImageNet, sinusoid, and first-order results without turning related-task adaptation into a universal capability.`],explore:{label:`Explore gradient descent in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Agradient-descent`,description:`Connect MAML's inner and outer loops to the optimization primitive that moves both task-specific parameters and their shared initialization.`},preview:{badge:`MAML`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-09-24-diffusion-policy-robot-actions`,date:`2026-09-24`,url:`https://doi.org/10.1177/02783649241273668`,title:`Diffusion Policy: Visuomotor Policy Learning via Action Diffusion`,authors:`Cheng Chi et al.`,venue:`The International Journal of Robotics Research, 2024`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`Diffusion Policy asks how a robot can imitate demonstrations when several incompatible action sequences are all valid. Read it to see how denoising samples one coherent action chunk, why the controller predicts farther than it executes, how that receding horizon corrects drift, and what the reported 46.9% relative improvement, real-robot results, latency, and evaluation protocol actually establish.`,learns:[`Why averaging demonstrations can create an action that belongs to no successful strategy, while diffusion can sample one mode at a time.`,`How observation, prediction, and execution horizons turn a denoised action sequence into a feedback controller.`,`How to read the 15-task evaluation, 46.9% relative improvement, real Push-T result, and unresolved inference-step discrepancy without overstating them.`],explore:{label:`Explore open robotics in Fanout`,href:`/open-robotics`,description:`Connect action diffusion to Fanout's robotics path, where perception, imitation data, control frequency, embodiment, and deployment constraints meet in one physical system.`},preview:{badge:`DIFFUSION POLICY`,accent:`var(--ga-cat-green)`,background:`color-mix(in srgb, var(--ga-cat-green) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-09-23-constitutional-ai-feedback`,date:`2026-09-23`,url:`https://arxiv.org/abs/2212.08073`,title:`Constitutional AI: Harmlessness from AI Feedback`,authors:`Yuntao Bai et al.`,venue:`Anthropic technical report, 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`Constitutional AI asks whether a short, explicit set of principles can replace repeated human harmlessness labels without reducing safety to blanket refusal. Read it to see how one rulebook produces self-revised demonstrations and AI-labelled response preferences, why the policy still depends on human helpfulness data and evaluation, and how inaccurate critiques, judge capability, principle choice, and reward over-optimization bound the result.`,learns:[`How sampled principles turn a model's first response into critiques, revisions, and supervised training targets.`,`How an AI feedback model converts the same kind of principles into soft pairwise labels for a preference model and reinforcement learning.`,`Why removing direct human harmlessness labels does not remove human values, evaluation, red-team prompts, or reward-model failure modes.`],explore:{label:`Compare the RLHF pipeline in Fanout`,href:`/daily/2026-07-31-instructgpt`,description:`Compare Constitutional AI's source of harmlessness preferences with InstructGPT's human-ranked responses, while keeping the supervised, reward-model, and policy-optimization stages distinct.`},preview:{badge:`CONSTITUTIONAL AI`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-22-spectre-speculative-execution`,date:`2026-09-22`,url:`https://spectreattack.com/spectre.pdf`,title:`Spectre Attacks: Exploiting Speculative Execution`,authors:`Paul Kocher et al.`,venue:`IEEE Symposium on Security and Privacy 2019`,lane:`Systems`,difficulty:`Medium`,readTime:`30 min`,description:`Spectre asks how code can read a secret even when a correct bounds check rejects the access. Read it to see how branch-predictor training opens a transient wrong path, how one secret-indexed cache line survives architectural rollback, and why process isolation, timer changes, compiler barriers, and processor controls each cover only part of the hardware-software contract.`,learns:[`Why speculative execution can perform a forbidden load without ever committing its register result.`,`How a secret byte selects one probe-array cache line and later timing turns that physical trace back into data.`,`Why Spectre mitigations target different ingredients of the attack and cannot be treated as one universal patch.`],explore:{label:`Explore security boundaries in Fanout`,href:`/system/archive/security-and-abuse-prevention`,description:`Connect Spectre's processor-level boundary failure to Fanout's application security path, where authorization, isolation, rate limits, and observable abuse controls make each trust boundary testable.`},preview:{badge:`SPECTRE`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-yellow) 9%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-21-leaderboard-illusion`,date:`2026-09-21`,url:`https://doi.org/10.52202/085713-2620`,title:`The Leaderboard Illusion`,authors:`Shivalika Singh et al.`,venue:`NeurIPS 2025`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`The Leaderboard Illusion asks what a live model ranking measures when some providers can privately test many candidates, keep only the strongest score, see more of the prompt distribution, or leave old models in a changing comparison graph. Read it to see why best-of-N selection lifts an observed maximum, how the authors audited private variants and prompt access, and where overlapping intervals, private data, disputed interpretations, and synthetic deprecation studies limit the verdict.`,learns:[`Why selecting the highest of several noisy or genuinely different candidate scores changes what one public leaderboard entry represents.`,`How the audit combines public battle data, identity-based private-model scraping, provider API traffic, controlled submissions, and simulations.`,`Which findings Arena disputed, which policy changes it announced, and what evidence is still needed to separate measurement noise from real model improvement.`],explore:{label:`Read Fanout's model-evaluation guide`,href:`/ai/articles`,description:`Continue from one live leaderboard to Fanout's broader evaluation reading list, where benchmark datasets, judges, prompts, and harness choices stay attached to every reported score.`},preview:{badge:`LEADERBOARD AUDIT`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-09-20-alphafold-protein-structure`,date:`2026-09-20`,url:`https://doi.org/10.1038/s41586-021-03819-2`,title:`Highly accurate protein structure prediction with AlphaFold`,authors:`John Jumper et al.`,venue:`Nature 2021`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`AlphaFold asks how a computer can turn an amino-acid sequence into a useful three-dimensional protein structure. Read it to see how evolutionary sequence evidence and residue-pair geometry continually constrain one another, how a structure module and recycling refine explicit atomic coordinates, and why per-residue confidence, missing biological context, and shallow alignments still bound what a prediction can establish.`,learns:[`How the Evoformer keeps a multiple-sequence alignment and a residue-pair map in continuous conversation.`,`Why triangle-shaped pair updates, local residue frames, invariant point attention, and recycling support one compatible 3D hypothesis.`,`What the blinded CASP14 results and pLDDT confidence validate, and why a predicted structure is not proof of function, dynamics, or one physical folding path.`],explore:{label:`Explore attention in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aattention`,description:`Connect AlphaFold's sequence, pair, and geometry-aware attention to Fanout's broader attention concept map, then compare how other architectures choose what information should interact.`},preview:{badge:`ALPHAFOLD`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-19-skip-lists-probabilistic-balancing`,date:`2026-09-19`,url:`https://doi.org/10.1145/78973.78977`,title:`Skip Lists: A Probabilistic Alternative to Balanced Trees`,authors:`William Pugh`,venue:`Communications of the ACM 1990`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`Skip Lists asks whether a sorted linked list can search like a balanced tree without rotations or global rebalancing. Read it to see how random node heights create sparse express lanes, how an advance-or-drop search finds a key in expected logarithmic time, and why the result trades a strict worst-case guarantee for simpler local updates and a tunable pointer budget.`,learns:[`How randomly promoted node towers turn one sorted base list into progressively sparser express levels.`,`Why search advances while the next pointer stays below the target, then drops a level when the next jump would overshoot.`,`How promotion probability trades pointer space, constant factors, and run-time variability without creating a worst-case guarantee.`],explore:{label:`Explore database indexing in Fanout`,href:`/system/archive/database-indexing`,description:`Connect the skip list's in-memory ordered-dictionary mechanism to Fanout's broader indexing path, including B-trees, page locality, query shapes, and the storage boundary that changes which structure fits.`},preview:{badge:`SKIP LISTS`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-18-raid-redundant-disk-arrays`,date:`2026-09-18`,url:`https://doi.org/10.1145/50202.50214`,title:`A Case for Redundant Arrays of Inexpensive Disks (RAID)`,authors:`David A. Patterson, Garth A. Gibson, and Randy H. Katz`,venue:`ACM SIGMOD 1988`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`The RAID paper asks how many small disks can deliver more I/O without making storage collapse whenever one device fails. Read it to see how striping exposes parallelism, how mirrors or XOR parity make one missing disk reconstructable, and why rotating the parity position removes a dedicated check-disk bottleneck without proving modern latency or whole-system durability.`,learns:[`Why an unprotected array encounters a disk failure sooner even as more independent devices increase potential I/O bandwidth.`,`How one parity bit per stripe lets the array reconstruct any single known missing bit from the survivors.`,`Why RAID levels trade storage overhead, small-write work, and parallelism, and which failure assumptions bound the paper's reliability arithmetic.`],explore:{label:`Explore object-storage durability in Fanout`,href:`/system/archive/object-storage-durability-and-replication`,description:`Connect one-array reconstruction to Fanout's broader object-storage durability path, where replicas, failure domains, integrity checks, and recovery policies protect bytes beyond a single disk group.`},preview:{badge:`RAID`,accent:`var(--ga-cat-green)`,background:`color-mix(in srgb, var(--ga-cat-green) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-17-relational-model-data-banks`,date:`2026-09-17`,url:`https://doi.org/10.1145/362384.362685`,title:`A Relational Model of Data for Large Shared Data Banks`,authors:`E. F. Codd`,venue:`Communications of the ACM 1970`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`Codd's relational model paper asks why an application program should break when the machine reorganizes the data it reads. Read it to see how describing everything as flat relations with keys removes ordering, indexing, and access-path dependence, how normalization copies a parent key downward to flatten nested records, and why the model deliberately leaves language syntax, implementation, and performance as open problems.`,learns:[`Why a program written for one of five equivalent tree layouts fails on at least three of the others, and what it means for row order and access paths to be invisible to users.`,`How normalization copies each parent's primary key into its subordinate relations until every domain is simple and the whole bank fits in flat arrays without pointers.`,`Why the natural join is the only join when the shared column is a function, and why following stored pointer paths answers the wrong question in the connection trap.`],explore:{label:`Explore relational database design in Fanout`,href:`/system/archive/relational-database-design`,description:`Connect Codd's relations, keys, and normalization to Fanout's schema design path, including table shapes, foreign keys, indexing choices, and how schemas evolve without breaking readers.`},preview:{badge:`RELATIONAL MODEL`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-16-neural-translation-soft-attention`,date:`2026-09-16`,url:`https://arxiv.org/abs/1409.0473`,title:`Neural Machine Translation by Jointly Learning to Align and Translate`,authors:`Dzmitry Bahdanau, Kyunghyun Cho, and Yoshua Bengio`,venue:`ICLR 2015`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`This paper asks how a translation model can look back at the right source words instead of compressing an entire sentence into one fixed vector. Read it to see how a bidirectional encoder leaves one annotation at every source position, how a jointly trained alignment scorer builds a fresh weighted context for each target word, and why strong WMT14 results still need careful treatment of unknown words, sequence length, exhaustive scoring, and causal claims.`,learns:[`Why one fixed context vector can become a bottleneck, and how per-position source annotations keep the sentence addressable.`,`How alignment scores, softmax weights, and a weighted sum produce a different context vector for every target word.`,`What the WMT14 BLEU and long-sentence results establish, and where vocabulary, compute, and architectural confounders limit the conclusion.`],explore:{label:`Explore attention in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aattention`,description:`Connect this recurrent target-to-source mechanism to Fanout's attention concept map, then continue into self-attention, cross-attention, Transformers, and modern language models.`},preview:{badge:`SOFT ATTENTION`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`attention`}},{id:`2026-09-15-jpeg-still-picture-compression`,date:`2026-09-15`,url:`https://doi.org/10.1145/103085.103089`,title:`The JPEG Still Picture Compression Standard`,authors:`Gregory K. Wallace`,venue:`Communications of the ACM 1991`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`The JPEG paper asks how a photograph can become much smaller without looking obviously broken. Read it to see how each 8 × 8 block becomes a set of spatial-frequency coefficients, why coefficient quantization is the deliberately lossy step, and how zig-zag ordering plus Huffman coding pack the surviving structure without pretending that one quality setting fits every image or display.`,learns:[`Why the discrete cosine transform changes an 8 × 8 block's coordinates without itself discarding image information.`,`How a 64-entry quantization table trades coefficient precision for more zeros, and why that trade depends on image and viewing conditions.`,`How differential DC coding, low-to-high-frequency zig-zag order, and Huffman coding compress the quantized symbols without adding another lossy step.`],explore:{label:`Compare with LZ77 in Fanout`,href:`/daily/2026-09-02-lz77-sequential-compression`,description:`Contrast JPEG's deliberate loss of coefficient precision with LZ77's exact reuse of repeated byte sequences, then separate representation loss from lossless symbol packing.`},preview:{badge:`JPEG`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-yellow) 9%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-14-darpa-internet-design`,date:`2026-09-14`,url:`https://www.cs.princeton.edu/courses/archive/spring14/cos461/papers/clark88.pdf`,title:`The Design Philosophy of the DARPA Internet Protocols`,authors:`David D. Clark`,venue:`ACM SIGCOMM 1988`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`The DARPA Internet design paper asks why a conversation should survive when a router or network disappears beneath it. Read it to see how fate-sharing keeps essential connection state at the endpoint hosts, why the network forwards independent datagrams, and where alternate paths, routing recovery, host behavior, management, accounting, and security remain outside that elegant core.`,learns:[`Why survivability outranked service variety, network variety, cost, attachment effort, and accountability in the architecture's ordered goals.`,`How fate-sharing places sequence, acknowledgment, and flow-control state with the hosts whose conversation that state describes.`,`Why stateless datagram forwarding makes failure recovery possible but does not itself supply another path, fast reconvergence, management, accounting, or security.`],explore:{label:`Explore TCP and UDP in Fanout`,href:`/system/archive/tcp-vs-udp`,description:`Connect the paper's datagram foundation and separated transport services to Fanout's practical guide to TCP streams, UDP datagrams, reliability, ordering, congestion control, and application tradeoffs.`},preview:{badge:`INTERNET DESIGN`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-13-deepseek-v4-1-flash`,date:`2026-09-13`,url:`https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash/blob/dba1be0a40aa45a94ad051997016db3960a90277/DeepSeek_V41_Tech_Report.pdf`,title:`DeepSeek-V4.1-Flash: Pushing the Limits of KV Cache Compression`,authors:`DeepSeek-AI`,venue:`Technical Report 2026`,lane:`Inference`,difficulty:`Medium`,readTime:`30 min`,description:`DeepSeek-V4.1-Flash asks how a million-token agent can keep attention memory from overwhelming accelerator memory, persistent storage, and transfer bandwidth. Read it to see how a causal encoder-decoder shares compressed global context across depth, how three CSA2 layer modes divide cache and indexing work, and why bounded replay makes an explicit approximation to avoid persisting local attention state.`,learns:[`How a 20-layer causal encoder produces shared global context for a 20-layer decoder, reducing prompt-side activation from 16B to 8B parameters per token.`,`How CSA2 Full, Reindex, and Reuse modes share global KV and sparse selections while preserving layer-local queries and sliding-window state.`,`Why 890-byte global KV and one-eighth persistent cache are separate claims, and where approximate bounded replay can fail.`],explore:{label:`Calculate KV-cache memory in Fanout`,href:`/labs/kv-cache`,description:`Connect the report's cross-layer sharing, cache precision, and context-length claims to the layer-by-layer memory arithmetic of an inference workload.`},preview:{badge:`KV CACHE`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`attention`}},{id:`2026-09-12-quicksort-partition`,date:`2026-09-12`,url:`https://academic.oup.com/comjnl/article/5/1/10/395338`,title:`Quicksort`,authors:`C. A. R. Hoare`,venue:`The Computer Journal 1962`,lane:`Systems`,difficulty:`Very Easy`,readTime:`30 min`,description:`Quicksort asks how one value can turn a disorderly table into two smaller sorting problems without copying everything into a merge buffer. Read it to see how two pointers scan inward around a chosen bound, exchange values found on the wrong sides, and leave independent segments whose balance determines the amount of work still ahead.`,learns:[`How inward scans manufacture a dividing line where every lower-side key is no greater than every upper-side key.`,`Why sorting the two resulting segments needs no merge step, and how a LIFO nest plus smaller-side-first processing limits postponed work.`,`Why the paper's expected comparison count depends on random bound rank, and why its National-Elliott 405 timing table is useful but historically narrow.`],explore:{label:`Continue with Dijkstra's shortest-path algorithm`,href:`/daily/2026-08-30-dijkstra-shortest-path`,description:`Follow Quicksort with another foundational algorithm guide and compare partitioning a table with settling the cheapest reachable frontier in a graph.`},preview:{badge:`QUICKSORT`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-orange) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-09-11-lamport-logical-clocks`,date:`2026-09-11`,url:`https://lamport.azurewebsites.net/pubs/time-clocks.pdf`,title:`Time, Clocks, and the Ordering of Events in a Distributed System`,authors:`Leslie Lamport`,venue:`Communications of the ACM 1978`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`Lamport asks how separated computers can agree on a useful event order when no perfect global clock tells them what happened first. Read it to see how local event order and delivered messages define causality, how message-carried logical counters preserve that order, and why the resulting timestamps still cannot prove that two events influenced one another.`,learns:[`How same-process order, message send before receive, and transitivity define the happened-before partial order while unrelated events remain concurrent.`,`Why each process increments a logical counter and advances it beyond a received timestamp before recording the receive event.`,`How a fixed tie-breaker extends causality to a useful but arbitrary total order, and which delivery, participation, external-causality, and physical-time limits remain.`],explore:{label:`Explore clocks and ordering in Fanout`,href:`/system/archive/clocks-and-ordering`,description:`Connect Lamport's logical clock to Fanout's practical guide for wall clocks, monotonic time, version vectors, consensus logs, time-sortable IDs, and correctness-sensitive ordering.`},preview:{badge:`LOGICAL TIME`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-10-yolo-unified-object-detection`,date:`2026-09-10`,url:`https://openaccess.thecvf.com/content_cvpr_2016/html/Redmon_You_Only_Look_CVPR_2016_paper.html`,title:`You Only Look Once: Unified, Real-Time Object Detection`,authors:`Joseph Redmon, Santosh Divvala, Ross Girshick, and Ali Farhadi`,venue:`CVPR 2016`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`YOLO asks how a computer can locate and name every object in an image quickly enough for live video. Read it to see how one full-image network fills a fixed responsibility grid with boxes and class scores, why that unified prediction runs in real time, and where coarse spatial capacity trades localization accuracy for speed.`,learns:[`How the cell containing an object's center takes responsibility and turns a variable scene into a fixed 7 × 7 × 30 prediction tensor on PASCAL VOC.`,`Why class-specific confidence combines object presence, predicted-versus-truth overlap, and conditional class probability before thresholding and duplicate removal.`,`What the paper's VOC speed, mAP, localization, background-error, small-object, objective, and historical-hardware limits do and do not establish.`],explore:{label:`Explore convolutional networks in Fanout`,href:`/knowledge-graph?node=ai-research%3Acategory%3Aglossary-architecture&detail=ai-research%3Aconcept%3Acnn`,description:`Connect YOLO's full-image feature extractor to Fanout's convolutional-network concept, then continue into image representations, spatial features, and later vision architectures.`},preview:{badge:`YOLO`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-09-rsync-rolling-checksum`,date:`2026-09-09`,url:`https://openresearch-repository.anu.edu.au/items/15a1c428-0ad3-49d6-bb54-9238250cbbf0`,title:`The rsync algorithm`,authors:`Andrew Tridgell and Paul Mackerras`,venue:`ANU Technical Report TR-CS-96-05, 1996`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`The rsync algorithm asks how one machine can update a remote file without sending the whole file or first collecting both versions. Read it to see how destination block signatures, a rolling checksum at every source offset, strong confirmation, and a stream of block references plus literal bytes preserve reuse even after an edit shifts every later boundary.`,learns:[`Why fixed-position block comparison loses unchanged content after an insertion, while an all-offset rolling window can find it again.`,`How a cheap 32-bit rolling checksum filters candidates before the report's 128-bit MD4 checksum confirms a reusable destination block.`,`What the 1996 Linux and Samba measurements show, and how signature traffic, sender CPU, receiver I/O, block size, collisions, and modern protocol changes limit the claim.`],explore:{label:`Explore remote file sync in Fanout`,href:`/system/archive/remote-file-sync-design`,description:`Connect rsync's delta-transfer mechanism to Fanout's system-design guide for file metadata, chunking, object storage, conflict handling, resumability, and production sync tradeoffs.`},preview:{badge:`RSYNC`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-09-08-btree-ordered-index`,date:`2026-09-08`,url:`https://doi.org/10.1007/BF00288683`,title:`Organization and Maintenance of Large Ordered Indices`,authors:`Rudolf Bayer and Edward M. McCreight`,venue:`Acta Informatica 1972`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`The original B-tree paper asks how an index can keep searches and updates cheap when it is too large for memory and every disk access is expensive. Read it to see why one page should hold many sorted separators, how a full page splits around its median, and how equal leaf depth keeps a changing index shallow.`,learns:[`Why matching one tree node to one disk-transfer page turns many in-page comparisons into a single expensive storage access.`,`How sorted separators route a search and how promoting the median of a full page creates two siblings without breaking order or balance.`,`Which occupancy, height, device-cost, workload, concurrency, and recovery limits separate the 1972 result from a complete modern database index.`],explore:{label:`Explore B-trees in Fanout`,href:`/system/archive/b-tree`,description:`Connect Bayer and McCreight's page-shaped balanced tree to Fanout's practical B-tree guide, database indexing, page splits, storage engines, and later B+ tree designs.`},preview:{badge:`B-TREE`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-07-backpropagation-hidden-representations`,date:`2026-09-07`,url:`https://doi.org/10.1038/323533a0`,title:`Learning representations by back-propagating errors`,authors:`David E. Rumelhart, Geoffrey E. Hinton, and Ronald J. Williams`,venue:`Nature 1986`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`Back-propagation asks how a hidden layer can learn useful features when a teacher specifies only the desired output. Read it to see how a forward pass stores activations, an output mismatch travels backward as chained derivatives, and each connection receives a local weight update that can organize hidden units around the task's structure.`,learns:[`Why hidden units create a credit-assignment problem: unlike output units, they have no teacher-provided target state.`,`How the chain rule sends output-error derivatives backward through the same weighted connections and produces a gradient for every weight.`,`What the mirror-symmetry and family-tree examples demonstrate, and why local minima, biological plausibility, historical priority, and missing reproduction details still limit the claim.`],explore:{label:`Explore backpropagation in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Abackpropagation`,description:`Connect the paper's two-pass derivative procedure to Fanout's backpropagation node, chain rule, gradient descent, activation functions, and from-scratch neural-network path.`},preview:{badge:`BACKPROPAGATION`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-06-diffie-hellman-key-agreement`,date:`2026-09-06`,url:`https://doi.org/10.1109/TIT.1976.1055638`,title:`New Directions in Cryptography`,authors:`Whitfield Diffie and Martin E. Hellman`,venue:`IEEE Transactions on Information Theory 1976`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`Diffie and Hellman ask how two people who have never exchanged a secret can agree on one over a public network. Read it to see how private exponents and exchanged modular powers meet at the same shared value, why reversing a public value is meant to be difficult, and why authentication must still stop an active intermediary from substituting keys.`,learns:[`Why advance pairwise secret delivery grows poorly as a network adds users, even before anyone sends an encrypted message.`,`How each party keeps one exponent private, publishes one modular power, and combines the other public value with its own secret to derive the same result.`,`Why the algebra blocks a passive eavesdropper only under hard-problem assumptions, while authentication, key derivation, parameter validation, and symmetric encryption remain separate protocol duties.`],explore:{label:`Explore public-key cryptography in Fanout`,href:`/daily/2026-08-16-tor-onion-router`,description:`Continue into Fanout's Tor paper guide and see ephemeral Diffie-Hellman used inside a larger authenticated, layered protocol with separate relay keys and threat assumptions.`},preview:{badge:`KEY AGREEMENT`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-09-05-consistent-hashing-random-trees`,date:`2026-09-05`,url:`https://doi.org/10.1145/258533.258660`,title:`Consistent Hashing and Random Trees: Distributed Caching Protocols for Relieving Hot Spots on the World Wide Web`,authors:`David Karger, Eric Lehman, Tom Leighton, Matthew Levine, Daniel Lewin, and Rina Panigrahy`,venue:`STOC 1997`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`Consistent Hashing and Random Trees asks how a distributed cache can absorb membership changes and flash crowds without throwing away nearly every placement decision. Read it to see how stable item and cache positions localize reassignment, how monotonicity limits movement, and how a different random cache tree for each page spreads hot demand.`,learns:[`Why a conventional hash whose range depends on the cache count can remap almost every object when one cache joins or leaves.`,`How the paper maps items and replicated cache points to a fixed unit interval, then uses monotonicity to prevent movement between two old caches.`,`How balance, spread, load, random cache trees, and explicit model assumptions qualify the paper's theoretical hot-spot guarantees.`],explore:{label:`Explore consistent hashing in Fanout`,href:`/system/archive/consistent-hashing`,description:`Connect the original closest-point construction to Fanout's practical hash-ring guide, including virtual nodes, membership convergence, warmup, and hot-key limits.`},preview:{badge:`CONSISTENT HASHING`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-04-ethernet-distributed-packet-switching`,date:`2026-09-04`,url:`https://doi.org/10.1145/360248.360253`,title:`Ethernet: Distributed Packet Switching for Local Computer Networks`,authors:`Robert M. Metcalfe and David R. Boggs`,venue:`Communications of the ACM 1976`,lane:`Systems`,difficulty:`Very Easy`,readTime:`30 min`,description:`Ethernet asks how many computers can share one inexpensive local medium without a central traffic controller. Read it to see how a passive broadcast cable, carrier sensing, collision detection, brief jamming, and adaptive random backoff turn simultaneous packet attempts into distributed coordination.`,learns:[`How a passive branching Ether broadcasts each addressed packet while destination stations decide locally whether to copy it.`,`Why listening before transmission reduces collisions but propagation delay still permits simultaneous starts, making rapid detection and shared collision consensus necessary.`,`How repeated collisions double the mean random retry interval, what the paper's heavy-load efficiency model actually assumes, and which reliability duties remain above the link.`],explore:{label:`Explore packet transport in Fanout`,href:`/system/archive/tcp-vs-udp`,description:`Move up one abstraction layer from Ethernet's shared-medium packet delivery to Fanout's comparison of reliable TCP byte streams and UDP datagrams.`},preview:{badge:`ETHERNET`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-03-gpt3-few-shot-learners`,date:`2026-09-03`,url:`https://arxiv.org/abs/2005.14165v4`,title:`Language Models are Few-Shot Learners`,authors:`Brown et al.`,venue:`NeurIPS 2020`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`GPT-3 asks whether one pretrained language model can take on a new task from text alone, without changing its weights. Read it to see how an instruction and zero, one, or several worked examples turn the prompt into a temporary task specification, why larger models used that context more effectively on many benchmarks, and where the result remained uneven or contaminated.`,learns:[`How zero-shot, one-shot, and few-shot prompting change the examples inside the context while the pretrained model weights remain fixed.`,`Why next-token prediction can continue a demonstrated input-output pattern, how a finite context limits the teaching set, and why more examples are not always better.`,`How the paper's CoQA and SuperGLUE results coexist with chance-level WiC, benchmark-overlap concerns, high compute cost, bias, and uncertainty about task learning versus task recognition.`],explore:{label:`Explore few-shot learning in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Afew-shot-learning`,description:`Connect GPT-3's prompt-only task adaptation to Fanout's few-shot-learning node, autoregressive models, prompt engineering, chain-of-thought, and later in-context methods.`},preview:{badge:`GPT-3`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-09-02-lz77-sequential-compression`,date:`2026-09-02`,url:`https://doi.org/10.1109/TIT.1977.1055714`,title:`A Universal Algorithm for Sequential Data Compression`,authors:`Jacob Ziv and Abraham Lempel`,venue:`IEEE Transactions on Information Theory 1977`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`LZ77 asks how to compress a stream exactly when its source statistics are unknown. Read it to see how a bounded window turns recent output into a moving dictionary, replaces the longest reachable repeat with a backward pointer and length, and keeps encoder and decoder synchronized with one following literal.`,learns:[`How recent decoded output becomes an adaptive dictionary without a separate training pass or a source-specific code book.`,`Why each source word is a longest reproducible prefix plus one literal, and how pointer range and maximum match length bound the codeword.`,`Why the paper's universality theorem is scoped to constrained sources, why channel errors can propagate, and which familiar DEFLATE limits came later.`],explore:{label:`Explore information theory in Fanout`,href:`/knowledge-graph?node=ai-research%3Amodule%3Amath-fundamentals&detail=ai-research%3Aconcept%3Aentropy-and-information-theory`,description:`Connect LZ77's adaptive copying rule to Fanout's entropy and information-theory material, including source regularity, logarithmic code lengths, and lossless compression limits.`},preview:{badge:`LZ77`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-orange) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-09-01-alexnet-image-classification`,date:`2026-09-01`,url:`https://papers.nips.cc/paper_files/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html`,title:`ImageNet Classification with Deep Convolutional Neural Networks`,authors:`Alex Krizhevsky, Ilya Sutskever, and Geoffrey E. Hinton`,venue:`NeurIPS 2012`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`AlexNet asks how a deep image classifier can learn from 1.2 million examples without taking impossibly long to optimize or simply memorizing the training set. Read it to see how ReLU activations, a selectively connected two-GPU network, image augmentation, and dropout made an eight-layer convolutional model practical at ImageNet scale.`,learns:[`Why ReLU reached a fixed training-error threshold much sooner than tanh in the paper's controlled comparison, without implying one universal speedup.`,`How two 3 GB GPUs divided the feature maps, exchanged information at selected layers, and converged into one 1,000-class classifier.`,`How random crops, reflections, color perturbations, dropout, test-time crop averaging, and ensembles shape what the headline benchmark does and does not prove.`],explore:{label:`Explore convolutional networks in Fanout`,href:`/knowledge-graph?node=ai-research%3Acategory%3Aglossary-architecture&detail=ai-research%3Aconcept%3Acnn`,description:`Connect AlexNet's local filters and shared weights to Fanout's convolutional-network concept, then trace the later vision architectures that changed depth, normalization, and scaling.`},preview:{badge:`ALEXNET`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-31-cap-theorem`,date:`2026-08-31`,url:`https://doi.org/10.1145/564585.564601`,title:`Brewer’s Conjecture and the Feasibility of Consistent, Available, Partition-Tolerant Web Services`,authors:`Seth Gilbert and Nancy Lynch`,venue:`ACM SIGACT News 2002`,lane:`Systems`,difficulty:`Very Easy`,readTime:`30 min`,description:`The CAP theorem asks what a replicated service can promise when the network splits. Read it to see how one completed write and one later isolated read force an exact choice: answer from incomplete knowledge or wait for communication that may never return.`,learns:[`How the paper defines atomic consistency, availability, and partition tolerance for one distributed read/write object.`,`Why an isolated replica cannot distinguish a delayed write from a missing one, so answering now can be stale while waiting breaks termination.`,`Why timeouts and weaker consistency create practical policies without restoring all three guarantees under the theorem's assumptions.`],explore:{label:`Explore consistency models in Fanout`,href:`/system/archive/consistency-models`,description:`Continue into Fanout's consistency guide and compare linearizability, sequential, causal, session, and eventual guarantees against real product invariants.`},preview:{badge:`CAP`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-30-dijkstra-shortest-path`,date:`2026-08-30`,url:`https://doi.org/10.1007/BF01386390`,title:`A Note on Two Problems in Connexion with Graphs`,authors:`E. W. Dijkstra`,venue:`Numerische Mathematik 1959`,lane:`Systems`,difficulty:`Very Easy`,readTime:`30 min`,description:`Dijkstra's three-page paper asks how to find the shortest route through a weighted network without listing every possible path. Read it to see how a growing settled frontier, one tentative distance per reachable node, and a smallest-first choice turn a global route question into a sequence of local commitments.`,learns:[`How settled, frontier, and unseen node sets separate distances that are final from routes that are only the best found so far.`,`Why inspecting the newest settled node can shorten a neighbour's tentative route, and why the smallest tentative total is the next safe commitment.`,`Why non-negative edge weights protect that greedy commitment, how direction-dependent costs still fit, and why minimum spanning trees solve a different problem.`],explore:{label:`Explore graph systems in Fanout`,href:`/system/archive/graph-database-decision-boundary`,description:`Connect shortest-path search to Fanout's graph-system guide, including traversal depth, fanout, relationship storage, and the boundary between ordinary indexes and graph algorithms.`},preview:{badge:`PATH`,accent:`var(--ga-cat-green)`,background:`color-mix(in srgb, var(--ga-cat-green) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-29-generative-adversarial-nets`,date:`2026-08-29`,url:`https://proceedings.neurips.cc/paper_files/paper/2014/file/f033ed80deb0234979a61f95710dbe25-Paper.pdf`,title:`Generative Adversarial Nets`,authors:`Goodfellow, Pouget-Abadie, Mirza, Xu, Warde-Farley, Ozair, Courville, and Bengio`,venue:`NeurIPS 2014`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`Generative Adversarial Nets asks how a model can learn to create convincing new samples without an explicit likelihood or a Markov chain. Read it to see how a generator and discriminator turn that problem into a two-player game, why the ideal judge eventually answers one half, and why the elegant equilibrium does not make practical training automatically stable.`,learns:[`How a generator maps noise into samples while a discriminator learns to separate generated examples from real data and sends a useful gradient back.`,`Why the minimax objective reaches its ideal distribution-space optimum when generated and real distributions match and the best discriminator returns one half.`,`Why alternating updates, the non-saturating generator loss, synchronization, implicit density, discrete data, collapse, and limited evaluation keep the theorem separate from practical training.`],explore:{label:`Explore GANs in Fanout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Agan`,description:`Connect the original generator-discriminator game to Fanout's GAN glossary node, generative models, latent variables, backpropagation, and later adversarial objectives.`},preview:{badge:`GAN`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-08-28-kafka-distributed-log`,date:`2026-08-28`,url:`https://www.microsoft.com/en-us/research/wp-content/uploads/2017/09/Kafka.pdf`,title:`Kafka: a Distributed Messaging System for Log Processing`,authors:`Kreps, Narkhede, and Rao`,venue:`NetDB 2011`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`Kafka turns a queue into a retained distributed log. Append-only partitions hold ordered records while independent consumers pull from their own offsets, replay after failure, and advance at different speeds.`,learns:[`How a topic becomes ordered append-only partitions whose records are addressed by logical offsets rather than deleted after one consumer sees them.`,`Why consumers pull at their own pace and keep their own checkpoints, making independent replay possible while exposing duplicate-processing and retention tradeoffs.`,`How batching, sequential I/O, filesystem page cache, sendfile, and partition ownership produced the paper's 2011 throughput, and why its no-acknowledgement and no-replication limits matter.`],explore:{label:`Explore Kafka design on Fanout`,href:`/system/archive/source-kafka-design-docs`,description:`Continue into Fanout's Kafka source summary and connect partitions, offsets, consumer groups, retention, replay, replication, and stream-processing semantics to the modern system.`},preview:{badge:`KAFKA`,accent:`var(--ga-cat-orange)`,background:`color-mix(in srgb, var(--ga-cat-orange) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-08-27-webassembly-safe-portable-bytecode`,date:`2026-08-27`,url:`https://doi.org/10.1145/3062341.3062363`,title:`Bringing the Web up to Speed with WebAssembly`,authors:`Haas, Rossberg, Schuff, Titzer, Holman, Gohman, Wagner, Zakai, and Bastien`,venue:`PLDI 2017`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`WebAssembly asks how a browser can run low-level code from an untrusted download without tying that code to one language, CPU, or browser. Read it to see how a typed stack format, structured branches, bounded linear memory, and streaming validation make compact portable code safe enough to compile near native speed.`,learns:[`Why WebAssembly uses an implicit typed stack for compact transport while production engines compile that stack away into registers and machine code.`,`How structured control flow and a single-pass type validator rule out arbitrary jumps, incompatible stack joins, and invalid indirect calls before execution.`,`Why linear memory isolates module bytes from code and engine state, how an out-of-bounds access traps, and which host, feature, and 2017 benchmark limits remain.`],explore:{label:`Explore the software papers map`,href:`/blog/100-papers-to-understand-software-and-computing`,description:`Place WebAssembly beside virtual machines, compiler intermediate representations, language runtimes, operating-system isolation, browser security, and other foundational software papers.`},preview:{badge:`WASM`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-08-26-xgboost-scalable-tree-boosting`,date:`2026-08-26`,url:`https://arxiv.org/abs/1603.02754v3`,title:`XGBoost: A Scalable Tree Boosting System`,authors:`Chen and Guestrin`,venue:`KDD 2016`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`XGBoost asks how many small decision trees can correct one another without growing into an uncontrolled forest, and how that learning rule can survive sparse, billion-row data. Read it to connect additive leaf scores and regularized split gain to weighted candidate sketches, learned missing-value directions, cache-aware column blocks, and the system work behind a practical tabular-ML classic.`,learns:[`How each new tree contributes a signed leaf correction to the ensemble's current prediction instead of replacing what earlier trees learned.`,`Why a split survives only when its improvement clears a complexity cost, and how shrinkage and leaf-weight penalties restrain the corrections.`,`How weighted split candidates, learned default directions for missing values, sorted column blocks, prefetching, compression, and sharding turn the same learner into a scalable system.`],explore:{label:`Explore trees and ensemble methods`,href:`/roadmaps/ai-research`,description:`Open Fanout's AI roadmap and continue through decision trees, random forests, gradient boosting, XGBoost, regularization, and the tabular-model tradeoffs surrounding this paper.`},preview:{badge:`XGB`,accent:`var(--ga-cat-green)`,background:`color-mix(in srgb, var(--ga-cat-green) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-25-segment-anything`,date:`2026-08-25`,url:`https://openaccess.thecvf.com/content/ICCV2023/html/Kirillov_Segment_Anything_ICCV_2023_paper.html`,title:`Segment Anything`,authors:`Kirillov et al.`,venue:`ICCV 2023`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`Segment Anything asks whether one vision model can turn a point, box, or rough mask into the pixels of a reasonable object, even on unfamiliar images. Read it to see how one reusable image embedding, a lightweight prompt decoder, ambiguity-aware mask candidates, and a model-in-the-loop data engine make segmentation feel like an interface rather than a fixed label set.`,learns:[`How promptable segmentation replaces a fixed class vocabulary with spatial instructions while allowing several answers to be valid for one ambiguous point.`,`Why SAM computes the expensive image embedding once, then combines cheap prompt embeddings with a lightweight mask decoder for repeated interaction.`,`How the assisted, semi-automatic, and fully automatic data-engine stages produced SA-1B, and where fine structures, heavy encoding, text prompts, data coverage, and specialist tools still limit the result.`],explore:{label:`Explore Vision Transformers`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Avision-transformer-vit`,description:`Open Fanout's Vision Transformer concept and connect SAM's reusable image embedding to patches, attention, representation learning, and the encoder that dominates its per-image cost.`},preview:{badge:`SAM`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-08-24-google-borg-cluster-management`,date:`2026-08-24`,url:`https://research.google/pubs/large-scale-cluster-management-at-google-with-borg/`,title:`Large-scale cluster management at Google with Borg`,authors:`Verma et al.`,venue:`EuroSys 2015`,lane:`Systems`,difficulty:`Easy`,readTime:`40 min`,description:`Borg asks how one fleet can run latency-sensitive services and opportunistic batch work without wasting the space between their peaks. Read it to see how cells, jobs, tasks, priorities, limits, reservations, placement scoring, and a continuously repaired control plane turn heterogeneous machines into shared infrastructure.`,learns:[`How Borg separates a replicated control plane from per-machine Borglets and continuously reconciles desired jobs with observed task state.`,`Why scheduling first filters feasible machines and then scores them, while priority, limits, and reservations make mixed workloads practical.`,`What Google's measurements do and do not show about packing, reclaimed capacity, availability, isolation, and the cost of segregating workloads.`],explore:{label:`Explore distributed task scheduling`,href:`/system/archive/distributed-task-scheduler`,description:`Continue into Fanout's scheduler archive and connect Borg's cells, placement constraints, resource reclamation, priorities, and reconciliation loop to modern cluster schedulers.`},preview:{badge:`BORG`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`bars`}},{id:`2026-08-23-clip-natural-language-supervision`,date:`2026-08-23`,url:`https://proceedings.mlr.press/v139/radford21a.html`,title:`Learning Transferable Visual Models From Natural Language Supervision`,authors:`Radford et al.`,venue:`ICML 2021`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`CLIP asks how an image model can recognize categories described in words without training a new classifier for every task. Read it to see how two encoders turn a batch into an all-pairs similarity matrix, how the true image-text pairs teach a shared embedding space, and why prompts make zero-shot recognition flexible but not automatically reliable.`,learns:[`How a batch of N image-text pairs becomes N² candidate matches, with the observed pairs forming the target diagonal.`,`Why normalized image and text embeddings plus a symmetric contrastive loss make written class descriptions usable at inference time.`,`Where CLIP's promise stops: prompt wording, class taxonomies, English-centric web data, heavy compute, weak tasks, and deployment risk still matter.`],explore:{label:`Explore contrastive learning`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Acontrastive-learning`,description:`Open Fanout's contrastive-learning concept and connect CLIP's image-text matching objective to embeddings, cosine similarity, multimodal models, and zero-shot transfer.`},preview:{badge:`CLIP`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`matrix`}},{id:`2026-08-22-development-domain-name-system`,date:`2026-08-22`,url:`https://dl.acm.org/doi/10.1145/52324.52338`,title:`Development of the Domain Name System`,authors:`Mockapetris and Dunlap`,venue:`SIGCOMM 1988`,lane:`Systems`,difficulty:`Very Easy`,readTime:`30 min`,description:`This paper asks how the Internet can keep one usable naming system without making every machine download one global host file. Read it to see how DNS cuts a name tree into delegated zones, follows referrals toward the server responsible for one branch, and uses time-limited caching to make repeated lookups local.`,learns:[`Why the centrally maintained HOSTS.TXT file grew into a distribution and administration bottleneck as the Internet added workstations and local networks.`,`How hierarchical names, zone cuts, referrals, and authoritative servers distribute control while preserving one global name space.`,`Why TTL caching removes repeated upstream work, where stale answers enter the tradeoff, and how unexpected failed lookups motivated negative caching.`],explore:{label:`Browse Fanout systems labs`,href:`/labs`,description:`Continue with Fanout's published systems labs for hands-on practice with latency, caching, reliability, and the operational tradeoffs that sit around networked services.`},preview:{badge:`DNS`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-21-end-to-end-arguments`,date:`2026-08-21`,url:`https://web.mit.edu/saltzer/www/publications/endtoend/endtoendA4.pdf`,title:`End-to-End Arguments in System Design`,authors:`Saltzer, Reed, and Clark`,venue:`ACM TOCS, 1984`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`This paper asks where a system should place reliability, delivery, security, and duplicate-suppression guarantees. Read it to see why a lower layer can make failures rarer yet still cannot certify the application result, and why the final check belongs at the endpoints that understand what success means.`,learns:[`Why packet checks and local retries cannot replace a checksum that covers the file from source storage through destination storage.`,`How lower-layer reliability can improve performance without becoming the source of application correctness.`,`Why the right endpoints change with the application, and why end-to-end is a design argument rather than a ban on smart networks.`],explore:{label:`Explore reliability engineering`,href:`/system/archive/reliability-resource-guide`,description:`Continue into Fanout's reliability guide and connect end-to-end checks to failure domains, retries, idempotency, graceful degradation, observability, and recovery design.`},preview:{badge:`END TO END`,accent:`var(--ga-cat-blue)`,background:`color-mix(in srgb, var(--ga-cat-blue) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-20-toolformer`,date:`2026-08-20`,url:`https://proceedings.neurips.cc/paper_files/paper/2023/hash/d842425e4bf79ba039352da0f658a906-Abstract-Conference.html`,title:`Toolformer: Language Models Can Teach Themselves to Use Tools`,authors:`Schick et al.`,venue:`NeurIPS 2023`,lane:`AI Research`,difficulty:`Easy`,readTime:`40 min`,description:`Toolformer asks how a language model can learn when and how to call external tools without a large hand-labeled tool-use dataset. Read it to see how the model proposes calls inside ordinary text, executes them, and keeps only those whose returned result lowers continuation loss enough to become a training example.`,learns:[`How a few demonstrations turn the base language model into a permissive annotator that proposes API-call positions and arguments.`,`Why Toolformer compares future-token loss with and without each executed result, and what that threshold does not certify.`,`How retained calls become fine-tuning data, why sufficiently capable base models benefit most, and where single-call learning stops short of a complete agent.`],explore:{label:`Explore tool use and function calling`,href:`/ai/glossary#tool-use-function-calling`,description:`Continue into Fanout's tool-use glossary and connect model-generated calls to external executors, structured arguments, permissions, validation, latency, and modern agent harnesses.`},preview:{badge:`TOOLS`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-19-shazam-audio-search`,date:`2026-08-19`,url:`https://www.ee.columbia.edu/~dpwe/papers/Wang03-shazam.pdf`,title:`An Industrial-Strength Audio Search Algorithm`,authors:`Avery Li-Chun Wang`,venue:`ISMIR 2003`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`This is the paper behind Shazam: how a phone can name a song from ten noisy seconds in a pub. Read it to see how a track is reduced to a constellation of spectrogram peaks, how pairing peaks into 32-bit hashes makes lookup about ten thousand times faster, and why a match is declared only when the surviving hashes agree on one time offset.`,learns:[`Why spectrogram peaks survive shouting, traffic, and phone-codec compression when almost every other audio feature is destroyed.`,`How pairing an anchor peak with nearby peaks turns 10-bit features into 30-bit hashes, trading about 10 times the storage for about 10,000 times the search speed.`,`Why a histogram of sample-to-track time offsets can confirm a match with only about 1-2% of the fingerprint tokens surviving the noise.`],explore:{label:`Explore inverted indexes`,href:`/system/archive/inverted-index-and-posting-lists`,description:`Continue into Fanout's inverted-index guide and connect Shazam's sorted hash-token index to posting lists, exact-match lookup, and the read paths of text search engines.`},preview:{badge:`SHAZAM`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`network`}},{id:`2026-08-18-chain-of-thought`,date:`2026-08-18`,url:`https://arxiv.org/abs/2201.11903`,title:`Chain-of-Thought Prompting Elicits Reasoning in Large Language Models`,authors:`Wei, Wang, Schuurmans, Bosma, Ichter, Xia, Chi, Le, and Zhou`,venue:`NeurIPS 2022`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`This paper asks why showing a language model a few worked examples of step-by-step reasoning unlocks problems that direct prompting cannot touch. Read it to see how eight hand-written exemplars lifted PaLM 540B from 17.9% to 56.9% on grade-school math, why meaningless filler tokens explain none of the gain, and why the same prompt actively hurts smaller models.`,learns:[`How a few worked examples make a large model write its own intermediate steps before committing to an answer.`,`Why the ablations show the gain comes from natural-language steps before the answer, not extra tokens or activated knowledge.`,`Why the ability emerges only near hundred-billion-parameter scale, and what fluent but illogical chains do to smaller models.`],explore:{label:`Explore chain-of-thought`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Achain-of-thought-cot`,description:`Open Fanout's chain-of-thought concept in the knowledge graph and continue into in-context learning, emergent abilities, and the agent patterns that build on step-by-step reasoning.`},preview:{badge:`COT`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`curve`}},{id:`2026-08-17-bloom-filter`,date:`2026-08-17`,url:`https://dl.acm.org/doi/10.1145/362686.362692`,title:`Space/Time Trade-offs in Hash Coding with Allowable Errors`,authors:`Burton H. Bloom`,venue:`Communications of the ACM, 1970`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`Bloom's paper asks how a compact in-memory screen can reject missing keys before an expensive exact lookup. Read it to see why one zero bit proves absence, why all-one evidence means only possibly present, and how shared hash positions trade memory for a controlled false-positive path.`,learns:[`How each inserted key sets several shared bit positions and a query replays the same address rule.`,`Why any zero proves a key absent while collisions can make a never-inserted key appear possibly present.`,`How bit occupancy, hash count, exact confirmation, and the cost of false positives determine whether the filter helps.`],explore:{label:`Explore Bloom filters`,href:`/system/archive/bloom-filters`,description:`Continue into Fanout's Bloom Filters guide and connect the original one-sided membership test to database read paths, filter sizing, false-positive budgets, and exact fallbacks.`},preview:{badge:`BLOOM`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`matrix`}},{id:`2026-08-16-tor-onion-router`,date:`2026-08-16`,url:`https://www.usenix.org/conference/13th-usenix-security-symposium/tor-second-generation-onion-router`,title:`Tor: The Second-Generation Onion Router`,authors:`Dingledine, Mathewson, and Syverson`,venue:`USENIX Security 2004`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`This paper asks how a browser can cross several volunteer relays without handing any one relay the complete route. Read it to see how the client extends a circuit one hop at a time, wraps each fixed-size cell in a different session key for every relay, and why those layers still cannot defeat an observer who can correlate traffic at both ends.`,learns:[`Why a relay can forward a connection while knowing only its predecessor and successor rather than both the client and destination.`,`How telescoping circuit construction negotiates a fresh key with each relay and how layered cells expose one local step at a time.`,`Where Tor's 2004 threat model stops: traffic timing, hostile exits, application leaks, directory trust, and early-deployment scale remain real boundaries.`],explore:{label:`Explore the software papers map`,href:`/blog/100-papers-to-understand-software-and-computing`,description:`Place Tor beside foundational papers on protocols, distributed trust, cryptography, naming, peer-to-peer systems, transport, and the tradeoffs that make real infrastructure deployable.`},preview:{badge:`TOR`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-15-alphago-neural-tree-search`,date:`2026-08-15`,url:`https://deepmind-media.storage.googleapis.com/alphago/AlphaGoNaturePaper.pdf`,title:`Mastering the game of Go with deep neural networks and tree search`,authors:`Silver et al.`,venue:`Nature 2016`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`This paper asks how a computer can choose a strong Go move when the game tree is far too large to enumerate. Read it to see how a learned policy concentrates search on promising moves, how a value network estimates who is ahead before a game ends, and how Monte Carlo tree search turns those estimates into professional-level play under a large compute budget.`,learns:[`How a policy network reduces the effective breadth of search while a value network reduces the effective depth.`,`Why expert imitation, self-play reinforcement learning, and independent value-training positions solve different parts of the problem.`,`How policy priors, visit counts, value estimates, and rollouts combine inside Monte Carlo tree search, and which compute and evaluation limits qualify the result.`],explore:{label:`Explore reinforcement learning`,href:`/knowledge-graph?node=ai-research%3Amodule%3Areinforcement-learning`,description:`Connect AlphaGo's self-play, policy, and value functions to Fanout's reinforcement-learning path, then continue into agents, environments, rewards, policy gradients, and modern reasoning systems.`},preview:{badge:`GO`,accent:`var(--ga-cat-purple)`,background:`color-mix(in srgb, var(--ga-cat-purple) 7%, var(--ga-bg))`,figure:`network`}},{id:`2026-08-14-bitcoin-proof-of-work`,date:`2026-08-14`,url:`https://bitcoin.org/bitcoin.pdf`,title:`Bitcoin: A Peer-to-Peer Electronic Cash System`,authors:`Satoshi Nakamoto`,venue:`Bitcoin white paper, 2008`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`This paper asks how two people can agree that a digital payment happened first without asking a central mint to keep the ledger. Read it to see why signatures prove ownership but not uniqueness, how hash-linked proof of work makes one public history costly to rewrite, and why every confirmation still depends on an honest-compute majority assumption.`,learns:[`Why a valid digital signature can authorize two conflicting transfers, leaving double-spending as an ordering problem rather than a signature problem.`,`How nodes validate transactions, compete to extend hash-linked blocks, and converge on the valid branch with the most accumulated proof of work.`,`Why later blocks raise the cost of rewriting a payment, how the paper models attacker catch-up probability, and where honest-majority, privacy, and light-client limits remain.`],explore:{label:`Explore the software papers map`,href:`/blog/100-papers-to-understand-software-and-computing`,description:`Place Bitcoin beside timestamping, distributed agreement, peer-to-peer systems, CRDTs, incentives, and other papers that explain how software coordinates without one owner.`},preview:{badge:`BTC`,accent:`#E8822A`,background:`#FFF8ED`,figure:`network`}},{id:`2026-08-13-congestion-avoidance-control`,date:`2026-08-13`,url:`https://doi.org/10.1145/52324.52356`,title:`Congestion Avoidance and Control`,authors:`Van Jacobson`,venue:`SIGCOMM 1988`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`This paper asks how TCP can keep a busy network useful when delay, packet loss, and retransmission tempt every sender to add even more traffic. Read it to see how acknowledgements become a clock, how slow start fills an empty path without a full-window burst, and why a congestion signal should make the sender retreat quickly before probing capacity again.`,learns:[`How ACK spacing carries the bottleneck's packet rhythm back to the sender, so one departing packet can clock one replacement into the network.`,`Why slow start begins with one packet and grows from returned evidence instead of dumping a complete receiver window into an empty path.`,`How additive increase, multiplicative decrease, RTT-variation estimation, and exponential timeout backoff interrupt the positive feedback behind congestion collapse.`],explore:{label:`Explore TCP and UDP`,href:`/system/archive/tcp-vs-udp`,description:`Continue into Fanout's transport guide and connect congestion control to reliable byte streams, retransmission, flow control, head-of-line blocking, UDP, and QUIC.`},preview:{badge:`TCP`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`curve`}},{id:`2026-08-12-stolen-reasoning-traces`,date:`2026-08-12`,url:`https://arxiv.org/abs/2608.09867`,title:`Stealing Reasoning Traces from Proprietary LLM APIs`,authors:`Panfilov, Schmotz, Shumailov, Beurer-Kellner, Schaeffer, Prabhu, Geiping, and Andriushchenko`,venue:`arXiv, 2026`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`This paper asks what happens when an API gives encrypted reasoning state to the client and later accepts that opaque state again. Read it to see why confidentiality and integrity do not automatically bind a reasoning block to one user, session, or model, how the authors tested compatible weaker decoders, and what the resulting privacy evidence means after responsible disclosure.`,learns:[`Why a client-held encrypted reasoning block can behave like a portable capability when its authorization context is not bound tightly enough.`,`How the study separates cross-session, cross-user, and cross-model compatibility from the weaker question of byte-exact trace recovery.`,`What the public-trajectory scan found, why block-level and session-level rates have different denominators, and which server-side and export-time defenses follow.`],explore:{label:`Explore knowledge distillation`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aknowledge-distillation`,description:`Connect the paper's weaker-decoder result to teacher-student transfer, model compression, and the broader question of what capabilities survive across model boundaries.`},preview:{badge:`TRACE`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`network`}},{id:`2026-08-11-pagerank`,date:`2026-08-11`,url:`https://ilpubs.stanford.edu/422/`,title:`The PageRank Citation Ranking: Bringing Order to the Web`,authors:`Page, Brin, Motwani, and Winograd`,venue:`Stanford InfoLab, 1999`,lane:`Systems`,difficulty:`Easy`,readTime:`35 min`,description:`PageRank asks how a search engine can estimate which web pages matter before it even sees a query. Read it to see how every page divides its authority among outgoing links, how repeated link-weight transfer settles into a global ranking, and why teleportation, incomplete crawls, and manipulation keep that score from being a synonym for truth.`,learns:[`Why a backlink from an important page contributes more than an ordinary backlink, while a source with many outgoing links gives each destination a smaller share.`,`How repeated rank redistribution becomes the stationary distribution of an idealized random surfer that sometimes jumps to another page.`,`Why PageRank complements text relevance rather than replacing it, and how rank sinks, dangling pages, crawl gaps, and adversarial links bound the result.`],explore:{label:`Explore search ranking`,href:`/system/archive/bm25-production-ranking`,description:`Continue into Fanout's production-ranking guide and connect PageRank's query-independent authority signal to inverted indexes, lexical relevance, field weighting, and modern ranking stages.`},preview:{badge:`PAGE`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`network`}},{id:`2026-08-10-react-reasoning-acting`,date:`2026-08-10`,url:`https://arxiv.org/abs/2210.03629v3`,title:`ReAct: Synergizing Reasoning and Acting in Language Models`,authors:`Yao, Zhao, Yu, Du, Shafran, Narasimhan, and Cao`,venue:`ICLR 2023`,lane:`AI Research`,difficulty:`Easy`,readTime:`35 min`,description:`ReAct gives language-model agents a simple working rhythm: reason about the current situation, take a bounded action, observe what the environment returns, and revise the next move. Read it for the durable idea behind many tool-using agent harnesses and for an honest look at why better grounding can still fail when tools return weak evidence or the agent gets stuck in a loop.`,learns:[`How ReAct interleaves language thoughts, task-specific actions, and returned observations in one inspectable trajectory.`,`Why thoughts can decompose goals and recover from surprises while actions ground later reasoning in new external evidence.`,`Why tool quality, prompt choice, step limits, repetition detection, and narrow permissions remain part of a reliable agent harness.`],explore:{label:`Explore AI agents`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aagent-agentic-ai`,description:`Open Fanout's agent concept node and connect ReAct to planning, tool use, environment observations, memory, permissions, and multi-step task execution.`},preview:{badge:`ReAct`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`network`}},{id:`2026-08-09-ring-attention`,date:`2026-08-09`,url:`https://arxiv.org/abs/2310.01889v4`,title:`Ring Attention with Blockwise Transformers for Near-Infinite Context`,authors:`Liu, Zaharia, and Abbeel`,venue:`ICLR 2024`,lane:`Systems`,difficulty:`Hard`,readTime:`50 min`,description:`Ring Attention asks how exact Transformer context can grow across devices without gathering the whole sequence on each one. Read it to see how stationary query blocks, circulating key-value blocks, and compute-transfer overlap turn a device ring into aggregate context capacity while keeping per-host activation memory independent of total sequence length.`,learns:[`Why blockwise attention removes the full score matrix but leaves a sequence-length cost in each layer's output activations.`,`How each host keeps one query block while key-value blocks rotate through neighboring hosts and exact softmax statistics accumulate in any block order.`,`Why the no-added-overhead claim requires c ≥ F/B, and why the paper's 6bch local-memory bound does not contain total sequence length s.`],explore:{label:`Explore distributed attention`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aflash-attention`,description:`Open Fanout's FlashAttention node and connect exact blockwise attention to sequence partitioning, interconnect bandwidth, memory hierarchy, and long-context Transformer systems.`},preview:{badge:`RING`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`network`}},{id:`2026-08-08-flashattention-2`,date:`2026-08-08`,url:`https://arxiv.org/abs/2307.08691v1`,title:`FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning`,authors:`Tri Dao`,venue:`ICLR 2024`,lane:`Inference`,difficulty:`Hard`,readTime:`50 min`,description:`FlashAttention-2 asks why an exact, I/O-aware attention kernel can still leave much of an A100 idle. Read it to see how reducing non-matmul work, parallelizing along sequence tiles, and giving each warp disjoint query and output rows improves GPU utilization without changing the attention result.`,learns:[`Why scalar softmax bookkeeping and synchronization are expensive relative to tensor-core matrix multiplication on the paper's A100 setup.`,`How sequence-level thread-block parallelism supplies more independent work when batch size and head count are too small to occupy the GPU.`,`Why splitting query rows across warps while sharing key and value tiles removes the cross-warp reduction of partial output rows.`],explore:{label:`Explore FlashAttention`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aflash-attention`,description:`Open Fanout's FlashAttention node and connect exact attention tiling to GPU memory hierarchy, fused kernels, sequence length, and modern inference systems.`},preview:{badge:`FA2`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`matrix`}},{id:`2026-08-07-mamba-selective-state-spaces`,date:`2026-08-07`,url:`https://arxiv.org/abs/2312.00752v2`,title:`Mamba: Linear-Time Sequence Modeling with Selective State Spaces`,authors:`Gu and Dao`,venue:`COLM 2024`,lane:`AI Research`,difficulty:`Medium`,readTime:`55 min`,description:`Mamba asks how a recurrent model with a fixed-size state can decide what information deserves to survive. Read it to see how input-dependent state-space parameters create content-aware persistence and reset, and how a fused parallel scan makes the resulting time-varying recurrence practical on GPUs.`,learns:[`Why fixed linear state-space dynamics can be trained as a convolution but cannot change their update rule according to token content.`,`How input-dependent Δ, B, and C let a bounded recurrent state persist useful history, admit selected inputs, and reset at boundaries.`,`Why Mamba needs kernel fusion, parallel scan, SRAM-local state expansion, and recomputation after giving up the global-convolution shortcut.`],explore:{label:`Explore recurrent state`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Arnn`,description:`Open Fanout's RNN node and connect Mamba's selective state to hidden-state recurrence, LSTM-style gates, sequence compression, and long-context modeling.`},preview:{badge:`S6`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`network`}},{id:`2026-08-06-rmsnorm`,date:`2026-08-06`,url:`https://papers.nips.cc/paper_files/paper/2019/hash/1e8a19426224ca89e83cef47f1e7f53b-Abstract.html`,title:`Root Mean Square Layer Normalization`,authors:`Zhang and Sennrich`,venue:`NeurIPS 2019`,lane:`AI Research`,difficulty:`Medium`,readTime:`35 min`,description:`RMSNorm asks whether LayerNorm needs to subtract the mean as well as control activation scale. Read it to see how dividing by a vector's root mean square preserves global rescaling invariance with less normalization work, while deliberately giving up re-centering invariance.`,learns:[`How LayerNorm's centering and scaling operations can be separated into distinct invariance properties.`,`Why dividing an activation vector by its RMS makes positive global rescaling cancel while leaving additive shifts visible.`,`Why the paper's quality and runtime results support a useful simplification without proving that mean-centering is universally dispensable.`],explore:{label:`Explore RMSNorm`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Armsnorm`,description:`Open Fanout's RMSNorm node and connect the paper to LayerNorm, activation scale, transformer blocks, and the neural-network-from-scratch course.`},preview:{badge:`RMS`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`curve`}},{id:`2026-08-05-zero-memory-optimization`,date:`2026-08-05`,url:`https://arxiv.org/abs/1910.02054v3`,title:`ZeRO: Memory Optimizations Toward Training Trillion Parameter Models`,authors:`Rajbhandari et al.`,venue:`SC 2020`,lane:`Systems`,difficulty:`Medium`,readTime:`50 min`,description:`ZeRO asks why adding data-parallel workers does not make a model easier to fit when every worker keeps the same training state. Read it to see how partitioning optimizer states, gradients, and parameters turns aggregate cluster memory into usable model capacity while preserving the data-parallel computation.`,learns:[`Why mixed-precision Adam needs 16 bytes of persistent model state per parameter on every conventional data-parallel worker.`,`How ZeRO's three cumulative stages shard optimizer states, gradients, and parameters across the data-parallel group.`,`Why Stages 1 and 2 keep the paper's baseline communication volume while full parameter partitioning raises it to 1.5 times baseline.`],explore:{label:`Explore Memory Optimization`,href:`/ai/hardware`,description:`Continue into Fanout's hardware guide for data parallelism, DeepSpeed ZeRO, mixed precision, interconnects, activation checkpointing, and GPU memory planning.`},preview:{badge:`ZeRO`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`matrix`}},{id:`2026-08-04-orca-continuous-batching`,date:`2026-08-04`,url:`https://www.usenix.org/conference/osdi22/presentation/yu`,title:`Orca: A Distributed Serving System for Transformer-Based Generative Models`,authors:`Yu et al.`,venue:`OSDI 2022`,lane:`Inference`,difficulty:`Easy`,readTime:`45 min`,description:`Orca moves LLM serving from fixed request batches to iteration-level scheduling. Read it to see how a scheduler can reconsider the active batch after every generated token, and how selective batching preserves efficient shared GPU work even when requests have different sequence lengths and lifetimes.`,learns:[`Why fixed request batches make short generations wait behind long ones and keep new arrivals outside the running work.`,`How iteration-level scheduling lets finished requests leave and waiting requests join between autoregressive model steps.`,`How selective batching flattens compatible non-attention operations while keeping Attention and KV-cache state separate for each request.`],explore:{label:`Explore Continuous Batching`,href:`/blog/continuous-batching-llm-inference`,description:`Continue into Fanout's continuous-batching guide for iteration boundaries, changing batch membership, token budgets, KV-cache pressure, and modern serving policy.`},preview:{badge:`ORCA`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`bars`}},{id:`2026-08-03-grouped-query-attention`,date:`2026-08-03`,url:`https://aclanthology.org/2023.emnlp-main.298/`,title:`GQA: Training Generalized Multi-Query Transformer Models from Multi-Head Checkpoints`,authors:`Ainslie et al.`,venue:`EMNLP 2023`,lane:`Inference`,difficulty:`Medium`,readTime:`35 min`,description:`Grouped-query attention finds a practical middle ground between multi-head attention's quality and multi-query attention's decoding speed. Read it to see how sharing key-value heads within groups shrinks the KV cache, and how an existing multi-head checkpoint can be converted with only a small amount of additional pretraining.`,learns:[`How grouping query heads lets each group share one key head and one value head, reducing KV-cache memory and bandwidth without collapsing to a single shared pair.`,`How mean-pooling the original key and value projection heads preserves more checkpoint information than selecting one head or initializing new heads randomly.`,`Why five percent additional pretraining produced GQA models with quality close to multi-head attention and inference speed close to multi-query attention.`],explore:{label:`Explore Grouped Query Attention`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Agrouped-query-attention-gqa`,description:`Open Fanout's GQA node and connect the paper to multi-head attention, multi-query attention, KV-cache memory, checkpoint conversion, and faster decoding.`},preview:{badge:`GQA`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`attention`}},{id:`2026-08-02-deepseekmath-grpo`,date:`2026-08-02`,url:`https://arxiv.org/abs/2402.03300`,title:`DeepSeekMath: Pushing the Limits of Mathematical Reasoning in Open Language Models`,authors:`Shao et al.`,venue:`arXiv 2024`,lane:`ML Math`,difficulty:`Hard`,readTime:`55 min`,description:`DeepSeekMath shows how targeted data and reinforcement learning can turn a compact open model into a strong mathematical reasoner. Read it for the data-selection pipeline behind its 120 billion math tokens and for GRPO, a PPO variant that removes the separate critic model by learning from relative rewards within groups of sampled answers.`,learns:[`How an iterative Common Crawl filtering pipeline expands a small high-quality math seed into a 120-billion-token training corpus.`,`How GRPO estimates each answer's advantage by comparing its reward with the other answers sampled for the same problem.`,`Why removing the learned critic reduces memory use while retaining PPO-style clipped policy updates for reinforcement learning.`],explore:{label:`Explore GRPO`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Agrpo`,description:`Open Fanout's GRPO node and connect the paper to PPO, group-relative advantages, critic-free reinforcement learning, and mathematical reasoning.`},preview:{badge:`GRPO`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`curve`}},{id:`2026-08-01-proximal-policy-optimization`,date:`2026-08-01`,url:`https://arxiv.org/abs/1707.06347`,title:`Proximal Policy Optimization Algorithms`,authors:`Schulman et al.`,venue:`arXiv 2017`,lane:`ML Math`,difficulty:`Hard`,readTime:`55 min`,description:`Proximal Policy Optimization shows how to reuse on-policy experience for several minibatch updates without letting the policy move too far in one step. Read it to understand the clipped surrogate objective behind a practical reinforcement-learning algorithm that later became central to RLHF pipelines.`,learns:[`How the probability ratio compares the new policy with the policy that collected each action.`,`Why clipping that ratio limits the incentive for destructively large policy updates while keeping the objective simple to optimize.`,`How multiple epochs of minibatch updates improve sample use, and why PPO balances empirical performance, implementation simplicity, and wall-clock cost.`],explore:{label:`Explore PPO`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Appo`,description:`Open Fanout's PPO node and connect the paper to policy gradients, importance ratios, clipped objectives, advantage estimates, and RLHF.`},preview:{badge:`PPO`,accent:`#E8822A`,background:`#FFF8ED`,figure:`curve`}},{id:`2026-07-31-instructgpt`,date:`2026-07-31`,url:`https://arxiv.org/abs/2203.02155`,title:`Training Language Models to Follow Instructions with Human Feedback`,authors:`Ouyang et al.`,venue:`NeurIPS 2022`,lane:`AI Research`,difficulty:`Easy`,readTime:`45 min`,description:`InstructGPT shows why a larger language model is not automatically better at following a user's intent. Read it to see how demonstrations, preference rankings, a learned reward model, and reinforcement learning turn human judgments into a practical post-training pipeline for more helpful instruction following.`,learns:[`How supervised fine-tuning on human-written demonstrations gives a pretrained model an initial instruction-following policy.`,`How rankings of model responses train a reward model that turns subjective human preferences into a reusable learning signal.`,`Why optimizing that reward with PPO can make a 1.3B-parameter model more preferred than a 175B GPT-3 model, while still leaving important alignment limitations.`],explore:{label:`Explore RLHF`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Arlhf`,description:`Open Fanout's RLHF node and connect the paper to supervised fine-tuning, preference data, reward modeling, PPO, and instruction-following alignment.`},preview:{badge:`RLHF`,accent:`#E8822A`,background:`#FFF8ED`,figure:`network`}},{id:`2026-07-30-switch-transformers`,date:`2026-07-30`,url:`https://www.jmlr.org/papers/v23/21-0998.html`,title:`Switch Transformers: Scaling to Trillion Parameter Models with Simple and Efficient Sparsity`,authors:`Fedus, Zoph, and Shazeer`,venue:`JMLR 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`50 min`,description:`Switch Transformers shows how to grow a model's capacity without activating every parameter for every token. Read it to see how top-1 expert routing, load balancing, and expert capacity turn mixture-of-experts into a simpler scaling recipe while keeping per-token computation roughly constant.`,learns:[`How a Switch layer routes each token to one expert feed-forward network instead of evaluating every expert.`,`Why an auxiliary load-balancing loss and a fixed expert capacity keep routing from overloading a small set of experts.`,`How sparse activation adds model capacity at roughly fixed computation per token, producing large pre-training speedups over dense T5 baselines.`],explore:{label:`Explore Mixture of Experts`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Amixture-of-experts-moe`,description:`Open Fanout's mixture-of-experts node and connect the paper to sparse activation, token routing, expert capacity, load balancing, and efficient model scaling.`},preview:{badge:`MoE`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`network`}},{id:`2026-07-29-knowledge-distillation`,date:`2026-07-29`,url:`https://arxiv.org/abs/1503.02531`,title:`Distilling the Knowledge in a Neural Network`,authors:`Hinton, Vinyals, and Dean`,venue:`NIPS 2014 Deep Learning Workshop`,lane:`AI Research`,difficulty:`Easy`,readTime:`30 min`,description:`Knowledge distillation turns an expensive ensemble or large teacher into a smaller, deployable student. Read it to see why the full pattern of class probabilities carries more useful structure than hard labels alone, and how temperature-scaled soft targets transfer that structure during training.`,learns:[`How a teacher's soft class probabilities reveal similarities between classes that one-hot labels discard.`,`Why raising the softmax temperature exposes more of that relative probability structure for the student to learn.`,`How combining soft teacher targets with the original hard labels produces a compact model that is easier to deploy.`],explore:{label:`Explore Knowledge Distillation`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aknowledge-distillation`,description:`Open Fanout's knowledge-distillation node and connect the paper to teacher-student training, soft targets, temperature scaling, and model compression.`},preview:{badge:`KD`,accent:`#0F9D58`,background:`#F3FBF6`,figure:`network`}},{id:`2026-07-28-tail-at-scale`,date:`2026-07-28`,url:`https://research.google/pubs/the-tail-at-scale/`,title:`The Tail at Scale`,authors:`Dean and Barroso`,venue:`Communications of the ACM 2013`,lane:`Systems`,difficulty:`Easy`,readTime:`30 min`,description:`The Tail at Scale explains why rare slowdowns become routine user-visible delays when one request fans out across many machines. Read it for a practical systems lesson: large services need techniques that tolerate latency variability, not only faster average components.`,learns:[`Why waiting on many parallel components makes the slowest response dominate end-to-end latency.`,`How hedged requests and backup work can cut tail latency without duplicating every request.`,`Why tail-tolerant systems combine deadlines, partial results, finer-grained work, and careful resource controls.`],explore:{label:`Explore Tail Latency`,href:`/system/archive/tail-latency`,description:`Continue into Fanout's tail-latency material for percentiles, fanout risk, hedged requests, deadlines, partial results, and load shedding.`},preview:{badge:`P99`,accent:`#E8822A`,background:`#FFF8ED`,figure:`bars`}},{id:`2026-07-27-speculative-decoding`,date:`2026-07-27`,url:`https://proceedings.mlr.press/v202/leviathan23a.html`,title:`Fast Inference from Transformers via Speculative Decoding`,authors:`Leviathan, Kalman, and Matias`,venue:`ICML 2023`,lane:`Inference`,difficulty:`Medium`,readTime:`40 min`,description:`Speculative decoding makes autoregressive generation faster without changing the target model's output distribution. Read it to see how a small draft model, parallel verification, and a corrected sampling rule turn extra compute into lower decoding latency without retraining the models.`,learns:[`How a smaller draft model proposes several likely tokens before the larger target model runs.`,`How the target model verifies a block of draft tokens in parallel instead of decoding every token serially.`,`Why the acceptance and correction rule preserves the target model's output distribution while enabling practical speedups.`],explore:{label:`Explore Speculative Decoding`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aspeculative-decoding`,description:`Open Fanout's speculative-decoding node and connect the paper to draft models, parallel verification, sampling, and low-latency LLM serving.`},preview:{badge:`SPEC`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`bars`}},{id:`2026-07-26-retrieval-augmented-generation`,date:`2026-07-26`,url:`https://arxiv.org/abs/2005.11401`,title:`Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks`,authors:`Lewis et al.`,venue:`NeurIPS 2020`,lane:`AI Research`,difficulty:`Easy`,readTime:`40 min`,description:`Retrieval-Augmented Generation gives a language model an explicit, updateable memory outside its parameters. Read it to see how a neural retriever and a sequence generator work together, and why grounding generation in retrieved evidence can improve factual, knowledge-intensive answers.`,learns:[`How RAG combines a dense Wikipedia retriever with a pretrained sequence-to-sequence generator.`,`Why parametric memory in model weights and non-parametric memory in a document index solve different parts of the task.`,`How RAG-Sequence and RAG-Token differ in whether retrieved passages stay fixed for a response or can change for each token.`],explore:{label:`Explore RAG`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Arag`,description:`Open Fanout's RAG concept node and connect the paper to retrieval, vector indexes, grounding, provenance, and knowledge-intensive generation.`},preview:{badge:`RAG`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`network`}},{id:`2026-07-24-auto-encoding-variational-bayes`,date:`2026-07-24`,url:`https://arxiv.org/abs/1312.6114`,title:`Auto-Encoding Variational Bayes`,authors:`Kingma and Welling`,venue:`ICLR 2014`,lane:`ML Math`,difficulty:`Hard`,readTime:`55 min`,description:`Auto-Encoding Variational Bayes makes latent-variable models trainable with ordinary backpropagation. Read it to see how the evidence lower bound, amortized inference, and the reparameterization trick turn an intractable posterior problem into a practical stochastic-optimization recipe.`,learns:[`How the evidence lower bound replaces an intractable log-likelihood with reconstruction and KL terms that can be optimized.`,`Why an encoder amortizes posterior inference by predicting a distribution over latent variables for each example.`,`How reparameterizing a sample as a deterministic transform of parameter-free noise lets gradients pass through stochastic latent variables.`],explore:{label:`Explore Variational Autoencoders`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Avariational-autoencoder-vae`,description:`Open Fanout's VAE concept node and connect the paper to latent-variable models, the ELBO, KL divergence, and generative modeling.`},preview:{badge:`VAE`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`network`}},{id:`2026-07-23-dropout`,date:`2026-07-23`,url:`https://jmlr.org/papers/v15/srivastava14a.html`,title:`Dropout: A Simple Way to Prevent Neural Networks from Overfitting`,authors:`Srivastava et al.`,venue:`JMLR 2014`,lane:`ML Math`,difficulty:`Very Easy`,readTime:`35 min`,description:`Dropout is a compact lesson in turning randomness into regularization. Read it to see how masking neurons during training discourages brittle co-adaptation and approximates an ensemble without paying the cost of running many networks at inference time.`,learns:[`How randomly masking units makes features useful across many different network configurations.`,`Why dropout can be understood as training an ensemble of thinned networks with shared weights.`,`How keep probability and test-time scaling connect stochastic training to deterministic inference.`],explore:{label:`Explore Dropout`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Adropout`,description:`Open Fanout's dropout concept node and connect the paper to regularization, overfitting, model averaging, and neural-network training.`},preview:{badge:`DROP`,accent:`#0F9D58`,background:`#F3FBF6`,figure:`network`}},{id:`2026-07-22-direct-preference-optimization`,date:`2026-07-22`,url:`https://arxiv.org/abs/2305.18290`,title:`Direct Preference Optimization: Your Language Model is Secretly a Reward Model`,authors:`Rafailov et al.`,venue:`NeurIPS 2023`,lane:`AI Research`,difficulty:`Easy`,readTime:`40 min`,description:`DPO turns language-model alignment from a multi-stage reinforcement-learning pipeline into a direct preference-learning objective. Read it to see how one mathematical reparameterization can remove the separate reward model and make preference tuning much simpler to train.`,learns:[`Why standard RLHF separates preference modeling from policy optimization.`,`How DPO expresses the implicit reward through the language model and a reference policy.`,`Why a classification-style loss can make preference tuning simpler and more stable than PPO-based RLHF.`],explore:{label:`Explore DPO`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Adpo`,description:`Open Fanout's DPO concept node and connect the paper to preference data, reward models, RLHF, and post-training alignment.`},preview:{badge:`DPO`,accent:`#B0174F`,background:`#FFF1F6`,figure:`curve`}},{id:`2026-07-21-pagedattention`,date:`2026-07-21`,url:`https://arxiv.org/abs/2309.06180v1`,title:`Efficient Memory Management for Large Language Model Serving with PagedAttention`,authors:`Woosuk Kwon et al.`,venue:`SOSP 2023`,lane:`Inference`,difficulty:`Hard`,readTime:`16 min`,description:`An LLM server can run out of room for requests while most of its KV cache memory holds nothing. Follow the three kinds of reservation waste, the block table that places 16-token blocks anywhere on the GPU, copy-on-write sharing, and the batch-size evidence behind vLLM's 2 to 4 times throughput.`,learns:[`Why contiguous worst-case reservation left only 20.4 to 38.2 percent of KV cache memory holding tokens in the paper's baselines.`,`How a per-request block table, on-demand blocks, and reference-counted copy-on-write bound waste to the last block and share prompts across samples.`,`Why a 20 to 26 percent slower attention kernel still serves 2 to 4 times more requests, and where the reimplemented baselines limit the claim.`],explore:{label:`Read the Orca Daily`,href:`/daily/2026-08-04-orca-continuous-batching`,description:`Iteration-level scheduling decides which requests run each step; PagedAttention decides how much memory each one may waste while it runs.`},preview:{badge:`SOSP`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`matrix`}},{id:`2026-07-20-kv-cache-management-survey`,date:`2026-07-20`,url:`https://arxiv.org/abs/2607.02574`,title:`From Tensor Buffer to Distributed Memory Hierarchy`,authors:`Li, Wang, and Chen`,venue:`arXiv 2026`,lane:`Inference`,difficulty:`Medium`,readTime:`50 min`,description:`This survey treats the KV cache as a distributed memory-management problem, not just a temporary tensor. It is a useful July 20 pick for understanding why LLM serving depends on locality, lifetime, ownership, substrate, and the tradeoffs behind paged, shared, disaggregated, and tiered cache designs.`,learns:[`Why the KV cache becomes a first-order serving object as context and concurrency grow.`,`How locality, lifetime, ownership, and substrate separate different KV-cache architectures.`,`Which measurements are still missing when teams evaluate LLM serving systems.`],explore:{label:`Explore KV Cache`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Akv-cache`,description:`Open Fanout's KV-cache concept node and connect the survey to attention, batching, PagedAttention, prefix caching, and inference serving.`},preview:{badge:`KV`,accent:`#B0174F`,background:`#FFF1F6`,figure:`matrix`}},{id:`2026-07-19-attention-is-all-you-need`,date:`2026-07-19`,url:`https://arxiv.org/abs/1706.03762`,title:`Attention Is All You Need`,authors:`Vaswani et al.`,venue:`NeurIPS 2017`,lane:`AI Research`,difficulty:`Medium`,readTime:`45 min`,description:`The Transformer paper replaced recurrence with attention and made sequence modeling easier to parallelize. Read it for the architectural move that turned token-to-token routing into the core primitive behind modern language models.`,learns:[`Why self-attention gives every token a learned view of the full context.`,`How multi-head attention, residual paths, and position encodings fit together.`,`What changed operationally when training became more parallel.`],explore:{label:`Explore Attention`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aattention`,description:`Open the Fanout concept map around attention, self-attention, Transformers, and related model architecture topics.`},preview:{badge:`NIPS`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`attention`}},{id:`2026-07-18-flashattention`,date:`2026-07-18`,url:`https://arxiv.org/abs/2205.14135`,title:`FlashAttention`,authors:`Dao et al.`,venue:`NeurIPS 2022`,lane:`Inference`,difficulty:`Hard`,readTime:`55 min`,description:`FlashAttention keeps exact attention but changes the memory traffic pattern. It is a clean example of why practical model speed often comes from respecting hardware limits rather than changing the math.`,learns:[`Why attention can be IO-bound even when the formula looks simple.`,`How tiling and recomputation reduce high-bandwidth memory reads and writes.`,`Why kernel-level details matter for serving long-context models.`],explore:{label:`Explore Flash Attention`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aflash-attention`,description:`Jump into Fanout's efficient-attention topic and continue toward KV cache, batching, and inference performance.`},preview:{badge:`IO`,accent:`#E4402C`,background:`#FFF6F3`,figure:`matrix`}},{id:`2026-07-17-scaling-laws`,date:`2026-07-17`,url:`https://arxiv.org/abs/2001.08361`,title:`Scaling Laws for Neural Language Models`,authors:`Kaplan et al.`,venue:`arXiv 2020`,lane:`ML Math`,difficulty:`Medium`,readTime:`50 min`,description:`The scaling-laws paper turns model size, data, and compute into a quantitative tradeoff. It is useful when you want to reason about progress curves instead of treating bigger training runs as folklore.`,learns:[`How loss trends with parameter count, dataset size, and compute budget.`,`Why log-log plots are the natural language of empirical scaling.`,`Where simple laws help and where newer regimes can break them.`],explore:{label:`Explore Scaling Laws`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Ascaling-laws`,description:`Open Fanout's scaling-laws node and connect the paper to model size, data budget, and LLM training decisions.`},preview:{badge:`LOG`,accent:`#0F9D58`,background:`#F3FBF6`,figure:`curve`}},{id:`2026-07-16-chinchilla`,date:`2026-07-16`,url:`https://arxiv.org/abs/2203.15556`,title:`Training Compute-Optimal Large Language Models`,authors:`Hoffmann et al.`,venue:`arXiv 2022`,lane:`AI Research`,difficulty:`Medium`,readTime:`45 min`,description:`Chinchilla is the scaling paper that made data budget feel as important as parameter count. It is a good daily pick for learning why a smaller model trained on more tokens can beat a larger undertrained one.`,learns:[`Why compute-optimal training balances model size and token count.`,`How scaling laws become practical training-budget decisions.`,`Why undertrained large models can waste compute despite looking impressive.`],explore:{label:`Explore LLM Training`,href:`/knowledge-graph?node=ai-research%3Amodule%3Allm-from-scratch`,description:`Use Fanout's LLM path to connect compute-optimal training with language-model architecture and training practice.`},preview:{badge:`TOK`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`curve`}},{id:`2026-07-15-dynamo`,date:`2026-07-15`,url:`https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf`,title:`Dynamo: Amazon's Highly Available Key-value Store`,authors:`DeCandia et al.`,venue:`SOSP 2007`,lane:`Systems`,difficulty:`Hard`,readTime:`60 min`,description:`Dynamo is the classic availability-first storage paper. It is worth reading for how partitioning, quorums, hinted handoff, vector clocks, and application-level conflict resolution combine into a product-shaped system.`,learns:[`How consistent hashing and sloppy quorums support availability targets.`,`Why conflict handling can become an application contract.`,`How production constraints shape data-store architecture.`],explore:{label:`Explore Dynamo on Fanout`,href:`/system/archive/source-amazon-dynamo-paper`,description:`Read Fanout's source summary for Dynamo and connect it to consistency, replication, partitioning, and conflict repair.`},preview:{badge:`SOSP`,accent:`#E8822A`,background:`#FFF8ED`,figure:`network`}},{id:`2026-07-14-mapreduce`,date:`2026-07-14`,url:`https://research.google/pubs/mapreduce-simplified-data-processing-on-large-clusters/`,title:`MapReduce`,authors:`Dean and Ghemawat`,venue:`OSDI 2004`,lane:`Systems`,difficulty:`Easy`,readTime:`40 min`,description:`MapReduce shows how a constrained programming model can hide distribution, retries, shuffling, and locality. Read it for the system-design lesson that an API can be an operational strategy.`,learns:[`How map, shuffle, and reduce decompose large batch jobs.`,`Why deterministic tasks make retries and straggler handling simpler.`,`How data locality and scheduling become part of the abstraction.`],explore:{label:`Explore Batch Workflows`,href:`/system/archive/dag-workflow-orchestration`,description:`Continue into Fanout's workflow orchestration material for batch pipelines, task graphs, retries, and scheduled work.`},preview:{badge:`OSDI`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`bars`}},{id:`2026-07-13-raft`,date:`2026-07-13`,url:`https://raft.github.io/raft.pdf`,title:`In Search of an Understandable Consensus Algorithm`,authors:`Ongaro and Ousterhout`,venue:`USENIX ATC 2014`,lane:`Systems`,difficulty:`Easy`,readTime:`45 min`,description:`Raft is the consensus paper to read before discussing leader election, replicated logs, or metadata coordination. It is intentionally structured for understandability, which makes it a strong beginner systems paper.`,learns:[`How leader election, log replication, and safety split the consensus problem.`,`Why a replicated log is the contract many coordination systems expose.`,`Where stale leaders and membership changes create production risk.`],explore:{label:`Explore Raft on Fanout`,href:`/system/archive/source-raft-paper`,description:`Read Fanout's Raft source summary and continue into consensus, leader election, and replicated logs.`},preview:{badge:`RAFT`,accent:`#2FA3D6`,background:`#F1FAFD`,figure:`network`}},{id:`2026-07-12-lora`,date:`2026-07-12`,url:`https://arxiv.org/abs/2106.09685`,title:`LoRA: Low-Rank Adaptation of Large Language Models`,authors:`Hu et al.`,venue:`ICLR 2022`,lane:`Inference`,difficulty:`Easy`,readTime:`35 min`,description:`LoRA is the cleanest first paper for understanding efficient model adaptation. It turns fine-tuning into small low-rank update matrices, which connects directly to Fanout's model training and serving material.`,learns:[`Why freezing the base model can still allow useful task adaptation.`,`How a low-rank update changes parameter count and storage cost.`,`Why adapter serving becomes a systems problem after training works.`],explore:{label:`Explore LoRA`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Alora`,description:`Open the Fanout LoRA node and connect low-rank adaptation to fine-tuning, QLoRA, PEFT, and adapter serving.`},preview:{badge:`LoRA`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`matrix`}},{id:`2026-07-11-bert`,date:`2026-07-11`,url:`https://arxiv.org/abs/1810.04805`,title:`BERT: Pre-training of Deep Bidirectional Transformers`,authors:`Devlin et al.`,venue:`NAACL 2019`,lane:`AI Research`,difficulty:`Medium`,readTime:`45 min`,description:`BERT is the pretrain-then-fine-tune paper that made bidirectional Transformer encoders the default for many language understanding tasks. It is useful for separating encoder intuition from decoder-only LLM intuition.`,learns:[`How masked language modeling differs from left-to-right prediction.`,`Why pretraining creates reusable representations for downstream tasks.`,`Where encoder-only Transformers still matter in practical NLP systems.`],explore:{label:`Explore BERT`,href:`/knowledge-graph?node=ai-research%3Acategory%3Aglossary-architecture&detail=ai-research%3Aconcept%3Abert`,description:`Open BERT inside Fanout's architecture glossary and connect it to encoders, Transformers, and pretraining.`},preview:{badge:`NLP`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`attention`}},{id:`2026-07-10-batch-normalization`,date:`2026-07-10`,url:`https://arxiv.org/abs/1502.03167`,title:`Batch Normalization`,authors:`Ioffe and Szegedy`,venue:`ICML 2015`,lane:`ML Math`,difficulty:`Medium`,readTime:`35 min`,description:`BatchNorm is a compact paper for learning how activation statistics, optimization stability, and architecture design interact. It is a good bridge between practical deep learning and the math of normalization.`,learns:[`Why unstable activation distributions can make optimization harder.`,`How learned scale and shift keep normalization from removing capacity.`,`Why training-time statistics and inference-time statistics differ.`],explore:{label:`Explore Batch Normalization`,href:`/knowledge-graph?node=ai-research%3Acategory%3Aglossary-architecture&detail=ai-research%3Aconcept%3Abatch-normalization`,description:`Open Batch Normalization in Fanout's architecture glossary and connect it to training stability and normalization layers.`},preview:{badge:`BN`,accent:`#0F9D58`,background:`#F3FBF6`,figure:`bars`}},{id:`2026-07-09-resnet`,date:`2026-07-09`,url:`https://arxiv.org/abs/1512.03385`,title:`Deep Residual Learning for Image Recognition`,authors:`He et al.`,venue:`CVPR 2016`,lane:`AI Research`,difficulty:`Very Easy`,readTime:`35 min`,description:`ResNet is the skip-connection paper that makes depth trainable in practice. It is beginner-friendly because the core idea is simple: learn a residual change instead of relearning the whole representation.`,learns:[`Why very deep networks can degrade even before overfitting is the issue.`,`How identity shortcuts improve gradient flow and optimization.`,`Why residual thinking reappears in modern Transformer blocks.`],explore:{label:`Explore CNN Architectures`,href:`/knowledge-graph?node=ai-research%3Acategory%3Aglossary-architecture&detail=ai-research%3Aconcept%3Acnn`,description:`Use Fanout's architecture glossary to connect ResNet to CNNs, residual blocks, and deeper model design.`},preview:{badge:`CVPR`,accent:`#E4402C`,background:`#FFF6F3`,figure:`network`}},{id:`2026-07-08-word2vec`,date:`2026-07-08`,url:`https://arxiv.org/abs/1301.3781`,title:`Efficient Estimation of Word Representations in Vector Space`,authors:`Mikolov et al.`,venue:`ICLR Workshop 2013`,lane:`AI Research`,difficulty:`Very Easy`,readTime:`30 min`,description:`The Word2Vec paper is still one of the best first reads for representation learning. It shows how simple prediction tasks can turn words into vectors with useful geometric structure.`,learns:[`Why embeddings can encode similarity through learned context prediction.`,`How CBOW and skip-gram frame word learning as efficient objectives.`,`Why representation quality can matter more than model complexity.`],explore:{label:`Explore Embeddings`,href:`/knowledge-graph?node=ai-research%3Aconcept%3Aembedding`,description:`Open Fanout's embedding topic and connect Word2Vec to representation learning, token vectors, and retrieval.`},preview:{badge:`VEC`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`matrix`}},{id:`2026-07-07-sequence-to-sequence`,date:`2026-07-07`,url:`https://arxiv.org/abs/1409.3215`,title:`Sequence to Sequence Learning with Neural Networks`,authors:`Sutskever et al.`,venue:`NeurIPS 2014`,lane:`AI Research`,difficulty:`Very Easy`,readTime:`35 min`,description:`Seq2Seq is the clean predecessor to attention and Transformers. It is a good beginner paper because the encoder-decoder contract is easy to visualize and still appears in translation, summarization, and agents.`,learns:[`How one network encodes an input sequence and another decodes an output.`,`Why fixed-size sequence representations created pressure for attention.`,`How teacher forcing and beam search fit early neural translation.`],explore:{label:`Explore Sequence Models`,href:`/knowledge-graph?node=ai-research%3Acategory%3Aglossary-architecture&detail=ai-research%3Aconcept%3Arnn`,description:`Open Fanout's sequence-modeling vocabulary and bridge RNNs, encoders, decoders, and later attention models.`},preview:{badge:`S2S`,accent:`#2FA3D6`,background:`#F1FAFD`,figure:`attention`}},{id:`2026-07-06-adam`,date:`2026-07-06`,url:`https://arxiv.org/abs/1412.6980`,title:`Adam: A Method for Stochastic Optimization`,authors:`Kingma and Ba`,venue:`ICLR 2015`,lane:`ML Math`,difficulty:`Very Easy`,readTime:`30 min`,description:`Adam is the optimizer paper learners meet constantly in code before they understand it. The first pass is approachable: it combines momentum-like gradient averages with squared-gradient adaptation.`,learns:[`How first and second moment estimates change parameter updates.`,`Why bias correction matters early in training.`,`What tradeoffs make Adam convenient but not automatically best.`],explore:{label:`Explore Adam Optimizer`,href:`/knowledge-graph?node=ai-research%3Amodule%3Aneural-network-from-scratch&detail=ai-research%3Aconcept%3Aadam-optimizer`,description:`Continue into Fanout's optimizer material around Adam, gradients, learning rates, and practical training loops.`},preview:{badge:`OPT`,accent:`#0F9D58`,background:`#F3FBF6`,figure:`curve`}},{id:`2026-07-05-dremel`,date:`2026-07-05`,url:`https://research.google/pubs/dremel-interactive-analysis-of-web-scale-datasets/`,title:`Dremel: Interactive Analysis of Web-Scale Datasets`,authors:`Melnik et al.`,venue:`VLDB 2010`,lane:`Systems`,difficulty:`Medium`,readTime:`45 min`,description:`Dremel is a strong systems pick for understanding columnar analytics, nested data, and query serving at scale. It connects directly to Fanout's storage and analytics material without becoming a database-product tour.`,learns:[`Why columnar layout can reduce bytes read for analytical queries.`,`How nested records can be represented with repetition and definition levels.`,`Why interactive analytics needs a different serving shape than OLTP.`],explore:{label:`Explore Columnar Systems`,href:`/system/archive/columnar-vs-wide-column-stores`,description:`Read Fanout's columnar storage note and connect Dremel to analytics scans, warehouse layout, and serving tradeoffs.`},preview:{badge:`VLDB`,accent:`#E8822A`,background:`#FFF8ED`,figure:`bars`}},{id:`2026-07-04-bigtable`,date:`2026-07-04`,url:`https://research.google/pubs/bigtable-a-distributed-storage-system-for-structured-data/`,title:`Bigtable: A Distributed Storage System for Structured Data`,authors:`Chang et al.`,venue:`OSDI 2006`,lane:`Systems`,difficulty:`Easy`,readTime:`45 min`,description:`Bigtable is the beginner-friendly bridge from simple key-value stores to distributed sorted maps. It teaches rows, tablets, locality, metadata, and why storage shape follows access patterns.`,learns:[`How row keys and tablets create a scalable sorted-map abstraction.`,`Why locality groups and compaction matter for read and write behavior.`,`How metadata and tablet assignment become part of storage design.`],explore:{label:`Explore Bigtable on Fanout`,href:`/system/archive/source-google-bigtable-paper`,description:`Read Fanout's Bigtable source summary and connect it to tablets, LSM storage, locality, and hot partitions.`},preview:{badge:`OSDI`,accent:`#6E56CF`,background:`#F8F5FF`,figure:`matrix`}},{id:`2026-07-03-google-file-system`,date:`2026-07-03`,url:`https://research.google/pubs/the-google-file-system/`,title:`The Google File System`,authors:`Ghemawat et al.`,venue:`SOSP 2003`,lane:`Systems`,difficulty:`Easy`,readTime:`40 min`,description:`GFS is a useful first distributed storage paper because the assumptions are explicit: large files, append-heavy workloads, commodity failures, and a master that keeps metadata tractable.`,learns:[`How chunks, chunkservers, and a master split data from metadata.`,`Why workload assumptions can simplify a distributed file system.`,`How leases, replication, and recovery handle common machine failures.`],explore:{label:`Explore Storage Systems`,href:`/system/archive/storage-engine-tradeoffs`,description:`Continue into Fanout's storage material around durable bytes, indexes, replication, and operational tradeoffs.`},preview:{badge:`SOSP`,accent:`#E8822A`,background:`#FFF8ED`,figure:`network`}},{id:`2026-07-02-mathematical-theory-of-communication`,date:`2026-07-02`,url:`https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf`,title:`A Mathematical Theory of Communication`,authors:`Claude Shannon`,venue:`Bell System Technical Journal 1948`,lane:`ML Math`,difficulty:`Hard`,readTime:`65 min`,description:`Shannon's information theory paper is hard but worth anchoring early in the calendar. Entropy, bits, uncertainty, and channel capacity sit underneath compression, coding, language modeling, and evaluation intuition.`,learns:[`How entropy gives uncertainty a quantitative unit.`,`Why communication can be separated into source, channel, noise, and code.`,`How information-theoretic language appears later in ML objectives.`],explore:{label:`Explore Information Theory`,href:`/knowledge-graph?node=ai-research%3Amodule%3Amath-fundamentals&detail=ai-research%3Aconcept%3Aentropy-and-information-theory`,description:`Open Fanout's math fundamentals topic for entropy, information theory, cross-entropy, and model objectives.`},preview:{badge:`INFO`,accent:`#0F9D58`,background:`#F3FBF6`,figure:`curve`}},{id:`2026-07-01-perceptron`,date:`2026-07-01`,url:`https://bpb-us-e2.wpmucdn.com/websites.umass.edu/dist/a/27637/files/2016/03/rosenblatt-1957.pdf`,title:`The Perceptron`,authors:`Frank Rosenblatt`,venue:`Psychological Review 1958`,lane:`AI Research`,difficulty:`Very Easy`,readTime:`30 min`,description:`The Perceptron is a good July 1 starting point because it gives learners the original linear-classifier idea before modern depth, attention, or scale enter the story.`,learns:[`How a weighted input rule turns examples into a learned decision boundary.`,`Why early neural-network optimism centered on simple trainable units.`,`What limitations later architectures had to overcome.`],explore:{label:`Explore Neural Networks`,href:`/knowledge-graph?node=ai-research%3Amodule%3Aneural-network-from-scratch`,description:`Start Fanout's neural-network path and connect the perceptron to neurons, weights, gradients, and modern layers.`},preview:{badge:`1958`,accent:`#2F7CF6`,background:`#F5F8FF`,figure:`bars`}}],r=n[0]}));function ne(e){return`${l}${e}`}function a(e){return!!(e.dailyId&&u.has(e.dailyId))}function re(e){if(d.size===0)for(let e of $.values())e.dailyId&&d.set(e.dailyId,e.id);return d.get(e)}function ie(e){return a(e)?`/daily/${e.dailyId}`:e.url}function o(e,...t){return t.map(t=>({paper:t,tier:e}))}function ae(e){return Q.find(t=>t.id===e)}function oe(e){return s.includes(e)?e:s[0]}function se(e){return new Set(e.placements.map(({paper:e})=>e.id))}function ce(e,t){let ee=se(e);return t.prerequisites.filter(e=>ee.has(e))}function le(e){return e.placements.filter(({paper:t})=>t.homeTrack===e.id).sort((e,t)=>c[e.tier]-c[t.tier])}function ue(){let e=new Map;for(let t of Q)e.set(t.id,le(t));return e}var s,c,l,u,d,f,p,m,h,g,_,v,y,b,x,S,C,w,T,E,D,O,k,A,j,M,N,P,F,I,L,R,z,B,V,H,U,W,G,K,q,de,fe,pe,me,he,ge,_e,ve,ye,be,xe,Se,Ce,we,Te,Ee,De,Oe,ke,Ae,je,J,Y,Me,Ne,Pe,Fe,Ie,Le,Re,ze,Be,Ve,He,Ue,We,Ge,Ke,qe,Je,Ye,Xe,Ze,Qe,$e,et,tt,nt,rt,it,X,at,ot,st,ct,lt,ut,Z,Q,$,dt=e((()=>{i(),s=[`ai-research`,`systems`,`rl`,`inference`],c={founding:0,core:1,frontier:2},l=`papers/`,u=new Map(n.map(e=>[e.id,e])),d=new Map,f={id:`perceptron`,title:`The Perceptron`,authors:`Frank Rosenblatt`,year:1958,url:`https://bpb-us-e2.wpmucdn.com/websites.umass.edu/dist/a/27637/files/2016/03/rosenblatt-1957.pdf`,dailyId:`2026-07-01-perceptron`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[],why:`The first learning rule for a linear classifier: nudge the weights after each mistake. Every later network is stacks of this unit with a smoother training signal.`},p={id:`alexnet`,title:`ImageNet Classification with Deep Convolutional Neural Networks`,authors:`Alex Krizhevsky, Ilya Sutskever, and Geoffrey E. Hinton`,year:2012,url:`https://papers.nips.cc/paper_files/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html`,dailyId:`2026-09-01-alexnet-image-classification`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`perceptron`],why:`A deep convolutional network trained on GPUs cut ImageNet error nearly in half. It shows why depth, ReLU, and data augmentation became the default recipe.`},m={id:`word2vec`,title:`Efficient Estimation of Word Representations in Vector Space`,authors:`Mikolov et al.`,year:2013,url:`https://arxiv.org/abs/1301.3781`,dailyId:`2026-07-08-word2vec`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[],why:`Trains dense word vectors from a simple prediction task and shows that arithmetic on them recovers analogies. The cleanest introduction to learned embeddings.`},h={id:`sequence-to-sequence`,title:`Sequence to Sequence Learning with Neural Networks`,authors:`Sutskever et al.`,year:2014,url:`https://arxiv.org/abs/1409.3215`,dailyId:`2026-07-07-sequence-to-sequence`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`word2vec`],why:`An encoder reads a sentence into one vector and a decoder writes the translation out. The encoder-decoder shape, and the bottleneck it creates, set up attention.`},g={id:`adam`,title:`Adam: A Method for Stochastic Optimization`,authors:`Kingma and Ba`,year:2014,url:`https://arxiv.org/abs/1412.6980`,dailyId:`2026-07-06-adam`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[],why:`Per-parameter step sizes from running estimates of the gradient's mean and variance. The optimizer most later papers assume without discussion.`},_={id:`dropout`,title:`Dropout: A Simple Way to Prevent Neural Networks from Overfitting`,authors:`Srivastava et al.`,year:2014,url:`https://jmlr.org/papers/v15/srivastava14a.html`,dailyId:`2026-07-23-dropout`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[],why:`Randomly dropping units during training makes a network behave like an averaged ensemble. Explains a regularizer you will meet in nearly every architecture.`},v={id:`batch-normalization`,title:`Batch Normalization`,authors:`Ioffe and Szegedy`,year:2015,url:`https://arxiv.org/abs/1502.03167`,dailyId:`2026-07-10-batch-normalization`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`alexnet`],why:`Normalizing activations per mini-batch lets much deeper networks train with larger learning rates. LayerNorm and RMSNorm are variations on this move.`},y={id:`resnet`,title:`Deep Residual Learning for Image Recognition`,authors:`He et al.`,year:2015,url:`https://arxiv.org/abs/1512.03385`,dailyId:`2026-07-09-resnet`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`alexnet`,`batch-normalization`],why:`Skip connections let a layer learn a residual instead of a full mapping, so networks with a hundred layers train. The residual stream inside a transformer comes directly from here.`},b={id:`vae`,title:`Auto-Encoding Variational Bayes`,authors:`Kingma and Welling`,year:2013,url:`https://arxiv.org/abs/1312.6114`,dailyId:`2026-07-24-auto-encoding-variational-bayes`,homeTrack:`ai-research`,difficulty:`hard`,prerequisites:[],why:`Derives a tractable lower bound for training a latent-variable generative model by gradient descent. The probabilistic groundwork under diffusion models.`},x={id:`gan`,title:`Generative Adversarial Nets`,authors:`Goodfellow, Pouget-Abadie, Mirza, Xu, Warde-Farley, Ozair, Courville, and Bengio`,year:2014,url:`https://proceedings.neurips.cc/paper_files/paper/2014/file/f033ed80deb0234979a61f95710dbe25-Paper.pdf`,dailyId:`2026-08-29-generative-adversarial-nets`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[],why:`Trains a generator against a discriminator as a two-player game instead of maximizing likelihood. Read it to understand adversarial training and why it is unstable.`},S={id:`attention-is-all-you-need`,title:`Attention Is All You Need`,authors:`Vaswani et al.`,year:2017,url:`https://arxiv.org/abs/1706.03762`,dailyId:`2026-07-19-attention-is-all-you-need`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`sequence-to-sequence`,`resnet`,`dropout`,`adam`],why:`Replaces recurrence with attention so every token can look at every other token in one step. Every later language model paper assumes you know this one.`},C={id:`bert`,title:`BERT: Pre-training of Deep Bidirectional Transformers`,authors:`Devlin et al.`,year:2018,url:`https://arxiv.org/abs/1810.04805`,dailyId:`2026-07-11-bert`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`],why:`Pretrains a bidirectional encoder on masked tokens, then fine-tunes it per task. It established the pretrain-then-adapt workflow that later models inherit.`},w={id:`gpt3`,title:`Language Models are Few-Shot Learners`,authors:`Brown et al.`,year:2020,url:`https://arxiv.org/abs/2005.14165v4`,dailyId:`2026-09-03-gpt3-few-shot-learners`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`,`scaling-laws`],why:`Shows that a large enough decoder can do new tasks from examples in its prompt, with no gradient updates. In-context learning and prompting start here.`},T={id:`scaling-laws`,title:`Scaling Laws for Neural Language Models`,authors:`Kaplan et al.`,year:2020,url:`https://arxiv.org/abs/2001.08361`,dailyId:`2026-07-17-scaling-laws`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`],why:`Fits loss as a power law in parameters, data, and compute across several orders of magnitude. It turns model sizing from a guess into a calculation.`},E={id:`chinchilla`,title:`Training Compute-Optimal Large Language Models`,authors:`Hoffmann et al.`,year:2022,url:`https://arxiv.org/abs/2203.15556`,dailyId:`2026-07-16-chinchilla`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`scaling-laws`],why:`Revisits the scaling fits and finds most large models were undertrained on data for their size. Explains why later models use far more tokens per parameter.`},D={id:`knowledge-distillation`,title:`Distilling the Knowledge in a Neural Network`,authors:`Hinton, Vinyals, and Dean`,year:2015,url:`https://arxiv.org/abs/1503.02531`,dailyId:`2026-07-29-knowledge-distillation`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`dropout`],why:`Trains a small model to match a large model's softened output distribution rather than hard labels. The basis for most model compression and teacher-student setups.`},O={id:`switch-transformers`,title:`Switch Transformers: Scaling to Trillion Parameter Models with Simple and Efficient Sparsity`,authors:`Fedus, Zoph, and Shazeer`,year:2021,url:`https://www.jmlr.org/papers/v23/21-0998.html`,dailyId:`2026-07-30-switch-transformers`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`],why:`Routes each token to one expert feed-forward block so parameter count grows without extra compute per token. The starting point for any mixture-of-experts paper.`},k={id:`chain-of-thought`,title:`Chain-of-Thought Prompting Elicits Reasoning in Large Language Models`,authors:`Wei, Wang, Schuurmans, Bosma, Ichter, Xia, Chi, Le, and Zhou`,year:2022,url:`https://arxiv.org/abs/2201.11903`,dailyId:`2026-08-18-chain-of-thought`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`gpt3`],why:`Asking a large model to write intermediate steps before its answer raises accuracy on reasoning tasks. A short paper that reframes prompting as controlling computation.`},A={id:`lora`,title:`LoRA: Low-Rank Adaptation of Large Language Models`,authors:`Hu et al.`,year:2021,url:`https://arxiv.org/abs/2106.09685`,dailyId:`2026-07-12-lora`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`gpt3`],why:`Fine-tunes a frozen model by learning low-rank updates to its weight matrices. It is how most people adapt a large model on one GPU.`},j={id:`rag`,title:`Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks`,authors:`Lewis et al.`,year:2020,url:`https://arxiv.org/abs/2005.11401`,dailyId:`2026-07-26-retrieval-augmented-generation`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`bert`,`sequence-to-sequence`],why:`Pairs a dense retriever with a generator so answers can draw on documents outside the weights. The reference design behind retrieval-augmented systems.`},M={id:`react`,title:`ReAct: Synergizing Reasoning and Acting in Language Models`,authors:`Yao, Zhao, Yu, Du, Shafran, Narasimhan, and Cao`,year:2022,url:`https://arxiv.org/abs/2210.03629v3`,dailyId:`2026-08-10-react-reasoning-acting`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`chain-of-thought`],why:`Interleaves reasoning traces with tool actions so a model can plan, act, and revise. Most agent loops are a variation on this pattern.`},N={id:`toolformer`,title:`Toolformer: Language Models Can Teach Themselves to Use Tools`,authors:`Schick et al.`,year:2023,url:`https://proceedings.neurips.cc/paper_files/paper/2023/hash/d842425e4bf79ba039352da0f658a906-Abstract-Conference.html`,dailyId:`2026-08-20-toolformer`,homeTrack:`ai-research`,difficulty:`simple`,prerequisites:[`gpt3`],why:`A model labels its own training data with API calls that improve its predictions, then learns to make them. Shows how tool use can be trained rather than prompted.`},P={id:`clip`,title:`Learning Transferable Visual Models From Natural Language Supervision`,authors:`Radford et al.`,year:2021,url:`https://proceedings.mlr.press/v139/radford21a.html`,dailyId:`2026-08-23-clip-natural-language-supervision`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`,`resnet`],why:`Trains an image encoder and a text encoder to agree on matching pairs, giving zero-shot classification from captions. The shared embedding space under most vision-language work.`},F={id:`segment-anything`,title:`Segment Anything`,authors:`Kirillov et al.`,year:2023,url:`https://openaccess.thecvf.com/content/ICCV2023/html/Kirillov_Segment_Anything_ICCV_2023_paper.html`,dailyId:`2026-08-25-segment-anything`,homeTrack:`ai-research`,difficulty:`medium`,prerequisites:[`clip`],why:`A promptable segmentation model trained on a billion masks that transfers without fine-tuning. Shows what a foundation model looks like outside language.`},I={id:`mamba`,title:`Mamba: Linear-Time Sequence Modeling with Selective State Spaces`,authors:`Gu and Dao`,year:2023,url:`https://arxiv.org/abs/2312.00752v2`,dailyId:`2026-08-07-mamba-selective-state-spaces`,homeTrack:`ai-research`,difficulty:`hard`,prerequisites:[`attention-is-all-you-need`],why:`A selective state-space model with linear-time sequence mixing that matches transformers at moderate scale. Read it to understand the main alternative to attention.`},L={id:`ddpm`,title:`Denoising Diffusion Probabilistic Models`,authors:`Ho, Jain, and Abbeel`,year:2020,url:`https://arxiv.org/abs/2006.11239v2`,dailyId:`2026-10-29-denoising-diffusion-probabilistic-models`,homeTrack:`ai-research`,difficulty:`hard`,prerequisites:[`vae`],why:`Trains a network to reverse a gradual noising process, with a simple objective that turns out to be a reweighted variational bound. The foundation of modern image generation.`},R={id:`shannon-communication`,title:`A Mathematical Theory of Communication`,authors:`Claude Shannon`,year:1948,url:`https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf`,dailyId:`2026-07-02-mathematical-theory-of-communication`,homeTrack:`systems`,difficulty:`hard`,prerequisites:[],why:`Defines information in bits and proves the limits on compression and on reliable transmission over a noisy channel. Every coding and networking result is measured against it.`},z={id:`dijkstra-shortest-path`,title:`A Note on Two Problems in Connexion with Graphs`,authors:`E. W. Dijkstra`,year:1959,url:`https://doi.org/10.1007/BF01386390`,dailyId:`2026-08-30-dijkstra-shortest-path`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`Two short algorithms, one for spanning trees and one for shortest paths in a weighted graph. Routing protocols still run the second one.`},B={id:`bloom-filter`,title:`Space/Time Trade-offs in Hash Coding with Allowable Errors`,authors:`Burton H. Bloom`,year:1970,url:`https://dl.acm.org/doi/10.1145/362686.362692`,dailyId:`2026-08-17-bloom-filter`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`A bit array and a few hash functions answer membership queries with no false negatives and a tunable false positive rate. The trade of exactness for space recurs across storage systems.`},V={id:`ethernet`,title:`Ethernet: Distributed Packet Switching for Local Computer Networks`,authors:`Robert M. Metcalfe and David R. Boggs`,year:1976,url:`https://doi.org/10.1145/360248.360253`,dailyId:`2026-09-04-ethernet-distributed-packet-switching`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`Stations share one cable by listening before sending, detecting collisions, and backing off at random. Shows how distributed coordination works without a central arbiter.`},H={id:`lz77`,title:`A Universal Algorithm for Sequential Data Compression`,authors:`Jacob Ziv and Abraham Lempel`,year:1977,url:`https://doi.org/10.1109/TIT.1977.1055714`,dailyId:`2026-09-02-lz77-sequential-compression`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`shannon-communication`],why:`Compresses by replacing repeated substrings with references to earlier text, approaching the source entropy without knowing its statistics. The algorithm inside gzip, PNG, and zstd.`},U={id:`end-to-end-arguments`,title:`End-to-End Arguments in System Design`,authors:`Saltzer, Reed, and Clark`,year:1984,url:`https://web.mit.edu/saltzer/www/publications/endtoend/endtoendA4.pdf`,dailyId:`2026-08-21-end-to-end-arguments`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`Argues that functions like reliability belong at the endpoints, because a lower layer can only do them incompletely. A design principle you will apply to every layered system.`},W={id:`congestion-avoidance`,title:`Congestion Avoidance and Control`,authors:`Van Jacobson`,year:1988,url:`https://doi.org/10.1145/52324.52356`,dailyId:`2026-08-13-congestion-avoidance-control`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`ethernet`,`end-to-end-arguments`],why:`Adds slow start and additive-increase, multiplicative-decrease to TCP so senders find a fair share of a bottleneck. Explains why the internet stays usable under load.`},G={id:`dns`,title:`Development of the Domain Name System`,authors:`Mockapetris and Dunlap`,year:1988,url:`https://dl.acm.org/doi/10.1145/52324.52338`,dailyId:`2026-08-22-development-domain-name-system`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`A hierarchical, cached, delegated name database that replaced one shared hosts file. Lessons on caching, TTLs, and delegation that apply to any global lookup service.`},K={id:`consistent-hashing`,title:`Consistent Hashing and Random Trees: Distributed Caching Protocols for Relieving Hot Spots on the World Wide Web`,authors:`David Karger, Eric Lehman, Tom Leighton, Matthew Levine, Daniel Lewin, and Rina Panigrahy`,year:1997,url:`https://doi.org/10.1145/258533.258660`,dailyId:`2026-09-05-consistent-hashing-random-trees`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[],why:`Maps keys and servers onto the same ring so adding one server moves only its share of keys. The placement scheme behind distributed caches and key-value stores.`},q={id:`cap-theorem`,title:`Brewer’s Conjecture and the Feasibility of Consistent, Available, Partition-Tolerant Web Services`,authors:`Seth Gilbert and Nancy Lynch`,year:2002,url:`https://doi.org/10.1145/564585.564601`,dailyId:`2026-08-31-cap-theorem`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`Proves that when the network partitions, a service must give up either consistency or availability for the duration. It sets the trade-off every distributed database paper positions itself against.`},de={id:`pagerank`,title:`The PageRank Citation Ranking: Bringing Order to the Web`,authors:`Page, Brin, Motwani, and Winograd`,year:1998,url:`https://ilpubs.stanford.edu/422/`,dailyId:`2026-08-11-pagerank`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[],why:`Scores a page by how often a reader who keeps clicking random links would end up on it. A compact example of turning link structure into a ranking at web scale.`},fe={id:`google-file-system`,title:`The Google File System`,authors:`Ghemawat et al.`,year:2003,url:`https://research.google/pubs/the-google-file-system/`,dailyId:`2026-07-03-google-file-system`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`end-to-end-arguments`],why:`A file system for large append-heavy files on commodity machines that fail constantly, with a single master and relaxed consistency. The storage layer that MapReduce and Bigtable build on.`},pe={id:`mapreduce`,title:`MapReduce`,authors:`Dean and Ghemawat`,year:2004,url:`https://research.google/pubs/mapreduce-simplified-data-processing-on-large-clusters/`,dailyId:`2026-07-14-mapreduce`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[`google-file-system`],why:`Two user functions and a runtime that handles partitioning, scheduling, and failures across thousands of machines. The programming model behind most batch data systems.`},me={id:`bigtable`,title:`Bigtable: A Distributed Storage System for Structured Data`,authors:`Chang et al.`,year:2006,url:`https://research.google/pubs/bigtable-a-distributed-storage-system-for-structured-data/`,dailyId:`2026-07-04-bigtable`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`google-file-system`,`bloom-filter`],why:`A sparse sorted map stored as tablets over GFS, with a log-structured write path. The design that HBase and many later stores copy.`},he={id:`dynamo`,title:`Dynamo: Amazon's Highly Available Key-value Store`,authors:`DeCandia et al.`,year:2007,url:`https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf`,dailyId:`2026-07-15-dynamo`,homeTrack:`systems`,difficulty:`hard`,prerequisites:[`cap-theorem`,`consistent-hashing`],why:`Chooses availability over consistency and shows what that costs: vector clocks, sloppy quorums, hinted handoff, and reconciliation at read time. The reference for eventually consistent stores.`},ge={id:`raft`,title:`In Search of an Understandable Consensus Algorithm`,authors:`Ongaro and Ousterhout`,year:2014,url:`https://raft.github.io/raft.pdf`,dailyId:`2026-07-13-raft`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`cap-theorem`],why:`Consensus decomposed into leader election, log replication, and safety, designed so people can understand it. The algorithm inside etcd and most modern replicated logs.`},_e={id:`kafka`,title:`Kafka: a Distributed Messaging System for Log Processing`,authors:`Kreps, Narkhede, and Rao`,year:2011,url:`https://www.microsoft.com/en-us/research/wp-content/uploads/2017/09/Kafka.pdf`,dailyId:`2026-08-28-kafka-distributed-log`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[`mapreduce`],why:`A partitioned, append-only log that consumers pull from at their own offsets, with no per-message state on the broker. Explains why the log became the backbone of streaming systems.`},ve={id:`tail-at-scale`,title:`The Tail at Scale`,authors:`Dean and Barroso`,year:2013,url:`https://research.google/pubs/the-tail-at-scale/`,dailyId:`2026-07-28-tail-at-scale`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[`mapreduce`],why:`When a request fans out to many servers, rare slow responses dominate latency. Gives the techniques, hedged and tied requests among them, that keep the tail in check.`},ye={id:`dremel`,title:`Dremel: Interactive Analysis of Web-Scale Datasets`,authors:`Melnik et al.`,year:2010,url:`https://research.google/pubs/dremel-interactive-analysis-of-web-scale-datasets/`,dailyId:`2026-07-05-dremel`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`mapreduce`,`bigtable`],why:`Columnar storage for nested records plus a serving tree that answers aggregation queries in seconds. The design behind BigQuery and the Parquet format.`},be={id:`borg`,title:`Large-scale cluster management at Google with Borg`,authors:`Verma et al.`,year:2015,url:`https://research.google/pubs/large-scale-cluster-management-at-google-with-borg/`,dailyId:`2026-08-24-google-borg-cluster-management`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`mapreduce`,`google-file-system`],why:`Google's cluster manager: jobs, allocs, priorities, and bin packing across tens of thousands of machines. Read it to understand the decisions Kubernetes inherited.`},xe={id:`tor`,title:`Tor: The Second-Generation Onion Router`,authors:`Dingledine, Mathewson, and Syverson`,year:2004,url:`https://www.usenix.org/conference/13th-usenix-security-symposium/tor-second-generation-onion-router`,dailyId:`2026-08-16-tor-onion-router`,homeTrack:`systems`,difficulty:`medium`,prerequisites:[`end-to-end-arguments`],why:`Layered encryption through a circuit of volunteer relays so no single hop knows both sender and destination. A careful example of a threat model shaping a design.`},Se={id:`bitcoin`,title:`Bitcoin: A Peer-to-Peer Electronic Cash System`,authors:`Satoshi Nakamoto`,year:2008,url:`https://bitcoin.org/bitcoin.pdf`,dailyId:`2026-08-14-bitcoin-proof-of-work`,homeTrack:`systems`,difficulty:`simple`,prerequisites:[`cap-theorem`,`raft`],why:`A shared ledger ordered by proof of work, so strangers agree on history without a trusted party. Read it to see consensus under an adversarial membership model.`},Ce={id:`q-learning`,title:`Q-learning`,authors:`Watkins and Dayan`,year:1992,url:`https://link.springer.com/article/10.1007/BF00992698`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[],why:`Learns the value of each action from experience alone, with a convergence proof. DQN is this idea plus a neural network.`},we={id:`reinforce`,title:`Simple Statistical Gradient-Following Algorithms for Connectionist Reinforcement Learning`,authors:`Williams`,year:1992,url:`https://link.springer.com/article/10.1007/BF00992696`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[],why:`Derives the gradient of expected reward with respect to policy parameters from sampled returns. The simplest policy gradient and the base of every one that follows.`},Te={id:`policy-gradient-theorem`,title:`Policy Gradient Methods for Reinforcement Learning with Function Approximation`,authors:`Sutton, McAllester, Singh, and Mansour`,year:1999,url:`https://proceedings.neurips.cc/paper/1999/hash/464d828b85b0bed98e80ade0a5c43b0f-Abstract.html`,homeTrack:`rl`,difficulty:`hard`,prerequisites:[`reinforce`],why:`Proves the policy gradient can be written with a learned value function and still point the right way. It justifies actor-critic methods and the advantage estimates in PPO.`},Ee={id:`dqn`,title:`Playing Atari with Deep Reinforcement Learning`,authors:`Mnih et al.`,year:2013,url:`https://arxiv.org/abs/1312.5602`,homeTrack:`rl`,difficulty:`simple`,prerequisites:[`q-learning`],why:`Q-learning with a convolutional network and experience replay, trained from raw pixels. The first deep RL result most courses teach.`},De={id:`trpo`,title:`Trust Region Policy Optimization`,authors:`Schulman et al.`,year:2015,url:`https://arxiv.org/abs/1502.05477`,homeTrack:`rl`,difficulty:`hard`,prerequisites:[`policy-gradient-theorem`],why:`Constrains each policy update by a KL divergence so improvement is monotonic in theory. Read it to see what PPO is approximating.`},Oe={id:`gae`,title:`High-Dimensional Continuous Control Using Generalized Advantage Estimation`,authors:`Schulman et al.`,year:2015,url:`https://arxiv.org/abs/1506.02438`,homeTrack:`rl`,difficulty:`hard`,prerequisites:[`policy-gradient-theorem`],why:`Blends n-step advantage estimates with an exponential weight to trade bias against variance. The advantage estimator used in nearly all on-policy training.`},ke={id:`ppo`,title:`Proximal Policy Optimization Algorithms`,authors:`Schulman et al.`,year:2017,url:`https://arxiv.org/abs/1707.06347`,dailyId:`2026-08-01-proximal-policy-optimization`,homeTrack:`rl`,difficulty:`hard`,prerequisites:[`trpo`,`gae`],why:`Replaces the trust-region constraint with a clipped objective that a plain optimizer can handle. The algorithm behind RLHF fine-tuning and most policy training since.`},Ae={id:`alphago`,title:`Mastering the game of Go with deep neural networks and tree search`,authors:`Silver et al.`,year:2016,url:`https://deepmind-media.storage.googleapis.com/alphago/AlphaGoNaturePaper.pdf`,dailyId:`2026-08-15-alphago-neural-tree-search`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[`dqn`,`policy-gradient-theorem`],why:`Combines a policy network, a value network, and Monte Carlo tree search to beat a professional Go player. Shows how learned priors and search reinforce each other.`},je={id:`rlhf-preferences`,title:`Deep Reinforcement Learning from Human Preferences`,authors:`Christiano et al.`,year:2017,url:`https://arxiv.org/abs/1706.03741`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[`trpo`],why:`Learns a reward model from human comparisons of trajectory pairs, then optimizes the policy against it. The two-stage recipe that RLHF for language models reuses.`},J={id:`instructgpt`,title:`Training Language Models to Follow Instructions with Human Feedback`,authors:`Ouyang et al.`,year:2022,url:`https://arxiv.org/abs/2203.02155`,dailyId:`2026-07-31-instructgpt`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[`gpt3`,`rlhf-preferences`,`ppo`],why:`Applies supervised fine-tuning, a preference reward model, and PPO to make GPT-3 follow instructions. The alignment pipeline every chat model descends from.`},Y={id:`dpo`,title:`Direct Preference Optimization: Your Language Model is Secretly a Reward Model`,authors:`Rafailov et al.`,year:2023,url:`https://arxiv.org/abs/2305.18290`,dailyId:`2026-07-22-direct-preference-optimization`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[`instructgpt`],why:`Rewrites the RLHF objective so the policy trains directly on preference pairs, with no reward model or sampling loop. Read it to see what the RL step was actually computing.`},Me={id:`grpo`,title:`DeepSeekMath: Pushing the Limits of Mathematical Reasoning in Open Language Models`,authors:`Shao et al.`,year:2024,url:`https://arxiv.org/abs/2402.03300`,dailyId:`2026-08-02-deepseekmath-grpo`,homeTrack:`rl`,difficulty:`hard`,prerequisites:[`ppo`],why:`Drops the value network and estimates advantages from a group of sampled answers to the same prompt. The variant of PPO that trained the DeepSeek reasoning models.`},Ne={id:`deepseek-r1`,title:`DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning`,authors:`DeepSeek-AI`,year:2025,url:`https://arxiv.org/abs/2501.12948`,homeTrack:`rl`,difficulty:`medium`,prerequisites:[`grpo`],why:`Reports that behaviors such as self-checking emerge from RL on verifiable rewards alone, then distills them into smaller models. The current reference for reasoning training.`},Pe={id:`rmsnorm`,title:`Root Mean Square Layer Normalization`,authors:`Zhang and Sennrich`,year:2019,url:`https://papers.nips.cc/paper_files/paper/2019/hash/1e8a19426224ca89e83cef47f1e7f53b-Abstract.html`,dailyId:`2026-08-06-rmsnorm`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`],why:`Drops mean centering from LayerNorm and keeps only the scale, with no loss in quality and less compute. The normalizer in Llama and most current decoders.`},Fe={id:`flashattention`,title:`FlashAttention`,authors:`Dao et al.`,year:2022,url:`https://arxiv.org/abs/2205.14135`,dailyId:`2026-07-18-flashattention`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`attention-is-all-you-need`],why:`Computes exact attention in tiles that fit in SRAM, never materializing the full score matrix. Read it to understand why attention is bound by memory traffic, not FLOPs.`},Ie={id:`gqa`,title:`GQA: Training Generalized Multi-Query Transformer Models from Multi-Head Checkpoints`,authors:`Ainslie et al.`,year:2023,url:`https://aclanthology.org/2023.emnlp-main.298/`,dailyId:`2026-08-03-grouped-query-attention`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`],why:`Shares key and value heads across groups of query heads to shrink the KV cache with little quality loss. Explains a knob in nearly every current model config.`},Le={id:`orca`,title:`Orca: A Distributed Serving System for Transformer-Based Generative Models`,authors:`Yu et al.`,year:2022,url:`https://www.usenix.org/conference/osdi22/presentation/yu`,dailyId:`2026-08-04-orca-continuous-batching`,homeTrack:`inference`,difficulty:`simple`,prerequisites:[`attention-is-all-you-need`],why:`Schedules at the iteration level so new requests join a batch as others finish, instead of waiting for the slowest sequence. The origin of continuous batching.`},Re={id:`zero`,title:`ZeRO: Memory Optimizations Toward Training Trillion Parameter Models`,authors:`Rajbhandari et al.`,year:2020,url:`https://arxiv.org/abs/1910.02054v3`,dailyId:`2026-08-05-zero-memory-optimization`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`,`scaling-laws`],why:`Partitions optimizer state, gradients, and parameters across data-parallel workers so each GPU holds only its slice and per-device memory falls as you add devices. The technique behind FSDP and DeepSpeed.`},ze={id:`speculative-decoding`,title:`Fast Inference from Transformers via Speculative Decoding`,authors:`Leviathan, Kalman, and Matias`,year:2023,url:`https://proceedings.mlr.press/v202/leviathan23a.html`,dailyId:`2026-07-27-speculative-decoding`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`attention-is-all-you-need`],why:`A small model drafts several tokens and the large model verifies them in one pass, with no change to the output distribution. Read it to see where decode latency can actually be recovered.`},Be={id:`pagedattention`,title:`Efficient Memory Management for Large Language Model Serving with PagedAttention`,authors:`Kwon et al.`,year:2023,url:`https://arxiv.org/abs/2309.06180`,dailyId:`2026-07-21-pagedattention`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`orca`],why:`Stores the KV cache in fixed-size blocks behind a page table, ending fragmentation and allowing sharing across sequences. The memory model inside vLLM.`},Ve={id:`flashattention-2`,title:`FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning`,authors:`Tri Dao`,year:2023,url:`https://arxiv.org/abs/2307.08691v1`,dailyId:`2026-08-08-flashattention-2`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`flashattention`],why:`Reworks the loop order and warp partitioning so the tiled kernel spends more of its time in matrix multiplies. Read it to see how kernel details turn into throughput.`},He={id:`ring-attention`,title:`Ring Attention with Blockwise Transformers for Near-Infinite Context`,authors:`Liu, Zaharia, and Abbeel`,year:2023,url:`https://arxiv.org/abs/2310.01889v4`,dailyId:`2026-08-09-ring-attention`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`flashattention`],why:`Passes KV blocks around a ring of devices while each computes its local attention tiles, so context length scales with device count. The basis of long-context training.`},Ue={id:`kv-cache-survey`,title:`From Tensor Buffer to Distributed Memory Hierarchy`,authors:`Li, Wang, and Chen`,year:2026,url:`https://arxiv.org/abs/2607.02574`,dailyId:`2026-07-20-kv-cache-management-survey`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`pagedattention`,`gqa`],why:`Organizes KV cache techniques by where the cache lives, from a single tensor to a distributed memory hierarchy. A map for placing every other inference paper.`},We={id:`deepseek-v2-mla`,title:`DeepSeek-V2: A Strong, Economical, and Efficient Mixture-of-Experts Language Model`,authors:`DeepSeek-AI`,year:2024,url:`https://arxiv.org/abs/2405.04434`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`gqa`],why:`Introduces Multi-head Latent Attention: compress keys and values into one low-rank latent and cache that instead of the heads. GQA shrinks the cache by a constant factor, MLA changes its shape, and every later cache design answers this paper.`},Ge={id:`vattention`,title:`vAttention: Dynamic Memory Management for Serving LLMs without PagedAttention`,authors:`Prabhu et al.`,year:2024,url:`https://arxiv.org/abs/2405.04437`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`pagedattention`],why:`Keeps the KV cache contiguous in virtual memory and lets the GPU's own paging handle fragmentation, so the attention kernel needs no block table at all. Read it as the argument that PagedAttention solved a real problem in the wrong layer.`},Ke={id:`minference`,title:`MInference 1.0: Accelerating Pre-filling for Long-Context LLMs via Dynamic Sparse Attention`,authors:`Jiang et al.`,year:2024,url:`https://arxiv.org/abs/2407.02490`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`flashattention-2`],why:`Sorts each attention head into one of three sparse shapes offline, then builds the index online so a million-token prefill skips most of the score matrix. The time-to-first-token half of long context, which tiling alone never fixes.`},qe={id:`native-sparse-attention`,title:`Native Sparse Attention: Hardware-Aligned and Natively Trainable Sparse Attention`,authors:`Yuan et al.`,year:2025,url:`https://arxiv.org/abs/2502.11089`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`deepseek-v2-mla`,`flashattention-2`],why:`Splits attention into compression, selection, and sliding-window branches that the model trains with from the first step, rather than a mask applied to a finished model. The case for sparsity the weights have already adapted to.`},Je={id:`moba`,title:`MoBA: Mixture of Block Attention for Long-Context LLMs`,authors:`Lu et al.`,year:2025,url:`https://arxiv.org/abs/2502.13189`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`native-sparse-attention`],why:`Gates each query to a few key blocks the way an MoE layer routes to experts, and switches back to full attention without retraining. Published the same month as Native Sparse Attention by a different lab, which makes the design space visible.`},Ye={id:`deepseek-sparse-attention`,title:`DeepSeek-V3.2: Pushing the Frontier of Open Large Language Models`,authors:`DeepSeek-AI`,year:2025,url:`https://arxiv.org/abs/2512.02556`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`native-sparse-attention`,`kv-cache-survey`],why:`A lightning indexer scores the query against compressed keys, the top blocks are selected, and only those are attended. The first fine-grained sparse attention shipped in a frontier open model, with the kernels released in FlashMLA and DeepGEMM.`},Xe={id:`deepseek-v4`,title:`DeepSeek-V4: Towards Highly Efficient Million-Token Context Intelligence`,authors:`DeepSeek-AI`,year:2026,url:`https://arxiv.org/abs/2606.19348`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`deepseek-sparse-attention`],why:`Interleaves Compressed Sparse Attention with a far more aggressive Heavily Compressed Attention, reaching a million tokens on 27 percent of V3.2's per-token FLOPs and 10 percent of its KV cache. The current ceiling on what compression buys.`},Ze={id:`deepseek-v41-flash`,title:`DeepSeek-V4.1-Flash Technical Report`,authors:`DeepSeek-AI`,year:2026,url:`https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash/blob/main/DeepSeek_V41_Tech_Report.pdf`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`deepseek-v4`],why:`A causal encoder-decoder that activates 8B parameters for prefill and 16B for decode, with an FP4 cache near 890 bytes per token. Prefill and decode stop being two phases of one model and become two models sharing a backbone.`},Qe={id:`gated-deltanet`,title:`Gated Delta Networks: Improving Mamba2 with Delta Rule`,authors:`Yang, Kautz, and Hatamizadeh`,year:2024,url:`https://arxiv.org/abs/2412.06464`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`kv-cache-survey`,`mamba`],why:`Pairs a gated decay with the delta rule so a fixed-size recurrent state can both forget and overwrite, which is what earlier linear attention could not do. The primitive that ended up inside Qwen3-Next and the hybrids after it.`},$e={id:`kimi-linear`,title:`Kimi Linear: An Expressive, Efficient Attention Architecture`,authors:`Kimi Team`,year:2025,url:`https://arxiv.org/abs/2510.26692`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`gated-deltanet`],why:`Three Kimi Delta Attention layers for every full-attention layer: 75 percent less KV cache and up to six times the decode throughput, while scoring above full attention rather than near it. The result that made hybrids a default instead of a compromise.`},et={id:`mamba-3`,title:`Mamba-3: Improved Sequence Modeling using State Space Principles`,authors:`Lahoti et al.`,year:2026,url:`https://arxiv.org/abs/2603.15569`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`gated-deltanet`],why:`Where the state-space line landed after three rounds of fixing what a linear recurrence cannot express. Read it alongside Gated DeltaNet-2 (arXiv 2605.22791) for the current state of the fixed-state primitive.`},tt={id:`grouped-latent-attention`,title:`Hardware-Efficient Attention for Fast Decoding`,authors:`Zadouri, Strauss, and Dao`,year:2025,url:`https://arxiv.org/abs/2505.21487`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`deepseek-v2-mla`,`flashattention-2`],why:`Derives decode speed from arithmetic intensity and KV bytes per token, then designs Grouped Latent Attention to fit that budget. The clearest statement of decode as a bandwidth problem with a fixed allowance per token.`},nt={id:`hybrid-attention-morphing`,title:`Morphing into Hybrid Attention Models`,authors:`Lan et al.`,year:2026,url:`https://arxiv.org/abs/2606.30562`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`kimi-linear`],why:`Converts a trained full-attention checkpoint into a hybrid instead of pretraining one, which is the only version of this question a serving team can act on. Newer than the rest of this rung, so treat it as a live result rather than settled practice.`},rt={id:`megascale-infer`,title:`MegaScale-Infer: Serving Mixture-of-Experts at Scale with Disaggregated Expert Parallelism`,authors:`Zhu et al.`,year:2025,url:`https://arxiv.org/abs/2504.02263`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`zero`,`pagedattention`],why:`Sparse experts turn the feed-forward network from compute-bound into memory-bound, so attention and FFN move onto separate machines fed by a ping-pong pipeline. The systems bill that arrives once every frontier model is an MoE.`},it={id:`arctic-inference`,title:`Arctic Inference with Shift Parallelism: Fast and Efficient Open Source Inference System for Enterprise AI`,authors:`Rajbhandari et al.`,year:2025,url:`https://arxiv.org/abs/2507.11830`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`orca`,`pagedattention`],why:`Changes parallelism strategy with the traffic rather than committing a deployment to either latency or throughput, and adds SwiftKV to halve prefill compute by reusing early-layer hidden states. By the author of ZeRO, one rung below.`},X={id:`prefill-as-a-service`,title:`Prefill-as-a-Service: KVCache of Next-Generation Models Could Go Cross-Datacenter`,authors:`Qin et al.`,year:2026,url:`https://arxiv.org/abs/2604.15039`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`kv-cache-survey`,`megascale-infer`],why:`Takes disaggregation past the rack and asks what happens when a KV cache crosses a datacenter boundary. From the Mooncake authors, and the argument that the cache, not the model, is the thing worth moving.`},at={id:`eagle-3`,title:`EAGLE-3: Scaling up Inference Acceleration of Large Language Models via Training-Time Test`,authors:`Li et al.`,year:2025,url:`https://arxiv.org/abs/2503.01840`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`speculative-decoding`],why:`Drops feature prediction for direct token prediction and fuses low, middle, and high layers of the target model, so the draft head keeps improving as training data grows. The speculation baseline in vLLM, SGLang, and TensorRT-LLM.`},ot={id:`suffix-decoding`,title:`SuffixDecoding: Extreme Speculative Decoding for Emerging AI Applications`,authors:`Oliaro et al.`,year:2024,url:`https://arxiv.org/abs/2411.04975`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`speculative-decoding`],why:`Drafts from a suffix tree built over past outputs instead of a draft model, so it costs no GPU memory and gets stronger the more repetitive the traffic is. The speculation method that fits agent loops and pipelines.`},st={id:`batch-invariant-inference`,title:`Defeating Nondeterminism in LLM Inference`,authors:`Horace He and Thinking Machines Lab`,year:2025,url:`https://thinkingmachines.ai/blog/defeating-nondeterminism-in-llm-inference/`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`flashattention`,`orca`],why:`Temperature zero is not deterministic, because matmul, RMSNorm, and attention kernels change their reduction order with the batch size around them. Reproducibility turns out to be purchasable, and this is the price list.`},ct={id:`serving-benchmark-evaluation`,title:`On Evaluating Performance of LLM Inference Serving Systems`,authors:`Agrawal et al.`,year:2025,url:`https://arxiv.org/abs/2507.09019`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`orca`,`pagedattention`],why:`Catalogues the mistakes that make serving benchmarks report the wrong winner, from bad load generators to metrics averaged across phases. Read it before you trust a throughput number, including your own.`},lt={id:`microscaling-fp4`,title:`Bridging the Gap Between Promise and Performance for Microscaling FP4 Quantization`,authors:`Egiazarian et al.`,year:2025,url:`https://arxiv.org/abs/2509.23202`,homeTrack:`inference`,difficulty:`hard`,prerequisites:[`flashattention-2`,`kv-cache-survey`],why:`Explains why NVFP4's small blocks neutralize the usual outlier tricks and why MXFP4's power-of-two scales cost accuracy, then closes the gap with block-wise rotation. The paper that makes the 4-bit format choice a decision rather than a default.`},ut={id:`inference-economics`,title:`Inference economics of language models`,authors:`Erdil et al.`,year:2025,url:`https://arxiv.org/abs/2506.04645`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`orca`,`pagedattention`],why:`Models the latency and cost frontier a deployment can reach given bandwidth, batch size, and parallelism, instead of quoting one benchmark. The bridge from the kernels above to the number a business actually pays.`},Z={id:`test-time-compute`,title:`Scaling LLM Test-Time Compute Optimally can be More Effective than Scaling Model Parameters`,authors:`Snell et al.`,year:2024,url:`https://arxiv.org/abs/2408.03314`,homeTrack:`inference`,difficulty:`medium`,prerequisites:[`scaling-laws`,`speculative-decoding`],why:`Spending more compute at inference can beat spending it on a larger model, which puts the serving budget on the quality path and not only the cost path. Pair it with s1 (arXiv 2501.19393) for the simplest version of the same lever.`},Q=[{id:`ai-research`,title:`AI research`,shortTitle:`AI research`,description:`From the perceptron to the transformer and the papers that scaled it. Read the base first; every arrow points at what it unlocks.`,placements:[...o(`founding`,f,p,v,y,_,g,m,h,b,x),...o(`core`,S,C,T,w,E,D,O),...o(`frontier`,k,A,j,M,N,P,F,I,L,J,Y)]},{id:`systems`,title:`Systems`,shortTitle:`Systems`,description:`The computing papers behind networks, storage, and coordination. Start with the arguments, then the systems built on them.`,placements:[...o(`founding`,R,z,B,V,H,U,W,G,K,q,de),...o(`core`,fe,pe,me,he,ge,_e,ve),...o(`frontier`,ye,be,xe,Se)]},{id:`rl`,title:`Reinforcement learning`,shortTitle:`RL`,description:`Policy gradients to preference optimization. The chain is short and strict, so read it in order.`,placements:[...o(`founding`,Ce,we,Te),...o(`core`,je,Ee,De,Oe,ke,Ae),...o(`frontier`,J,Y,Me,Ne)]},{id:`inference`,title:`Inference engineering`,shortTitle:`Inference`,description:`Attention as a memory problem. Each paper here removes a bottleneck the previous one exposed, from tiling the score matrix to compressing the cache away entirely.`,placements:[...o(`founding`,S,T),...o(`core`,Pe,Fe,Ie,Le,Re,ze,We),...o(`frontier`,Be,Ve,He,Ue,Ge,Ke,qe,Je,Ye,Xe,Ze,Qe,$e,et,tt,nt,rt,it,X,at,ot,st,ct,lt,ut,Z)]}],$=new Map(Q.flatMap(e=>e.placements).map(({paper:e})=>[e.id,e]))}));export{i as _,a,dt as c,re as d,oe as f,te as g,ee as h,ae as i,ne as l,n as m,$ as n,ue as o,r as p,Q as r,ce as s,l as t,ie as u,t as v};